class ModInt : Comparable, Equatable {
    let _MOD = 1_000_000_007
    static func < (lhs: ModInt, rhs: ModInt) -> Bool { lhs._value < rhs._value}
    var _value: Int
    init(_ value: Int = 0) {
        if isprime(_MOD) == false { fatalError("The divisor should be prime!") }
        _value = value % _MOD
        if _value < 0 { _value = turnpos(_value, _MOD) }
    }
    func setv(newvalue: Int) {
        _value = newvalue % _MOD
        if _value < 0 { _value = turnpos(_value, _MOD) }
    }
    func getv() -> Int { _value }
    func getd() -> Int { _MOD }
    var value: Int { _value }
    func pow(_ a: Int, _ b: Int) -> Int {
        if (b == 0) { return 1 }
        if (b % 2 == 0) {
            let d = pow(a, b / 2)
            return (d * d) % _MOD
        }
        return a * pow(a, b - 1) % _MOD
    }
    func pow(_ t: Int) -> ModInt {
        if t <= 0 { return ModInt(1) }
        var a = self.pow(t >> 1)
        a *= a
        if t & 1 != 0 { a *= self }
        return a
    }
    func description() -> String { String(_value) }
}

func seq(_ start: ModInt, _ end: ModInt) -> [ModInt] {
    if start == end { return [start] }
    else {
        var result = [ModInt]()
        var temp = start
        while temp != end {
            result.append(temp)
            temp += 1
        }
        result.append(end)
        return result
    }
}
func seq(_ start: Double,_ end: Double,_ by: Double) -> [Double] {
    let length = Int(abs(round((end - start) / by)))
    var result = [Double]()
    if start >= end { for n in 0 ... length { result.append(start + by * Double(n)) } }
    else { for n in 0 ... length { result.append(start - by * Double(n)) } }
    return result
}

