func turnpos(_ x: Int, _ y: Int) -> Int {
    var nx: Int
    var ratio: Int
    switch (x) {
    case ..<0:
        nx = -1 * x
        ratio = nx / y
        return (ratio + 1) * y + x
    default: return x // 0...
    }
}
func isprime(_ x: Int) -> Bool {
    switch (x) {
    case ...1: return false
    case ...3: return true
    default:
        var n = 2
        while n * n <= x {
            if x % n == 0 { return false }
            n += 1
        }
        return true
    }
}
