//べき乗高速化
ll mpow(ll x, ll n){
	ll ans = 1;
	while(n != 0){
		if (n&1) ans = ans * x % M;
		x = x*x % M;
		n  = n >> 1;
	}
	return ans;
}

//aCbを計算
ll comb(ll a, ll b){
	if (a == 0 && b == 0) return 1;
	if (a < b || a < 0){
		return 0;
	}
	ll temp = ifac[a-b] * ifac[b] % M;
	return temp * fac[a] % M;
}

int main(){
	ll k;
	cin >> k;
	string s;
	cin >> s;
	ll l = s.size();
	fac[0] = 1;
	ifac[0] = 1;
	for(ll i = 0; i<= 2000000; i++){
		fac[i+1] = fac[i]*(i+1) % M; // n!(mod M)
		ifac[i+1] = ifac[i]*mpow(i+1, M-2) % M; // k!^{M-2} (mod M) ←累乗にmpowを採用
	}
	ll ans = 0;
	for (ll i = 0; i <= k; ++i) {
		ll count = mpow(26,i);
		count *=comb(l+k-i-1, l-1);
		count %= M;
		count *= mpow(25, k-i);
		ans += count % M;
		ans %= M;
	}
	cout << ans << endl;
    return 0;
}

