uint64_t powMod(uint64_t a, uint64_t p, uint64_t mod)
{
	uint64_t res = 1;
	while (p)
	{
		if (p & 1)
		{
			res = (res * a) % mod;
		}
		a = (a* a) % mod;
		p >>= 1;
	}
	return res;
}

uint64_t inverse(uint64_t a, uint64_t mod)
{
	return powMod(a, mod - 2, mod);
}

