const int MOD = 1e9+7;

int fat[2000007];
int inv[2000007];

int binExp(int x, int p){
	int ans = 1;
	while(p){
		if(p&1)
			ans = 1LL * ans * x % MOD;
		x = 1LL * x * x % MOD;
		p >>= 1;
	}
	return ans;
}

int comb(int a, int b){
	int up = 1LL * fat[a] * inv[b] % MOD;
	up = 1LL * up * inv[a-b] % MOD;
	return up;
}

int main(){
	ios::sync_with_stdio(false); cin.tie(0);

	fat[0] = inv[0] = 1;
	for(int i = 1; i < 2000007; i++){
		fat[i] = 1LL * fat[i-1] * i % MOD;
		inv[i] = binExp(fat[i], MOD-2);
	}

	int k; cin >> k;
	string s; cin >> s;
	int n = s.size();

	ll ans = 0;
	for(int i = 0; i <= k; i++){
		int add = 1LL * comb(n+k, i+n) * binExp(25, k-i) % MOD;
		ans = (ans + add) % MOD;
	}

	cout << ans << '\n';

	return 0;
}

