struct Factorial{
    vector<mint> fact;
    vector<mint> factinv;
    Factorial(ll n){
        fact = vector<mint>(n+1);
        factinv = vector<mint>(n+1);
        fact[0] = 1;
        REP(i,1,n+1) fact[i] = fact[i-1] * i;
        factinv[n] = fact[n].inv();
        RREP(i,1,n+1) factinv[i-1] = factinv[i] * i;
    }
    mint C(ll n, ll k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k] * factinv[k];
    }
    mint P(ll n, ll k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k];
    }
    mint H(ll n, ll k){
        if(n==0 && k==0) return 1;
        return C(n+k-1, k);
    }
};

