    ll ans=0;

    rep(i,k+1){
        ll rem=k-i;
        ll res=pow_mod(26,i)*COM(n-2+rem+1,rem)%mod*pow_mod(25,rem)%mod;
        ans+=res;
        ans%=mod;
    }
    cout<<ans<<endl;
    return 0;
}

