#include <bits/stdc++.h>
using namespace std;
using ll = long long;

constexpr long long MOD = 1e9 + 7;

vector<ll> factorials;
vector<ll> powers;

long long binExp(long long a, long long e) {
	if (e == 0) {
		return 1;
	}

	if (e % 2 == 1) {
		return (binExp(a, e - 1) * a) % MOD;
	}

	long long b = binExp(a, e / 2);
	return (b * b) % MOD;
}

long long f(long long a) {
	if (a < factorials.size()) {
		return factorials[a];
	}

	long long r = 1;
	for (long long i = 2; i <= a; ++i) {
		r = (r * i) % MOD;
	}

	return r;
}

long long inv(long long a) {
	return binExp(a, MOD - 2);
}

long long c(long long n, long long k) {
	long long a = f(n);
	long long b = inv(f(k));
	long long d = inv(f(n - k));

	return ((a * b) % MOD * d) % MOD;
}

int main() {
	ll k;
	cin >> k;

	string s;
	cin >> s;

	ll n = s.length();

	for (int i = 0; i <= (n + k); ++i) {
		factorials.push_back(f(i));
	}

	for (int i = 0; i <= k; ++i) {
		powers.push_back(binExp(25, i));
	}

	ll ans = 0;
	for (int i = n; i <= (n + k); ++i) {
		ll a = (c(n + k, i) * powers[n + k - i]) % MOD;
		ans = (ans + a) % MOD;
	}

	cout << ans;

	return 0;
}

