ll modpow( ll a, ll b ){
	if ( b == 0 ) return 1;
	if ( b == 1 ) return a;

	ll tmp = modpow( a, b/2 );
	tmp = tmp*tmp%MOD;
	if ( b % 2 == 1 ) return ((tmp%MOD)*a)%MOD;
	return tmp;
}


ll RepeatSquaring(ll N, ll P, ll M){
    if(P==0) return 1;
    if(P%2==0){
        ll t = RepeatSquaring(N, P/2, M);
        return t*t % M;
    }
    return N * RepeatSquaring(N, P-1, M);
}


