  for (int i = 0; i <= K; i++) {
    ll x = power(25, i, mod) * C(i + N - 1, i, mod) % mod * power(26, K - i, mod) % mod;
    ans = (ans + x) % mod;
  }

  cout << ans << endl;

  return 0;
}

