class Factorial {
public:
    vector<mint> fact, finv;
    Factorial(int n) : fact(n + 1, mint(1)), finv(n + 1, mint(1)) {
        for (int i = 2; i <= n; i++) {
            mint tmp(i);
            fact[i] = fact[i - 1] * tmp;
            finv[i] = finv[i - 1] / tmp;
        }
    }
    mint com(const ll &n, const ll &k) {
        if (n < k || n < 0 || k < 0)
            return mint(0);
        return fact[n] * finv[k] * finv[n - k];
    }
};

signed main() {
    mint ans = 0;
    cin >> K;
    cin >> S;
    N = S.size() + K;
    Factorial f(N);
    for (int i = S.size() - 1; i < N; i++) {
        int tmp = N - 1 - i;
        ans += modpow(25, K - tmp) * modpow(26, tmp) * f.com(N - tmp - 1, S.size() - 1);
    }
    cout << ans << endl;
}

