LL expsq(LL x, LL p, LL M) {
  LL res = 1LL;
  while (p > 0LL) {
    if (p & 1LL) {
      res = (res * x) % M;
    }
    x = (x * x) % M;
    p /= 2LL;
  }
  return res;
}

LL modinv(LL x, LL M) {
  return expsq(x, M - 2, M);
}

LL nCr_fermat(int N, int K, LL M) {
