{
	long long ans = n;
	for(int i = 2, t = sqrt(n); i<=t; i++)
	{
		if(n % i == 0) ans = (ans)/i*(i-1);
		while (n % i == 0) n/=i;
	}
	return (n-1)?(ans)/n*(n-1):ans;
}
