{
	vector<pair<int, int>> Ans;
	for(int i = 2, t = sqrt(n); i <= t; i++)
	{
		if(n % i == 0) Ans.push_back(pair<int, int>(i, 0));
		while(n % i == 0) n /= i, Ans.back().second++;
	}
	return (n-1)?Ans+pair<int, int>(n, 1):Ans;
}

