        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
    return;
}

ll com(int n, int r) {
    if (n < r) return 0;
    if (n < 0 || r < 0) return 0;
    if (r == 0 || r == n) return 1;
    return (fac[n] * finv[r]) % mod * finv[n - r] % mod;
}

ll ml_pow(ll n, ll k, int p) {
    ll y, res;

    res = 1;
    y = n;
    while (k > 0) {
        if (k % 2 == 1) {
            res = res * y % p;
        }
        y = y * y % p;
        k /= 2;
    }

    return res;
}

