    vi BM(vi s)
    {
        vi ans(1,1),res(1,1);
        ll l=0,m=1,b=0;
        for(int n=0;n<s.size();n++)
        {
            ll d=0;
            for(int i=0;i<=l;i++) d=(d+(ll)ans[i]*s[n-i])%mod;
            if(d==0) m++;
            else if(2*l<=n)
            {
                vi t=ans;
                ll c=mod-d*qpow(b,mod-2)%mod;
                while(ans.size()<res.size()+m) ans.pb(0);
                for(int i=0;i<res.size();i++)
                ans[i+m]=(ans[i+m]+c*res[i])%mod;
                l=n+1-l;res=t;b=d;m=1;
            }
            else
            {
                ll c=mod-d*qpow(b,mod-2)%mod;
                while(ans.size()<res.size()+m) res.pb(0);
                for(int i=0;i<res.size();i++)
                    ans[i+m]=(ans[i+m]+c*res[i])%mod;
                m++;
            }
        }
        return ans;
    }
