template<typename T=Int>
struct NChooseR {
    vector<T> perm;
    NChooseR(int N=1e5) : perm(N+1) {
        perm[0] = 1;
        for (int i = 1; i <= N; i++) perm[i] = perm[i-1] * T(i);
    }
    T operator()(int n, int r) {
        return perm[n] / perm[r] / perm[n-r];
    }
};
NChooseR<> ncr(1e6+10);
