long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    long long ans=1;
    for(long long i = n; i >= n-k+1; i--) {
        ans*=i;
        ans%=MOD;
    }
    ans*=finv[k];
    return ans%MOD;
}
