namespace modop {
	ll madd(ll a, ll b) {
	  return (a + b) % mod;
	}
	ll msub(ll a, ll b) {
	  return (((a - b) % mod) + mod) % mod;
	}
	ll mmul(ll a, ll b) {
	  return ((a % mod) * (b % mod)) % mod;
	}
	ll mpow(ll base, ll exp) {
	  ll res = 1;
	  while (exp) {
		if (exp % 2 == 1){
			res = (res * base) % mod;
		}
		exp >>= 1;
		base = (base * base) % mod;
	  }
	  return res;
	}
	ll minv(ll base) {
	  return mpow(base, mod - 2);
	}
	ll mdiv(ll a, ll b) {
	  return mmul(a, minv(b));
	}
}

using namespace modop;

ll fact[2000005], ifact[2000005];

ll nck(ll n, ll k) {
  ll dem = (ifact[k] * ifact[n - k]) % mod;
  return (fact[n] * dem) % mod;
}

void solve() {
  ll n; string s; cin >> n >> s;
  ll k = s.length();

  ll tot = mpow(26, n + k);

  fact[0] = fact[1] = ifact[0] = ifact[1] = 1;
  f1r(i, 2, n + k + 3) {
    fact[i] = (fact[i - 1] * i) % mod;
    ifact[i] = minv(fact[i]);
  }

  ll sub = 0;
  f0r(i, k) {
    ll pos = mpow(25, n + k - i);
    pos = (pos * nck(n + k, i)) % mod;
    sub = (sub + pos) % mod;
  }

  cout << msub(tot, sub) << '\n';
}

