constexpr std::int64_t kModulus = 1000000007;

std::int64_t ExtendedGCD(std::int64_t a, std::int64_t b,
                         std::int64_t& x, std::int64_t& y) {
  auto c = a;
  if (b == 0) {
    x = 1;
    y = 0;
  } else {
    c = ExtendedGCD(b, a % b, y, x);
    y -= a / b * x;
  }
  return c;
}

std::int64_t Inverse(std::int64_t n) {
  std::int64_t x, y;
  ExtendedGCD(n, kModulus, x, y);
  return (x % kModulus + kModulus) % kModulus;
}

int main() {
