  }
  const auto ratio_count = Inverse(26) * 25 % kModulus;
  std::int64_t combination = 1;
  std::int64_t sum = 0;
  for (int i = 0; i <= K; ++i) {
    sum = (sum + combination * count) % kModulus;
    count = count * ratio_count % kModulus;
    auto delta_combination = combination * (N - 1) % kModulus * Inverse(i + 1) % kModulus;
    combination = (combination + delta_combination) % kModulus;
  }
  std::cout << sum << std::endl;
  return 0;
}

