const ll MOD = 1000000007;

ll modmul(ll a, ll b) {
    return (a*b) % MOD;
}

ll modpow(ll a, ll exp) {
    if(exp == 0) return 1;

    ll t = modpow(a, exp / 2);
    if(exp % 2) return t*t % MOD * a%MOD;
    return t*t % MOD;
}

ll modinv(ll n) {
    return modpow(n, MOD-2);
}

ll choose(ll n, ll k) {
    return modmul(fac[n], modmul(modinv(fac[n-k]), modinv(fac[k])));
}

