/* Iterative Function to calculate (x^y)%p 
in O(log y) */
unsigned long long power(unsigned long long x, 
						ll y, int p) 
{ 
	unsigned long long res = 1; // Initialize result 

	x = x % p; // Update x if it is more than or 
	// equal to p 

	while (y > 0) { 
		// If y is odd, multiply x with result 
		if (y & 1) 
			res = (res * x) % p; 

		// y must be even now 
		y = y >> 1; // y = y/2 
		x = (x * x) % p; 
	} 
	return res; 
} 
