    ModInt pow(ll t) const {
        if (!t) return 1;
        ModInt a = pow(t / 2);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }
    ModInt inv() const {
        return pow(mod - 2);
    }
    ModInt &operator/= (const ModInt &a) {
        return (*this) *= a.inv();
    }
    ModInt operator/ (const ModInt &a) const {
        ModInt res(*this);
        return res /= a;
    }
    friend ostream &operator<< (ostream &os, const ModInt &a){
        os << a.x;
        return os;
    }
};

vector<ModInt> fact, ifact;
void init(int N) {
    ModInt now(1);
    fact.push_back(now);
    for (int i = 1; i <= N; ++i) {
        ModInt M(i);
        now *= M;
        fact.push_back(now);
    }
    rep(i, N + 1) ifact.push_back(fact[i].inv());
}
ModInt comb(int x, int y) {
    if (x < y) return ModInt{0};
    else return fact[x] * ifact[y] * ifact[x - y];
}

int main() {
