    ModInt ans(0), A(25), B(26);
    init(N + K);
    rep(i, K + 1) {
        ans += comb(N + K - i - 1, N - 1) * A.pow(K - i) * B.pow(i);
    }
    cout << ans << "\n";
    return 0;
}

