vector<ll> fact, ifact, invs;
ll combmod(int n, int k, ll MOD, int M = 1e5){
    if (!fact.size()){
        fact.resize(M+1); ifact.resize(M+1); invs.resize(M+1);
        fact[0] = ifact[0] = invs[0] = fact[1] = ifact[1] = invs[1] = 1;
        for(int i = 2; i <= M; i++){
            fact[i] = fact[i-1] * i % MOD;
            invs[i] = MOD - MOD / i * invs[MOD % i] % MOD;
            ifact[i] = ifact[i-1] * invs[i] % MOD;
        }
    }
    return fact[n] * ifact[k] % MOD * ifact[n-k] % MOD;
}

template<class T> T powmod(T x, ll n, ll m)
{
    T r = 1;
    T a = x % m;
    while (n>0)
    {
        if (n & 1)
            r = (r*a)%m;
        a = (a*a)%m;
        n = n >> 1;
    }
    return r;
}

