#include <bits/stdc++.h>
using namespace std;
const uint64_t MOD = 1000000007;

uint64_t power_s(uint32_t a, uint32_t p, uint64_t M){
    if( p < 3){
        uint64_t ans = 1;
        while(p--){
            ans =  (ans * a) % M;
        }
        return ans;
    }else{
        uint64_t half_ans = power_s(a, p/2, M);
        uint64_t ans = (half_ans * half_ans) % M;
        if( p % 2 == 1){
            ans = ( a * ans) % M;
        }
        return ans;
    }
}

uint64_t combination(uint32_t m, uint32_t n, uint64_t M){
    //choose m objects from n set object
    uint64_t ans = 1;
    for(uint32_t i = 1 ; i <= m ; i++){
        //assuming M prime
        uint64_t inverse_mod = power_s(i, M - 2, M);
        ans = (ans * ( n + 1 - i)) % M;
        ans = (ans * inverse_mod) % M;
    }
    return ans;
}

void solve(){

    uint32_t K;
    cin >> K;
    std::string S;
    cin >> S;
    uint32_t last_position = S.size();
    K = K + S.size();
    uint64_t count = 0;

    for(; last_position <= K ; last_position++){
        uint64_t last_choices = power_s(26, K - last_position, MOD);
        uint64_t reposition_choices = combination(S.size() - 1, last_position - 1, MOD);
        uint64_t completion_choices = power_s(25, last_position - S.size(), MOD);
        uint64_t overall_choices = (last_choices * reposition_choices) % MOD;
        overall_choices = (overall_choices * completion_choices) % MOD;
        count = (count + overall_choices) % MOD;
    }
    cout << count << endl;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    return 0;
}

