        // snの位置は右端、残りのn-1個の並べ方
        mint sum = comb(snlen-1, slen-1);
        sum *= wl.pow(k-rest);
        sum *= wr.pow(rest);
        ans += sum;
    }
    cout << ans << endl;
}

