    long long res = 0;
    for(int i = 0; i < siz; i++){
        res = res + COM(siz + K, i) * mod_pow(25, siz + K - i) % MOD;
        res %= MOD;
    }
    long long ans = (mod_pow(26, siz + K) - res + MOD) % MOD;
    cout << ans << endl;
}

