ll qp(ll a,ll b){
    ll res=1;
    a%=mod;
    if(a==0)return 0;
    while(b){
        if(b&1){
            res=res*a%mod;
        }
        a=a*a%mod;
        b>>=1;
    }
    return res%mod;
}

void prepare(){
    fun[0]=fun[1]=1;
    for(int i=2;i<maxn;++i){
        fun[i]=fun[i-1]*i%mod;
    }
    infun[maxn-1]=qp(fun[maxn-1],mod-2);
    for(int i=maxn-2;i>=0;--i){
        infun[i]=infun[i+1]*(i+1)%mod;
    }
}

ll C(ll n,ll m){
    if(n<0||m<0||n<m)return 0;
    ll res = fun[n];
    res = res*infun[m]%mod;
    res = res*infun[n-m]%mod;
    return res;
}

