	vector<long long int>rev(N + s.size() + 1, 1);
	for (int i = 2; i <= N + s.size(); i++) {
		by[i] = by[i - 1] * i%MOD;
	}
	rev[N + s.size()] = power(by[N + s.size()], MOD - 2, MOD);
	for (int i = N + s.size() - 1; i > 1; i--) {
		rev[i] = rev[i + 1] * (i + 1) % MOD;
	}
	long long int sum = 0;
	long long int ans = 0;
	for (int i = s.size(); i <= N + s.size(); i++) {
		long long int add = by[i] * rev[s.size()] % MOD*rev[i - s.size()] % MOD;
		long long int box = add;
		add += MOD - sum;
		add %= MOD;
		ans += add * power(26, N + s.size() - i, MOD) % MOD*power(25, N - (N + s.size() - i), MOD) % MOD;
		ans %= MOD;
		sum = box;
	}
	cout << ans << endl;
}

