    const long long A = 26;

    auto calc = [&](int N, int M) {
        long long res = nCr(N - 1, M - 1);
        res *= powM(A - 1, N - M);
        res %= MOD;
        return res;
    };

    long long res = 0;
    long long P = 1;
    for (int i = K; i >= 0; --i) {
        (res += calc(n + i, n) * P % MOD) %= MOD;
        // cout << i + n << " " <<  " " << calc(n + i, n) << endl;
        (P *= A) %= MOD;
    }

    cout << res << '\n';

    return 0;
}

