const int64_t MOD = 1000000007;
int64_t ff[2000006];

int64_t fact(int n) {
  if (n == 0) return 1;
  if (n == 1) return 1;
  if (ff[n] != 0) return ff[n];
  ff[n] = (fact(n-1) * n) % MOD;
  return ff[n] % MOD;
}

int64_t pm(int64_t a, int64_t b) {
  if (b == 0) return 1;
  if (b == 1) return a % MOD;
  int64_t v = pm(a, b/2) % MOD;
  v = v * v % MOD;
  if (b % 2) {
    return v * a % MOD;
  }
  return v;
}

