{
    parent[v]=v;
	sz[v]=1;
}
int find_set(int v)
{
    if(parent[v]==v)
        return v;
    else
        return parent[v] = find_set(parent[v]);
}
void union_sets(int a,int b)
{
	//trace(a,b);
    a = find_set(a);
    b = find_set(b);
	//trace(a,b);
    if(a==b)
        return;
	if(sz[a] < sz[b])
	{
		swap(a,b);
	}
	sz[a] += sz[b];
    parent[b] = a;
    return;
}
