inline ll exp(ll b, ll e) {
    ll ret = 1;
    while(e) {
        if(e&1) ret = (ret * b) % MOD;
        b = (b * b) % MOD;
        e /= 2;
    }
    return ret;
}
inline ll nCr(int n, int r) {
    return (((F[n] * IF[r]) % MOD) * IF[n - r]) % MOD;
}
