const int N = 2e6 + 5;
long long inv[N], fact[N], ifact[N];
void pre()
{
	inv[1] = fact[0] = fact[1] = ifact[0] = ifact[1] = 1;
	for (int i = 2; i < N; i++)
	{
		inv[i] = mul(MOD - MOD / i, inv[MOD % i], MOD);
		fact[i] = mul(i * 1ll, fact[i - 1], MOD);
		ifact[i] = mul(inv[i], ifact[i - 1], MOD);
	}
	return;
}
long long nCr(long long n, long long r)
{
	if (n >= 0 && r >= 0 && n >= r)
		return mul(fact[n], mul(ifact[r], ifact[n - r], MOD), MOD);
	return 0;
}
long long binpow(long long x, long long y, long long m)
{
	long long res = 1;
	x %= MOD;
	while (y)
	{
		if (y & 1)
			res = mul(res, x, m);
		y = (y >> 1);
		x = mul(x, x, m);
	}
	return res;
}
void solve(int tc)
{
