	cin >> k;
	string s;
	cin >> s;
	int n = s.length();
	pre();
	ll ans = binpow(26, n + k, MOD);
	ll sum = 0;
	for (int i = 0; i < n; i++)
	{
		ll tmp = nCr(n + k, i);
		tmp = mul(tmp, binpow(25, n + k - i, MOD), MOD);
		sum = add(sum, tmp, MOD);
	}
	ans = add(ans, MOD - sum, MOD);
	cout << ans << ln;
	return;
}

