	ll sum = 0;
	for(int i=n;i<=m;i++)
	{
		sum = (sum + C(i-1,n-1) * power(25,i-n)%MOD * power(26,m-i)%MOD)%MOD;
	}
	cout<<sum<<endl;
	return 0;
}

