using namespace std;
typedef long long ll;

#define MOD 1000000007

class Combination
{
	vector<ll> fact;	//n!
	vector<ll> finv;	//n!の逆元
public:Combination(int n)
{
	vector<ll> inv(n + 1, 1);	//iの逆元
	fact.resize(n + 1, 1);
	finv.resize(n + 1, 1);
	for (int i = 2; i <= n; ++i) {
		fact[i] = fact[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

public:ll cmb(int n, int k)
{
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fact[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
};


int main()
{
	int K; cin >> K;
	string S; cin >> S;
	int len = K + S.size();
	Combination cmb = Combination(len);
	vector<ll> pow25(K + 1, 1), pow26(K + 1, 1);
	for (int i = 0; i < K; ++i) {
		pow25[i + 1] = pow25[i] * 25 % MOD;
		pow26[i + 1] = pow26[i] * 26 % MOD;
	}

	ll ans = 0;
	ll buf;
	//k文字を最後に置く。26**k通り
	//最後のk文字の前に固定の一文字
	//残りの文字の置き場所の選び方 cmb(len-k-1, S.size()-1) * 25**(K-k)
	for (int k = 0; k <= K; ++k) {
		//ans = ans + cmb.cmb(len - k - 1, S.size() - 1) * modpow(25, K - k) * modpow(26, k);
		buf = cmb.cmb(len - k - 1, S.size() - 1) * pow25[K - k] % MOD;
		buf = buf * pow26[k] % MOD;
		ans = (ans + buf) % MOD;
	}
	cout << ans << endl;
}

