ll fact[N], invfact[N];

ll modinv(ll k) { return powmod(k, MOD - 2, MOD); }

void precompute() {
    fact[0] = fact[1] = 1;
    for(ll i = 2; i < N; i++) {
        fact[i] = fact[i - 1] * i;
        fact[i] %= MOD;
    }
    invfact[N - 1] = modinv(fact[N - 1]);
    for(ll i = N - 2; i >= 0; i--) {
        invfact[i] = invfact[i + 1] * (i + 1);
        invfact[i] %= MOD;
    }
}

ll nCr(ll x, ll y) {
