	r *= r;
	r %= MOD;
	if(n % 2 == 1) r *= a;
	return r % MOD;
}

ll Cnm(ll n, ll m){
	return (((((fs[n] * ifs[m]) % MOD + MOD)%MOD) * ifs[n-m])%MOD + MOD)%MOD;
