const static int MOD = 1000000007;
ull RepeatSquaring(ull N, ull P){
	if(P == 0 || N == 1) return 1;
	if(N == -1) return P & 1 ? -1 : 1;
	if(!(P & 1)){
		ull t = RepeatSquaring(N, P >> 1);
		return t*t %MOD;
	}
	//Pが偶数のときN^(P/2)を求めてからそれの2乗を返す
	return N*RepeatSquaring(N, P - 1) % MOD;
	//Pが奇数のときN^((P - 1)/2)を求めてからそれの2乗を返す
}

/*
組合せ(nCr)
O(min(r, n - r) + log(MOD))
*/
ull Combination(ull n, ull r){
	if(n - r < r) r = n - r;
	ull numerator = 1, denominator = 1;
	for (ull i = 0; i < r; ++i){
		numerator = numerator*((n - i) %MOD) %MOD;
		denominator = denominator*((i + 1) %MOD) %MOD;
	}
	return numerator*RepeatSquaring(denominator, MOD-2) %MOD;
}

