  Combination(int n) : fact(n+1){
    fact[0] = fact[1] = 1;
    for(int i = 2; i <= n; i++){
      fact[i] = fact[i-1] * i % MOD;
    }
  }

  int nCr(int n, int r){ // nCr = n!/r!(n-r)!
    if(n < r) return 0;
    return fact[n] * inv(fact[r]*fact[n-r]%MOD) % MOD;
  }

  int inv(int n, int p = MOD-2){ // a/n ≡ a*n^(p-2) nとpは互いに素
    int r = 1;
    for(; p > 0; p >>= 1){
      if(p & 1LL) r = r * n % MOD;
      n = n * n % MOD;
    }
    return r; // r = n^p % MOD
  }
};

signed main(){

  int k; cin >> k;
  string s; cin >> s;

  Combination c(2e6);
  int n = s.size(), ans = 0;
  for(int i = 0; i <= k; i++){
    ans = (ans + c.nCr(n-1+i, i) * c.inv(25, i) % MOD * c.inv(26, k-i)) % MOD;
  }
  cout << ans << endl;

  return 0;
}

