ll mod = 1e9+7;

ll binomialCoefficients(ll n, ll k) {
   ll C[k+1];
   memset(C, 0, sizeof(C));
   C[0] = 1;
   for (ll i = 1; i <= n; i++) {
      for (ll j = min(i, k); j > 0; j--)
         C[j] = (C[j] + C[j-1]) % mod;
   }
   return C[k] % mod;
}

//all positive in our case
ll powermod(ll n, ll e) {
    if(e==0) {
        return 1l;
    }
    if(e==1) {
        return n;
    }
    ll res = (powermod(n, e/2)*powermod(n, e/2))%mod;
    if(e%2==1)
        res*=n;
    res = res % mod;
    return res;
}

int main(int argc, char * argv[]) {
    ios_base::sync_with_stdio(false);
