vector<ll> DecToBinary(ll num,ll trailing_zero, ll nbits)
{
    vector<ll> bits;
    while(num > 0)
    {
        bits.push_back(num%2);
        num /= 2;
    }

    if(trailing_zero == 1)
    {
        while(bits.size() < nbits)
        {
            bits.push_back(0);
        }
    }

    return bits;
}

long long int BinaryToDec(vector<ll> bits)
{
    ll number = 0;
    ll i;
    for(i=bits.size()-1;i>=0;i--)
    {
        number += (bits[i] * (long long)pow((ll)2 , i));
    }
    return number;
}

unsigned long long modular_exponentiation(unsigned long long  base, unsigned long long  power)
{
    unsigned long long  ans = 1;
    base = base % M;
    while (power > 0)
    {
        if (power & 1)
        {
            ans = (ans * base) % M;
        }

        power /= 2;
        base = (base * base) % M;
    }
    return ans;
}

