ll power(ll n, ll r, ll mod){
    ll ans = 1;
    while(r > 0){
        if((r & 1) == 1){
            ans = ans * n % mod;
        }
        n = n * n % mod;
        r >>= 1;
    }
    return ans % mod;
}

ll comb(ll n, ll r, ll mod){
    ll x[n+1], y[n+1];
    x[0] = 1;
    for(int i = 1; i <= n; i++) x[i] = x[i-1] * i % mod;
    y[n] = power(x[n], mod-2, mod);
    for(int i = n; i >= 1; i--) y[i-1] = y[i] * i % mod;
    return ((x[n] * y[r]) % mod) * y[n-r] % mod;
}

