    fat[0] = 1;
    for(int i = 1; i < MAXN; ++i)
        fat[i] = mul(i, fat[i - 1]);

    ifat[MAXN - 1] = fexp(fat[MAXN - 1], MOD - 2);

    for(int i = MAXN - 2; i >= 0; --i)
        ifat[i] = mul(i + 1, ifat[i + 1]);
}

int comb(int n, int r) { 
