using ll = long long;
const int maxn = 2e6 + 555;
const int MOD = 1e9 + 7;
ll xpow(ll a, ll b) {
    ll ret = 1;
    a %= MOD;
    assert(b >= 0);
    while (b) {
        if (b & 1)
            ret = ret * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return ret;
}
int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cout.precision(10);
    cout << fixed;
    static ll inv[maxn + 555], invp[maxn + 555], p[maxn + 555];
    inv[1] = 1;
    for (int i = 2; i <= maxn; i++)
        inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
    p[0] = 1;
    for (int i = 1; i <= maxn; i++)
        p[i] = p[i - 1] * i % MOD;
    invp[0] = 1;
    for (int i = 1; i <= maxn; i++)
        invp[i] = invp[i - 1] * inv[i] % MOD;
    auto C = [&](int a, int b) -> ll {
        if (a < b)
            return 0;
        else
            return p[a] * invp[b] % MOD * invp[a - b] % MOD;
    };
    int n;
    string s;
    cin >> n >> s;
    ll ans = 0;
    int tot = n + (int)s.size();
    for (int i = (int)s.size(); i <= tot; i++) {
        //枚举放i个a，剩下地方放b..z
        (ans += C(tot, i) * xpow(25, tot - i)) %= MOD;
    }
    cout << ans << endl;
    return 0;
}

