template<typename T>
void add_self(T& a, T b)
{
	a += b;
	if(a > mod)
	{
		a -= mod;
	}
}

template<typename T>
void substract_self(T& a, T b)
{
	a -= b;
	if(a < 0)
	{
		a += mod;
	}
}

template<typename T>
long long mul(T a, T b)
{
	return (a * b) % mod;
}

long long power(long long a, long long b)
{
	long long res = 1ll;
	while(b)
	{
		if(b & 1)
		{
			res = (res * a) % mod;
		}
		a = (a * a) % mod;
		b >>= 1;
	}
	return res;
}

long long modInverse(long long a)
{
	return power(a, (long long)(mod - 2));
}

long long nCr(long long n, long long r)
{
	long long val = mul(fact[n], mul(modInverse(fact[n - r]), modInverse(fact[r])));
	return val;
}

