const long long modConst = 1E9 + 7;

long long facMemo[2000005];
long long fastExp(long long A, long long B)
{
	if(B == 0)
		return 1 % modConst;

	long long Sqrt = fastExp(A, B / 2), ans = (Sqrt * Sqrt) % modConst;
	if(B % 2 == 1)
		ans *= A % modConst;

	return ans % modConst;
}

long long modInverse(long long int X)
{
	return fastExp(X, modConst - 2);
}

long long choose(int N, int R)
{
	long long ans = (facMemo[N] * modInverse(facMemo[N - R])) % modConst;
	ans = (ans * modInverse(facMemo[R])) % modConst;

	return ans;
}

long long starsAndBars(long long stars, long long bars)
{
	return choose(stars + bars, stars);
}

