const ll MOD = 1e9 + 7;
const ll max_n = 1010101;
ll fact[max_n];
bool fact_init = false;

ll powmod(ll a, ll b){
	if(b == 0) return 1;
	if(b % 2 == 1) return a * powmod(a, b - 1) % MOD;

	ll d = powmod(a, b / 2) % MOD;
	return d * d % MOD;
}

ll comb(ll n, ll k){
	if(!fact_init){
		fact[0] = 1;
		fact[1] = 1;

		for(ll i = 2; i < max_n; i++){
			fact[i] = fact[i-1] * i;
			fact[i] %= MOD;
		}

		fact_init = true;
	}

	ll ret = fact[n];
	ret *= powmod(fact[k],MOD-2);
	ret %= MOD;
	ret *= powmod(fact[n-k],MOD-2);
	ret %= MOD;
	return ret;

	// X^(-1) = X^(p-2) (mod p) (Fermat's little theorem)
}

