    ll ans =mod_pow(26ll,K+N,MOD);

    COMinit();
    for(ll i=0;i<N;i++){
        ll minus =COM(K+N,i)*mod_pow(25ll,K+N-i,MOD);
        minus %= MOD;
        ans = ans + MOD -minus;
        ans %=MOD;
    }
    cout << ans << endl;

}

