ll B(ll x){
  ll res = 1, k = MOD - 2, y = x;
  while(k){
    if(k&1){
      res *= y;
      res %= MOD;
    }
    y *= y;
    y %= MOD;
    k >>= 1;
  }
  return res;
}

void init(int n){
  memo1[0] = 1;
  for(ll i = 1; i < 202020; i++) memo1[i] = (memo1[i-1] * i) % MOD;
  for(ll i = 0; i < 202020; i++) memo2[i] = B(memo1[i]);
}

ll C(ll n, ll r){
  ll a = memo1[n];
  ll b = memo2[r];
  ll c = memo2[n-r];
  ll res = a * b;
  res %= MOD;
  res *= c;
  res %= MOD;
  return res;
}

ll BB(ll x, ll y){
  ll res = 1;
  while(y){
    if(y&1){
      res *= x;
      res %= MOD;
    }
    x *= x;
    x %= MOD;
    y >>= 1;
  }
  return res;
}
