int64 gcd(int64 a, int64 b){
	while (a != 0 && b != 0){
		if (b > a)
			b %= a;
		else
			a %= b;
	}

	return a + b;
}

int64 minFactor(int64 x){
	for (int64 i = 2; i * i <= x; ++i)
		if (x % i == 0)
			return i;

	return x;
}

int64 allFactors(int64 x, vint64 &prms, vint64 &prm_cnt){
	prms.clear();
	prm_cnt.clear();
	while (x > 1){
		int64 t = minFactor(x);
		prms.push_back(t);
		int s = prms.size() - 1;
		prm_cnt.push_back(0);
		while (x % t == 0){
			x /= t;
			++prm_cnt[s];
		}
	}

	return 0;
}

#define MOD (int64)(1000000007)

int64 add(int64 x, int64 y){
	return ((x % MOD) + (y % MOD)) % MOD;
}

uint64 mul(uint64 x, uint64 y){
	if (y == 0 || x == 0)
		return 0;

	if (y % 2 == 0){
		int64 k = mul(x, y / 2);
		return (k * 2) % MOD;
	}
	else
		return (x + mul(x, y - 1)) % MOD;
}

int64 pow_(int64 x, int64 y){
	if (y == 0)
		return 1;
	if (y % 2 == 0){
		int64 k = pow_(x, y / 2);
		return (k * k) % MOD;
	}
	else
		return (x * pow_(x, y - 1)) % MOD;
}


int main(){

	ios_base::sync_with_stdio(0);
	cin.tie();

	int k;
	string s;

	cin >> k >> s;
	vint64 fact(2 * ((int)1e6 + 2));
	fact[0] = 1;
	fact[1] = 1;

	for (int i = 2; i <= 1e5; ++i){
		fact[i] = (fact[i - 1] * i) % MOD;
		//if (i < 20) cout << fact[i] << endl;
	}

	vint64 revfact(fact.size());
	fori(1e5 + 1)
		revfact[i] = pow_(fact[i], MOD - 2);

	int n = s.length() + k;
	int64 total = pow_(26, n);
	int64 sum = 0;
	for (int i = 0; i < s.length(); ++i){
		int64 t = pow_(25, n - i);
		int64 comb = mul(fact[n], mul(revfact[i], revfact[n - i]));
		sum = add(sum, mul(t, comb));
	}

	int64 res = total - sum;
	while (res < 0) res += MOD;

	cout << res << endl;
	return 0;
}

