ll modinv(ll a, ll mod) {
    ll b = mod, u = 1, v = 0;
    while(b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= mod;
    if (u < 0) u += mod;
    return u;
}

vector<ll> mif(MAX_NUM, -1);
ll modinvfac(ll n, ll mod) {
    if (mif[n] != -1) return mif[n];
    if (n == 0) return mif[0] = 1;
    return mif[n] = modinv(n, mod) * modinvfac(n-1, mod) % mod;
}

ll modcomb(ll n, ll k, ll mod) {
    return modfac(n, mod) * modinvfac(k, mod) % mod * modinvfac(n-k, mod) % mod; 
}

ll modpow(ll a, ll n, ll mod) {
    ll res = 1;
    while (n) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

