//Using binary exponentiation to calculate x^n in log(n) time.
int binExp(int base, int power)
{
    int x = 1;
    while(power)
    {
        if(power%2 == 1)
            x = ((x % mod) * (base % mod) * 1LL) % mod;
        base  = ((base % mod) * (base % mod) * 1LL) % mod;
        power = power / 2;
    }
    return x;
}

int facto(int num)
{
    int result = 1;
    for(int i=1; i<=num; ++i)
    {
        result = ((result % mod) * (i % mod) * 1LL) % mod;
    }
    return result;
}

