struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) { (x *= a.x) %= mod; return *this;}
  mint operator+(const mint a) const { return mint(*this) += a;}
  mint operator-(const mint a) const { return mint(*this) -= a;}
  mint operator*(const mint a) const { return mint(*this) *= a;}
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod-2);}
  mint& operator/=(const mint a) { return *this *= a.inv();}
  mint operator/(const mint a) const { return mint(*this) /= a;}
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

struct combination {
  vector<mint> fact, ifact;
  combination(int n):fact(n+1),ifact(n+1) {
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
  }
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n]*ifact[k]*ifact[n-k];
  }
};

void solve(long long K, std::string S){
    ll N = S.size();
    /*
    まずは|S|+Kの長さの文字列Uが何通りあるか計算
    そこから余事象としてSが含まれないものの通り数を引いていく。
    Sが含まれないとは、丁度n文字目まで含まれ、n+1文字目が含まれないという条件でMECEに分割可能
    例えば、S= "abc"だっととして、Uの部分文字列にaがありbが現れない場合、abがありcが現れない場合....
    例えばabまで現れる場合を考える。最初にその出現位置を決めると、
    文字列は(xxxx,a,yyyy,b,zzzz)となるが、xにaが含まれないこと、yにbが含まれないこと、zにcが含まれないことが
    条件となる。
    これを一般化させるとk文字目まで含まれる部分文字列の候補はcombination(|S|,k)*pow(25,部分文字列以外の部分の長さ)
    となる。
    */
    mint ans = mint(26).pow(N+K);
    combination com = combination(int(1e6)*2+5);
    //
    for(ll i=0;i<N;i++){
        ans -=com(K+N,i)*(mint(25).pow(K+N-i));
    }
    cout << ans << endl;

}

