int main()
{
	int k;
	string s;

	cin >> k >> s;

	vector<int64_t> pow25(1000000+1);
	vector<int64_t> pow26(1000000+1);
	pow25[0]=1;
	pow26[0]=1;
	for (int i=1;i<=1000000;++i)
	{
		pow25[i]=pow25[i-1]*25;
		pow25[i]%=combination_modulo;
		pow26[i]=pow26[i-1]*26;
		pow26[i]%=combination_modulo;
	}
	prepare_combination_mod();

	int l=s.size();
	int64_t combi=0;
	for (int i=l;i<=l+k;++i)
	{
		int64_t c=1;
		c*=pow25[i-l];
		c%=combination_modulo;
		c*=pow26[l+k-i];
		c%=combination_modulo;
		c*=combination_mod(i-1,l-1);
		c%=combination_modulo;
		combi+=c;
		combi%=combination_modulo;
	}
	cout << combi << endl;
}

int prepare_combination_mod()
{
	factorials[0]=1;
	factorials[1]=1;
	factorials_inv[0]=1;
	factorials_inv[1]=1;
	inverse[1]=1;
	for (int i=2;i<combination_max;++i)
	{
		factorials[i]=factorials[i-1]*i%combination_modulo;
		inverse[i]=combination_modulo - inverse[combination_modulo%i]*(combination_modulo/i)%combination_modulo;
		factorials_inv[i]=factorials_inv[i-1]*inverse[i]%combination_modulo;
	}
	return 0;
}

int combination_mod(int n, int k)
{
	return factorials[n]*(factorials_inv[k]*factorials_inv[n-k]%combination_modulo)%combination_modulo;
}

