ll mod(ll x, ll M)
{
    ll res = x % M;
    return (res >= 0 ? res : res + M);
}

ll powmod(ll x, ll n, ll M)
{
    if(n == 0) return 1%M;
    ll half = powmod(x, n/2, M);
    if(n % 2 == 0) return (half*half)%M;
    return (((half*half)%M)*x)%M;
}

ll modinv(ll a, ll M)
{
    ll x = a, y = M;
    ll sx = 1, tx = 0;
    ll sy = 0, ty = 1;

    while(y != 0) {
        ll q = x/y;
        ll r = x%y;
        ll nsx = sy;
        ll ntx = ty;
        sy = sx - q*sy;
        ty = tx - q*ty;
        sx = nsx; tx = ntx;
        x = y; y = r;
    }

    if(sx < 0) sx += M;
    return sx;
}

