int modoMulti(int a, int b, int mod) 
{ 
    int res = 0; 

    a %= mod; 

    while (b) 
    { 
        if (b & 1) 
            res = (res + a) % mod; 
        a = (2 * a) % mod; 
        b >>= 1;  
    } 

    return res; 
} 


void factorial(int x)
{
    while(fact.size() <= x)
    {   
        fact.push_back(modoMulti(fact[fact.size() - 1], fact.size(), mod));
    }
}


int modInverse(int a, int m) 
{ 
    int m0 = m; 
    int y = 0, x = 1; 

    if (m == 1) 
      return 0; 

    while (a > 1) 
    { 

        int q = a / m; 
        int t = m; 

        m = a % m, a = t; 
        t = y; 

        y = x - q * y; 
        x = t; 
    } 

    if (x < 0) 
       x += m0; 

    return x; 
} 


int pow(int x, int e) 
{
    if (e < 0) 
    {
        x = modInverse(x, mod);
        e *= -1;
    }
    if (e == 0)
        return 1;
    if ((e & 1) > 0)
        return modoMulti(x, pow(x, e - 1), mod);

    return pow(modoMulti(x, x, mod), e / 2);
}


int bino(int n, int r) 
