// calculating factorial 
void cal_fact()
{
    fact[0] = 1;
    for (int i = 1; i < MS; i++)
    {
        fact[i] = i * fact[i - 1];
        fact[i] %= mod;
    }
}
// modular exponentiation 
ll binpow(ll val, ll deg, ll mod)
{
    if (!deg)
        return 1 % mod;
    if (deg & 1)
        return binpow(val, deg - 1, mod) * val % mod;
    ll res = binpow(val, deg >> 1, mod);
    return (res * res) % mod;
}

ll cal_c(ll n, ll i)
{
    ll res = fact[n]; 
    ll div = fact[n - i] * fact[i];
    div %= mod;
    // using fermat little theorum
    div = binpow(div, mod - 2, mod); // modular inverse  
    return (res * div) % mod; 
}

