long long modMult(long long a, long long b, long long m) {
    long long res = 0;
    long long exp = a % m;
    while (b) {
        if (b & 1) {
            res += exp;
            if (res > m) res -= m;
        }
        exp <<= 1;
        if (exp > m) exp -= m;
        b >>= 1;
    }
    return res;
}
long long powMod(long long a, long long b, long long m) {
    long long res = 1;
    long long exp = a % m;
    while (b) {
        if (b & 1) res = modMult(res, exp, m);
        exp = modMult(exp, exp, m);
        b >>= 1;
    }
    return res;
}
