const int MOD = 1e9+9;
const int MAX = 2e6;

// a^n mod.p を計算する（二分累乗法）ただしpは素数
long long modpow(long long a, long long n, long long p) {
    long long res = 1;
    while (n) {
        if (n & 1) res = res * a % p;
        a = a * a % p;
        n >>= 1;
    }
    return res;
}

// nCk mod.MOD を求める方法1　ただしpは素数 p > n
// p = (p/a) * a + (a%b) を変形すると a^(-1) = -(p%a)^(-1) * (p/a)
long long fac[MAX], finv[MAX], inv[MAX];
// 前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1; // mod.MODにおける1,2,…,nの逆元
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD; // iの逆元をMOD/iの逆元を利用して求める
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
// 二項係数の計算
long long COM(int n, int k){
    if (n < 0 || k < 0 || n < k) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(){
    int n; cin >> n;
    string s; cin >> s;
    int k = s.length();

    ll ans = 0;
    COMinit();

    for(int i=k; i<=n+k; i++){ // (i-1 C k-1) * (25^(i-k)) * (26^(n+k-i)) を数え上げる
        ll num = ((COM(i-1, k-1) % MOD) * modpow(25, i-k, MOD) % MOD) * modpow(26, n+k-i, MOD) % MOD;
        ans += num;
        ans %= MOD;
    }

    cout << ans << endl;
}

