ll modinv(ll a, ll m) {
  ll b = m, u = 1, v = 0;
  while(b) {
    ll t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}

ll combination(ll n, ll r){
  ll num = 1;
  for(int i = 1; i <= r; i++){
      num = num * (n - i + 1) % MOD;
      num = num * modinv(r - i + 1, MOD) % MOD;
  }
  return num;
}

ll modpow(ll a, ll n) {
  ll res = 1;
  while(n > 0) {
    if (n & 1) res = res * a % MOD;
    a = a * a % MOD;
    n >>= 1;
  }
  return res;
}

