typedef long long lli;
lli mod = 1e9 + 7, func[2000050];
lli mypow(lli x, lli y)
{
	lli res = 1, tmp = x;
	while(y)
	{
		if(y & 1) res = (res * tmp) % mod;
		tmp = (tmp * tmp) % mod;
		y >>= 1;
	}
	return res;
}
lli C(lli n, lli m)
{
	if(n * m == 0 || n == m) return 1;
	if(m == 1) return n;
	lli one = func[n];
	lli two = mypow(func[n - m], mod - 2);
	lli three = mypow(func[m], mod - 2);
	return ((one * two) % mod * three) % mod;
}
int main()
{
