	for(int i=str.size(); i <= a + str.size(); i++)
	{
		lli front = mypow(26, a + str.size() - i);
		lli back = mypow(25, i - str.size());
		lli comb = C(i - 1, str.size() - 1);
		res += ((front * back) % mod * comb) % mod;
		if(res >= mod) res -= mod;
	}
