ll pwm(ll xx, ll pow, ll MD) {
    if (pow < 0) { pow = pow % (MD - 1) + MD - 1; }
    ll mlt = 1;
    while (pow) {
        if (pow & 1) {
            mlt *= xx;
            mlt %= MD;
        }
        xx *= xx;
        pow >>= 1;
        xx %= MD;
    }
    return mlt;
}

int inv(ll r, int _mod) {
    return pwm(r % _mod, _mod - 2, _mod);
}

vector<ll> fact;
vector<ll> invfact;

void factorial(int n, ll mod) {
    fact.resize(n);
    invfact.resize(n);
    fact[0] = 1;
    for (int i = 1; i < n; ++i) {
        fact[i] = fact[i - 1] * i;
        fact[i] %= mod;
    }
    invfact[n - 1] = inv(fact[n - 1], mod);
    for (int i = n - 2; i >= 0; i--) {
        invfact[i] = invfact[i + 1] * (i + 1);
        invfact[i] %= mod;
    }
}

