struct combination {
  vector<mint> fact, ifact;
  combination(int n) : fact(n + 1), ifact(n + 1) {
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
  }
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * ifact[k] * ifact[n - k];
  }
};

int main() {
  int k, n;
  string s;
  cin >> k >> s;
  n = s.size();
  combination c(n + k);
  mint ans = 0;
  for (int i = 0; i <= k; i++) {
    mint now = mint(26).pow(k - i);
    now *= mint(25).pow(i);
    now *= c(i + n - 1, n - 1);
    ans += now;
  }
  cout << ans << endl;
  return 0;
}

