  init();
  for (int i = 0; i <= K; i++)
  {
    int64_t tmp = POW26[K - i];
    (tmp *= POW25[i]) %= MOD;
    (tmp *= nCk(N + i - 1, N - 1)) %= MOD;
    (ans += tmp) %= MOD;
  }
  cout << ans << endl;
}

