const int mod = 1e9+7;
const int N = 1e6+2;

int fac[N], inv[N];

int mi(int x, int n) 
{
   int res = 1;
   while(n) {
      if(n & 1) 
         res = (1LL * res * x) % mod;
      x = (1LL * x * x) % mod;
      n >>= 1;
   }
   return res;
}

void fact() 
{
   fac[0] = 1;
   rep(i, 1, N) {
      fac[i] = (1LL * fac[i-1] * i) % mod;
   }

   inv[N-1] = mi(fac[N-1], mod-2);
   for(int i=N-1; i>0; i--) {
      inv[i-1] = (1LL * inv[i] * i) % mod;
   }
}

int nCr(int n, int k) 
{
   if(k > n)
      return 0;

   int ans = (1LL * fac[n] * inv[k]) % mod;
   ans = (1LL * ans * inv[n-k]) % mod;
   return ans;
}


void solve()
{   
    fact();

    int k;
    string s;

    cin >> k >> s;

    int m = (int)s.size();

    int ans = 0;

    for(int x=0; x<=k; x ++) {
        // 26^x * (k-x+m-1)Cm-1 * 25^(k-x)

        int here = mi(26, x);
        here = (1LL * here * nCr(k-x+m-1, m-1)) % mod;
        here = (1LL * here * mi(25, k-x)) % mod;
        ans = (1LL * ans + here) % mod;
    }

    prin(ans);
}

