#define  N  2000005
ll fact[N];
ll invfact[N];

void factorialInverse()
{
  invfact[N - 1] = moduloInverse(fact[N - 1]);
  for (ll i = N - 2; i >= 0; i--) {
    invfact[i] = invfact[i + 1] * (i + 1);
    invfact[i] %= mod;
  }
}

ll nCr(ll n, ll r) {
  if (n < 0 or r < 0) return 0LL;
  if (n < r) return 0LL;
  return fact[n] * (invfact[r] * invfact[n - r] % mod) % mod;
}


