  //for (ll i = 0; i < 10; i++) cout << invfact[i] << " ";
  for (ll i = 0; i <= k; i++) {
    ll temp = ((powmod(26, i)) * (powmod(25, k - i))) % mod;
    temp = (temp * nCr(n + k - i - 1, n - 1)) % mod;
    ans = (ans + temp) % mod;
  }
