	inv[N-1]=quick_pow(fac[N-1],mod-2);
	per(i,N-2,0) inv[i]=(inv[i+1]*(i+1))%mod;
}
ll C(ll a,ll b){
	if(b>a) return 0ll;
	return fac[a]*inv[b]%mod*inv[a-b]%mod;
}

