ll mpow(ll x, ll n){ //x^n (mod M)
    ll ans = 1;
    while(n != 0){
        //したの桁から見ていって、その桁にあったら*xして、nをシフトするにつれxを二乗する
        if (n & 1) ans = ans * x % M;
        x = x * x % M;
        n = n >> 1;
    }
    return ans;
}

//aCbを求める
ll comb(ll a, ll b){
    if(a == 0 && b == 0) return 1;
    if(a < b || a < 0) return 0;
    ll tmp = ifac[a-b] * ifac[b] % M;//階乗を求めたもので割る
    return tmp * fac[a] % M;
}

int main() {
    int k, n;
    string s;
    cin >> k >> s;
    n = s.size();
    ll ans = 0;

    //最初に階乗を求めておく
    fac[0] = 1;
    ifac[0] = 1;
    for(ll i = 0; i < 1000000; i++){
        fac[i+1] = fac[i]*(i+1) % M;
        ifac[i+1] = ifac[i] * mpow(i+1,M-2)%M;//逆元を求めている
    }

    for (int i = 0; i <= k; ++i) {
        //
        ll now = mpow(26,k-i);
        now = now * mpow(25,i) % M;
        now = now * comb(i+n-1,n-1) % M;
        ans = (ans+now)%M;
    }
    cout << ans << endl;
    return 0;
}

