ll extended_euclidean(ll u, ll v)
{
	ll r0 = u;
	ll r1 = v;
	ll s0 = 1;
	ll s1 = 0;
	ll t0 = 0;
	ll t1 = 1;
	while (r1 != 0)
	{
		ll q = r0 / r1;
		ll r = r0 - q * r1;
		ll s = s0 - q * s1;
		ll t = t0 - q * t1;
		r0 = r1;
		s0 = s1;
		t0 = t1;
		r1 = r;
		s1 = s;
		t1 = t;
	}
	if (t0 < 0)
