ll pw(ll a, ll b) {
    if (b == 0)
        return 1LL;
    ll x = pw(a, b/2LL);
    x = (x*x) % M;
    if (b%2LL)
        return (x*a)%M;
    return x;
}

ll C(ll a, ll b) {
    ll r = f[a];
    r *= pw(f[b], M-2LL);
    r %= M;
    r *= pw(f[a-b], M-2LL);
    r %= M;
    return r;
}

