	long long ans = 0;
	for (int i = 0; i <= k; i++) {
		ans = (ans + mpow(26,i)*mpow(25,k-i)%mod * (nCk(s.size()+k-1-i, s.size()-1))%mod) % mod;
	}

	cout << ans << endl;
	return 0;
}

