// セグ木の更新(幼稚園に人が＜＜＜入るとき＞＞＞に呼ぶ！）
void seg_update(ll p, ll v)
{
	p += SEG_LEN;
	total[p] = max(total[p], v);
	if (total[p] == LLINF)
	{
		total[p] = v;
	}
	while (true)
	{
		p /= 2;
		if (p <= 0) break;
		total[p] = min(total[2 * p], total[2 * p + 1]);
	}
}

// セグ木の更新(いなくなった時用)
void seg_replace(ll p, ll v)
{
	p += SEG_LEN;
	total[p] = v;
	while (true)
	{
		p /= 2;
		if (p <= 0) break;
		total[p] = min(total[2 * p], total[2 * p + 1]);
	}
}

