ll qp(ll a, ll n, ll mod = ::mod) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

ll jie[maxn] = {1};
char s[maxn];

ll inv(ll x) { return qp(x, mod - 2); }

ll C(int x, int y) {
    if (x < y) return 0;
    if (x == 0) return 0;
    return jie[x] * inv(jie[y]) % mod * inv(jie[x - y]) % mod;
}

