using namespace std;

const int MOD = 1e9 + 7;
const int MAX = 3e6 + 5;

int fact[MAX];
int inv[MAX];

int Power(int n, int x) {
  if (x == 0) {
    return 1;
  } else if (x & 1) {
    return 1ll * n * Power(n, x - 1) % MOD;
  } else {
    int res = Power(n, x / 2);
    return 1ll * res * res % MOD;
  }
}

int C(int n, int r) {
  if (r > n || r < 0) {
    return 0;
  }
  return 1ll * fact[n] * inv[r] % MOD * inv[n - r] % MOD;
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  fact[0] = inv[0] = 1;
  for (int i = 1; i < MAX; i++) {
    fact[i] = 1ll * i * fact[i - 1] % MOD;
    inv[i] = Power(fact[i], MOD - 2);
  }

  int K;
