  string S;
  cin >> S;
  int ans = 0;
  for (int i = 0; i <= K; i++) {
    ans += 1ll * Power(26, i) * Power(25, K - i) % MOD * C(K - i + int(S.size()) - 1, int(S.size()) - 1) % MOD;
    if (ans >= MOD) {
      ans -= MOD;
    }
  }
  cout << ans << "\n";
  return 0;
}

