ll modpow(ll a, ll n, ll m=mod) {
	ll res = 1;
	while (n) {
		if (n & 1)res = res * a % m;
		a = a * a%m; n >>= 1;
	}
	return res;
}

struct STMOD{
  int n;
  V<ll> f, invf;
  STMOD(int N=3000200) : n(N), f(N), invf(N) {
    f[0] = 1;
    FOR(i,0,N-10) f[i+1] = (i+1)*f[i] % mod;
    FOR(i,0,N-10) invf[i] = modpow(f[i],mod-2);
  }
  ll comb(ll a, ll b){
    if(a<0 || b<0 || a<b) return 0LL;
    ll ret = 1;
    ret *= f[a];
    (ret *= invf[b]) %= mod;
    (ret *= invf[a-b]) %= mod;
    return ret;
  }
};





