typedef long long ll;

const int MOD = 1e9+7;

int pow(int a, int p) {
  int x = 1;
  while (p > 0) {
    if (p % 2 == 0) {
      a = 1LL*a*a%MOD;
      p /=2;
    }
    else {
      x = 1LL*x*a%MOD;
      --p;
    }
  }
  return x;
}

int calc(map<pair<int,int>, int> &dp, int n, int l, vector<int>& distinct) {
  pair<int,int> d(n,l);
  if (dp.find(d) != dp.end()) {
    return dp[d];
  }
  if (l==0) {
    return dp[d]=pow(26,n);
  }
  if (n == l) {
    return dp[d]=1;
  }
  return dp[d] = (calc(dp,n-1,l-1,distinct)+1LL*25*calc(dp,n-1,l,distinct)%MOD)%MOD;
}

