lint binpow(lint n, lint x, lint mod)
{
  lint tgt = 1;
  lint dig = n;
  while (x > 0) {
    if (x%2) {
      tgt = (tgt * dig) % mod;
    }
    dig = (dig * dig) % mod;
    x /= 2;
  }
  return tgt;
}

class Comb
{
private:
  lint mod;
  vector< lint > fact;
  vector< lint > factf;
public:
  Comb(lint size, lint mod) : mod(mod), fact(size+1, 0), factf(size+1, 0) {
    fact[0] = 1;
    factf[0] = 1;
    for (lint i = 1; i <= size; ++i) {
      fact[i] = fact[i-1]*i%mod;
      factf[i] = binpow(fact[i], mod-2, mod);
    }
  }
  lint comb(lint n, lint k) {
    if (n<k) return 0;
    if (k==0 || n==k) return 1;
    return ((fact[n] * factf[k]) % mod * factf[n-k]) % mod;
  }
};

int main(void)
{
