  lint ans = 0;
  for (lint i=0; i<=k; ++i) {
    ans += comb.comb(i+s.size()-1, s.size()-1) * binpow(25, i, mod) % mod * binpow(26, k-i, mod) % mod;
    ans %= mod;
  }
  cout << ans << endl;
  return 0;
}

