template<int M>
class ModInt {
   public:
    ll value;
    constexpr ModInt(ll v = 0) { value = v % M; if (value < 0) value += M; }
    constexpr ModInt pow(ll n) const {
        if (!n) return 1;
        ModInt a = pow(n >> 1);
        a *= a;
        if (n & 1) a *= *this;
        return a;
    }
    constexpr ModInt inv() const { return this->pow(M - 2); }
    constexpr ModInt operator + (const ModInt &rhs) const { return ModInt(*this) += rhs; };
    constexpr ModInt operator - (const ModInt &rhs) const { return ModInt(*this) -= rhs; };
    constexpr ModInt operator * (const ModInt &rhs) const { return ModInt(*this) *= rhs; };
    constexpr ModInt operator / (const ModInt &rhs) const { return ModInt(*this) /= rhs; };
    constexpr ModInt &operator += (const ModInt &rhs) { value += rhs.value; if (value >= M) value -= M; return *this; };
    constexpr ModInt &operator -= (const ModInt &rhs) { value -= rhs.value; if (value <  0) value += M; return *this; };
    constexpr ModInt &operator *= (const ModInt &rhs) { value = value * rhs.value % M; return *this; };
    constexpr ModInt &operator /= (const ModInt &rhs) { return (*this) *= rhs.inv(); };
    constexpr bool operator == (const ModInt &rhs) { return value == rhs.value; }
    constexpr bool operator != (const ModInt &rhs) { return value != rhs.value; }
    friend ostream &operator << (ostream &os, const ModInt &rhs) { os << rhs.value; return os; }
};

using mint = ModInt<MOD>;

template <class T>
class Combination {
   public:
    vector<T> _fact, _rfact, _inv;
    constexpr Combination(int N) : _fact(N + 1), _rfact(N + 1), _inv(N + 1) {
        _fact[0] = _rfact[N] = _inv[0] = 1;
        for (int i = 1; i < N + 1; i++) _fact[i] = _fact[i - 1] * i;
        _rfact[N] /= _fact[N];
        for (int i = N - 1; i >= 0; i--) _rfact[i] = _rfact[i + 1] * (i + 1);
        for (int i = 1; i < N + 1; i++) _inv[i] = _rfact[i] * _fact[i - 1];
    }

    constexpr T fact(int k) const { return _fact[k]; }
    constexpr T rfact(int k) const { return _rfact[k]; }
    constexpr T inv(int k) const { return _inv[k]; }

    constexpr T P (int n, int r) const {
        if (r < 0 || n < r) return 0;
        return fact(n) * rfact(n - r);
    }

    constexpr T C (int n, int r) const {
        if (r < 0 || n < r) return 0;
        return fact(n) * rfact(r) * rfact(n - r);
    }

    constexpr T H (int n, int r) const {
        if (r < 0 || n < 0) return 0;
        return r == 0 ? 1 : C(n + r - 1, r);
    }
};

