ll laip(ll a, ll b, ll liek) {
	a=a%liek;
	if (b==0) {return 1;}
	if (b==1) {return a;}
	ll c=(a*a)%liek;
	ll x=laip(c,b/2,liek);
	if (b%2==0) {return x;}
	else {return (a*x)%liek;}
	}


ll cnk (int i, int s, vector <ll> &F) {
	ll li=1000000005;
	ll liek=li+2;
	ll a=F[i];
	ll bb=laip(F[s],li,liek);
	ll cc=laip(F[i-s],li,liek);
	ll x=a*bb;
	x=x%liek;
	x=x*cc;
	x=x%liek;
	return x;
	}


