      for(int i=0;i<n;i++){
        f[i+1]=f[i]*(modint)(i+1);
      }
      i_f[n]=f[n].power(mod-2);
      for(int i=n-1;i>=0;i--){
        i_f[i]=i_f[i+1]*(modint)(i+1);
      }
    }
    ModFac(modint n_){
      n=(int)n_;
      f.resize(n+1,1);
