ll powmodk(ll a, ll k, ll m) {
    if (k == 0) return 1;
    ll r = powmodk(a, k / 2, m);
    r = (r * r) % m;
    if (k % 2) r = (r * a) % m;
    return r;
}

inline ll fix(ll x){
	return (x % MOD + MOD) % MOD;
}

inline ll modinverse(ll a) {
    return powmodk(fix(a), MOD - 2, MOD);
}

ll nck(int n, int k){
	ll num = fact[n];
	ll den = modinverse(1LL * fact[n - k] * fact[k]);
	return fix(num * den);
}

