struct ModValue
{
    static constexpr int
        value = 1'000'000'007;
};

template<int mod = ModValue::value>
struct mint
{   
    long long x;

    mint(long long xx = 0) : x(xx % mod){}

    mint(const mint&) = default;
    mint& operator=(const mint& rhs) = default;

    mint operator-() const
    {
        return mint(-x);
    }

    mint& operator+=(const mint rhs)
    {
        x += rhs.x;
        if(x >= mod)
        {
            x -= mod;
        }

        return *this;
    }

    mint& operator-=(const mint rhs)
    {
        x += mod - rhs.x;
        if(x >= mod)
        {
            x -= mod;
        }

        return *this;
    }

    mint& operator*=(const mint rhs)
    {
        x *= rhs.x;
        x %= mod;
        return *this;
    }

    mint operator+(const mint rhs) const
    {
        return mint(*this) += rhs;
    }

    mint operator-(const mint rhs) const
    {
        return mint(*this) -= rhs;
    }

    mint operator*(const mint rhs) const
    {
        return mint(*this) *= rhs;
    }

    mint pow(long long t) const
    {
        mint rtn = 1;
        mint tmp = *this;
        while(t > 0)
        {
            if(t & 1)
            {
                rtn *= tmp;
            }
            tmp *= tmp;
            t >>= 1;
        }
        return rtn;
    }

    mint inv() const
    {
        return pow(mod - 2);
    }
    mint& operator/= (const mint rhs)
    {
        return *this *= rhs.inv();
    }
    mint operator/ (const mint rhs) const
    {
        return mint(*this) /= rhs;
    }
};
template<int mod = ModValue::value>
std::istream& operator>>(std::istream& is, mint<mod>& m)
{ return is >> m.x; }

template<int mod = ModValue::value>
std::ostream& operator<<(std::ostream& os, mint<mod>& m)
{ return os << m.x; }

template<int mod = ModValue::value>
struct combination
{
    // factorial, invFactorial
    std::vector<mint<mod>> fact, ifact;

    combination(int n) : fact(n + 1), ifact(n + 1)
    {
        fact[0] = 1;
        for(int i = 1; i <= n; ++i)
        {
            fact[i] = fact[i - 1] * i;
        }

        // inv
        ifact[n] = fact[n].inv();
        for(int i = n; i >= 1; --i)
        {
            ifact[i - 1] = ifact[i] * i;
        }
    }

    mint<mod> operator()(int n, int k)
    {
        if(k < 0 || k > n)
        {
            return 0;
        }
        // nCk = n! / k!(n-k)!
        return fact[n] * ifact[k] * ifact[n - k];
    }
};

