	inv[N - 1] = power(fac[N - 1], mod - 2);
	for (int i = N - 2; i >= 0; i--) {
		inv[i] = inv[i + 1] * (i + 1) % mod;
	}
}
ll C(int n, int k) {
	return fac[n] * inv[k] % mod*inv[n - k] % mod;
}
