template<int mod> struct ModInt {
    int64_t x;
    ModInt() : x(0) {}
    ModInt(int64_t y) : x(y >= 0 ? y % mod : (y % mod + mod) % mod) {}

    ModInt &operator+=(const ModInt &a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &a) {
        x = 1LL * x * a.x % mod;
        return *this;
    }

    ModInt &operator/=(const ModInt &a) {
        *this *= a.inverse();
        return *this;
    }

    ModInt operator-() const {
        return ModInt(-x);
    }

    ModInt operator+(const ModInt a) const {
        return ModInt(*this) += a;
    }

    ModInt operator-(const ModInt a) const {
        return ModInt(*this) -= a;
    }

    ModInt operator*(const ModInt a) const {
        return ModInt(*this) *= a;
    }

    ModInt operator/(const ModInt a) const {
        return ModInt(*this) /= a;
    }

    bool operator==(const ModInt a) const {
        return x == a.x;
    }

    bool operator!=(const ModInt a) const {
        return x != a.x;
    }

    ModInt pow(int64_t k) const {
        ModInt ret(1), mul(x);
        while (k > 0) {
            if (k & 1) ret *= mul;
            mul *= mul;
            k >>= 1;
        }
        return ret;
    }

    ModInt inverse() const {
        return pow(mod - 2);
    }

    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a) {
        int64_t t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }
};

template <typename ModInt> class ModCalc {
private:
    vector<ModInt> fact, finv, inv_;

    void init(int n) {
        int mx = n*2+10;
        fact = vector<ModInt>(mx);
        finv = vector<ModInt>(mx);
        inv_ = vector<ModInt>(mx);

        fact[0] = fact[1] = ModInt(1);
        finv[0] = finv[1] = ModInt(1);
        inv_[1] = ModInt(1);
        FOR (i, 2, mx) {
            fact[i] = fact[i-1]*ModInt(i);
            inv_[i] = ModInt(i).inverse();
            finv[i] = finv[i-1]*inv_[i];
        }
    }

public:
    ModCalc() {}
    ModCalc(int n) { init(n); }

    ModInt nCk (int n, int k) {
        if (n < k || k < 0 || n < 0) return 0;
        return fact[n]*finv[k]*finv[n-k];
    }

    ModInt nHk (int n, int k) {
        return nCk(n-1+k, n-1);
    }

    ModInt nPk (int n, int k) {
        if (n < k || k < 0 || n < 0) return 0;
        return fact[n]*finv[n-k];
    }

    ModInt factorial(int n) {
        return fact[n];
    }

    ModInt stirling(ll n, int k) {
        ll ret = 0;
        FOR (i, 1, k+1)
            ret += ModInt(-1).pow(k-i) * nCk(k, i) * ModInt(i, n);
        return ret;
    }
};

