ULL RepSq(ULL x, ULL n, ULL mod){
	if (n == 0)	return 1;
	if (n == 1) return x;

	ULL ret = 1;
	while (0 < n) {
		if (n % 2) {
			ret *= x;
			ret %= mod;
			n--;
		} else {
			x *= x;
			x %= mod;
			n >>= 1;
		}
	}
	return ret;
}

void nCk_init(ULL mod) {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++){
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		finv[i] = finv[i - 1] * inv[i] % mod;
	}
}

ULL nCk(int n, int k, ULL mod){
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

