struct NumberTheory{
	//mult,normalize,div,add,sub,fact,finv,ncr,pow,inv
	vector<ll> factorial={1},factorialInv={1};
	ll mod=1e9+7;
	inline ll mult(ll a,ll b){
		return (a*b)%mod;
	}
	inline ll norm(ll x){
		x%=mod;
		if(x<0) x+=mod;
		return x;
	}
	inline ll div(ll a,ll b){
		return mult(a,inv(b));
	}
	inline ll sub(ll a, ll b){
		return norm(a-b);
	}
	inline ll add(ll a,ll b){
		return (a+b)%mod;
	}
	//using ll so it works with both int and ll
	ll ncr(ll n,ll r){
		assert(n>=0);
		if(r<0 || n<r)
			return 0;
		return mult(fac(n),mult(finv(r),finv(n-r)));
	}
	ll finv(ll n){
		int last=factorialInv.size()-1;
		if(last<n){
			//this was as mult is easier than cal inverse again
			//mult in O(1) while inv in log(mod)
			vector<ll> finv_temp(n-last);
			finv_temp[0]=inv(fac(n));
			for(int i=1;i<(int)finv_temp.size();i++){
				finv_temp[i]=mult(finv_temp[i-1],n-i+1);
			}
			for(int i=finv_temp.size()-1;i>=0;i--){
				factorialInv.push_back(finv_temp[i]);
			}
		}
		return factorialInv[n];
	}
	ll pow(ll x,ll e){
		if(e<0){
			x=inv(x);
			e*=-1;
		}
		ll res=1;
		while(e>0){
			if(e&1)
				res=mult(res,x);
			e=e>>1;
			x=mult(x,x);
		}
		return res;
	}

	inline ll inv(ll x){
		//currently using fermat little
		return pow(x,mod-2);
	}

	ll fac(int n){
		while((int)factorial.size()<=n){
			factorial.push_back(mult(factorial[factorial.size()-1],factorial.size()));
		}
		return factorial[n];
	}
};

