ll mp(ll a, ll b) {
    if (b == 0) return 1LL;
    ll ret = mp(a,b/2);
    ret *= ret;
    ret %= mod;
    if (b&1) ret *= a;
    return ret % mod;
}

ll inv(ll k) {
    return mp(k,mod-2);
}

ll c(ll n, ll k) {
    if (k == 0) return 1;
    if (n == k) return 1;
    return kai[n] * inv(kai[k]) % mod * inv(kai[n-k]) % mod;
}

