    init();
    int k;
    string s;
    cin >> k >> s;
    int n = s.size();
    dp[n] = 1LL;
    for (ll i = n + 1; i <= n + k; i++) {
        dp[i] = dp[i-1] * 26LL % mod;
        dp[i] += c(i-1,n-1) * mp(25LL,i-n);
        dp[i] %= mod;
    }
    cout << dp[n+k] << endl;
    return 0;
}

