s64 fac[N + 1], finv[N + 1];

s64 mypow(s64 x, s64 n)
{
    s64 ret = 1;
    while (n > 0)
    {
        if (n & 1) ret = (ret * x) % MOD;
        x = (x * x) % MOD;
        n >>= 1;
    }
    return ret;
}

void init(int n)
{
    if (n > N) n = N;
    fac[0] = 1;
    rep (i, n)
    {
        fac[i + 1] = (fac[i] * (i + 1)) % MOD;
    }
    finv[n] = mypow(fac[n], MOD - 2);
    for (int i = n; i >= 1; --i)
    {
        finv[i - 1] = (finv[i] * i) % MOD;
    }
}

s64 com(int n, int k)
{
    if (n < k || n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

