ll binomialCoeff(int n,int k){
	ll res = 1;
	if(k > n-k) k = n-k;
	for(int i = 0; i < k; i++){
		res = (res%mod*(n-i)%mod)%mod;
		res = modDivide(res,i+1);
	}
	return res;
}
