    p26[i] = p26[i - 1] * 26 % MOD;
  }

  ModuloCombination<ll, MOD> c(k + n);

  ll r = 0;
  for (int i = n; i <= n + k; i++) {
    r += c(i - 1, n - 1) * p25[i - n] % MOD * p26[n + k - i] % MOD;
    r %= MOD;
  }
