unsigned mod_pow(unsigned num, unsigned r, unsigned mod){
    unsigned long long test;
    unsigned long long n = num;
    for(test = 1; r; r >>= 1)
    {
        if (r & 1)
            test = ((test % mod) * (n % mod)) % mod;
        n = ((n % mod) * (n % mod)) % mod;
    }

    return test;
}


