    ll B[n+k][n] = {0};
    for(int i = 0; i <= n+k-1; i++){
        for(int j = 0; j <= min(i,n-1); j++){
            if(j==0 || j == i){
                B[i][j] = 1;
            }else{
                B[i][j] = B[i-1][j-1]+B[i-1][j];
            }
        }
