ll mexp(ll a , ll b , ll mod){
  ll res=1;
  while(b){
    if(b%2)
      res=(res%mod)*(a%mod);
    a=(a%mod)*(a%mod);
    res=res%mod;
    a=a%mod;
    b=b/2;
  }
  return res;
}
