ll pwr(ll a, ll b) {
    ll ret = 1;
    while (b > 0) {
        if (b % 2 == 1) ret = ret * a % mod;
        a = a * a % mod;
        b /= 2; 
    }
    return ret;
}

const int N = 2e6 + 5;
ll f[N], inv[N];

ll C(int n, int k) {
    if (k > n || k < 0) return 0;
    return f[n] * (inv[k] * inv[n - k] % mod) % mod;
}

