int normalize(int x)
{
	x = x % MOD;
	if(x < 0) x += MOD;
	return x;
}

int add(int x, int y)
{
	return normalize(normalize(x) + normalize(y));
}

int mul(int x, int y)
{
	return normalize(normalize(x) * normalize(y));
}

int sub(int x, int y)
{
	return normalize(normalize(x) - normalize(y));
}

int expMod(int a, int e)
{
	int ans = 1;
	while(e)
	{
		if(e & 1) ans = mul(ans, a), e--;
		else a = mul(a, a), e /= 2;
	}
	return ans;
}

int inv(int x)
{
	return expMod(x, MOD - 2);
}

int nCk(int n, int k)
{
	return mul( fat[n] , mul( inv(fat[k]) , inv(fat[n - k]) ));
}

