    for(LL i=1; i<=lim; i++)
        facto[i]=((facto[i-1]%m)*(i%m))%m; /// (facto[i-1]*i)%m
}

LL nCr(LL n,LL r,LL m)
{
    LL up = facto[n];
    LL d1 = facto[n-r];
    LL d2 = facto[r];

    d1 = invMod_general(d1,m);
    d2 = invMod_general(d2,m);

    LL ans = (up * d1)%m;
    ans = (ans * d2)%m;

    return ans;
}

