}
int pwr(int a,int n,int mdo=mod){
	if(n==0)
		return md(1,mdo);
	else if(n==1)
		return md(a,mdo);
	int x=pwr(a,n/2,mdo);
	if(max(x,md(a,mdo))< int(1e9))
		x=md(x*x,mdo);
	else
		x=md(multi(x,x,mdo),mdo);
	if(n&1){
		if(max(x,md(a,mdo))< int(1e9))
			x=md(x*md(a,mdo),mdo);
		else
			x=md(multi(x,md(a,mdo),mdo),mdo);
	}
	return x;
}
int ge(int a, int b, int *x, int *y){
	if (a == 0){
		*x = 0, *y = 1;
		return b;
	}
	int x1, y1;
	int gcd = ge(b%a, a, &x1, &y1);
	*x = y1 - (b/a) * x1;
	*y = x1;
	return gcd;
}
int  modinv(int a, int m=mod){
	int x, y;
	int g = ge(a, m, &x, &y);
	// if g!=1 modinv doesn't exist;
	assert(g==1);
	int p = (x%m + m) % m;
	return p;
}
vector<int> fct,ifct;
void factorials(int n){
	int i;
	fct.resize(n+1);
	ifct.resize(n+1);
	fct[0]=1;
	for(i=1;i<=n;i++){
		fct[i]=md(fct[i-1]*i);
	}
	ifct[n]=modinv(fct[n]);
	for(i=n;i>0;i--){
		ifct[i-1]=md(ifct[i]*i);
	}
}
int ncr(int n, int r){
	if(n<0 || r<0 || n<r)
		return 0;
	return md(fct[n]*md(ifct[r]*ifct[n-r]));
}

