class mint {
  int32_t value;
  static vector<int32_t> _fact;
  static void fill(long n) {
    long i = _fact.size();
    if (n < i) return;
    mint val = _fact.back();
    for (; i <= n; i++) {
      _fact.push_back(val *= i);
    }
  }

public:
  static const int32_t MOD = 1e9 + 7;
  mint(int64_t x)
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  mint operator+(mint y) const {
    return mint(value + y.value);
  }
  mint &operator+=(mint a) {
    return *this = *this + a;
  }
  mint operator*(mint y) const {
    return mint(long(value) * y.value);
  }
  mint &operator*=(mint a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(mint y) const {
    return *this + (-y);
  }
  mint &operator-=(mint a) {
    return *this = *this - a;
  }
  operator int() const {
    return value;
  }
  static mint pow(mint a, long n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static mint fact(long n) {
    fill(n);
    return _fact[n];
  }
  static mint comb(long n, long k) {
    return fact(n) * fact(k).inv() * fact(n - k).inv();
  }
};
