const int MOD = 1e9 + 7; // 998244353;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

int mul(int a, int b) {
    return 1LL * a * b % MOD;
}

int binpow(int a, ll n) {
    if (n < 0)
        a = binpow(a, MOD - 2), n *= -1;

    int res = 1;
    while (n) {
        if (n & 1)
            res = mul(res, a);
        a = mul(a, a);
        n /= 2;
    }
    return res;
}

int inv(int x) {
    return binpow(x, MOD - 2);
}

void brute(int n, int k) {
    int m = n + k;

    vector<vector<int>> dp(m + 1, vector<int>(n + 2, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j <= n + 1; ++j) {
            if (j)
                dp[i][j] = add(dp[i][j], dp[i - 1][j - 1]);
            if (j == n + 1)
                dp[i][j] = add(dp[i][j], dp[i - 1][j]);
            dp[i][j] = add(dp[i][j], mul(25, dp[i - 1][j]));
        }
    }
    cout << add(dp[m][n], dp[m][n + 1]) << '\n';
}

