template <TN T, TN R> inline T modpow(T base, R exp) {
    base %= mod; T res = 1;
    if (base < 0) base += mod;
    if (exp < 0) exp += mod - 1;
    for (; exp > 0; exp >>= 1) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
