  comInit();

  for(int i=0;i <= K;i++){
    long long sumsub = (modpow(25,i) % mod *  modpow(26, K - i) % mod ) % mod;

    int r = sNum - 1;
    int n = i + r;
    sumsub *=  com(n, r);
    sum += sumsub % mod;
  }
  cout << sum % mod << endl;
}

