class Combination {
public:
	vector<long long> fact, ifact;
	long long mod;
public:
	Combination(int n, int mod) : fact(n+1), ifact(n+1), mod(mod) {
		fact[0] = 1;
		for (int i = 1; i <= n; i++) {
			fact[i] = fact[i-1] * i % mod;
		}
		ifact[n] = modinv(fact[n], mod);
		for (int i = n; i > 0; i--) {
			ifact[i-1] = ifact[i] * i % mod;
		}
	};
	// ~Combination();

	// nCk
	long long comb(int n, int k) {
		assert(n >= 0);
		assert(0 <= k && k <= n);
		return fact[n] * ifact[k] % mod * ifact[n-k] % mod;
	}

	// nPk
	long long perm(int n, int k) {
		assert(n >= 0);
		assert(0 <= k && k <= n);
		return fact[n] * ifact[n - k] % mod;
	}

	// nHk n種類から重複を許してk個
	long long h(int n, int k) {
		return comb(n - k + 1, k);
	}
};

