	for (int i = 0; i <= k; i++) {
		sum += modpow(25, i, mod) * modpow(26, k - i, mod) % mod * com.comb(i + n - 1, n - 1) % mod;
		sum %= mod;
	}

	cout << sum << endl;
	return 0;
}

