for(int i=1;i<=n;++i){
        res *= i;
    }
    return res;
}

mint nCr(int n,int r){
    mint numerator = 1;
    if(r > n - r) r = n - r;
    for(int i=n;i>n-r;--i){
        numerator *= i;
    }
    mint denominator = 1;
    for(int i=1;i<=r;++i){
        denominator *= i;
    }
    return numerator/denominator;
}

vector<pair<char,int>> RunLengthEncording(const string& s){
    vector<pair<char,int>> ret;
    int cnt = 1;
    for(int i=0;i<s.size()-1;++i){
        if(s[i] == s[i+1]){
            ++cnt;
        }else{
            ret.push_back({s[i], cnt});
            cnt = 1;
        }
    }
    ret.push_back({s[s.size()-1], cnt});
    return ret;
}

