#include <bits/stdc++.h>
using namespace std;
const int MAX = 1000005;
const int64_t MOD = 1000000007;
int64_t POW25[MAX], POW26[MAX];

int64_t fac[MAX], finv[MAX], inv[MAX];
void COMinit()
{
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++)
  {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

int64_t nCk(int n, int k)
{
  if (n < k)
    return 0;
  if (n < 0 || k < 0)
    return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int64_t nHk(int n, int k)
{
  return nCk(n + k - 1, k);
}

void init()
{
  POW25[0] = POW26[0] = 1;
  for (int i = 1; i < MAX; i++)
  {
    POW25[i] = (POW25[i - 1] * 25) % MOD;
    POW26[i] = (POW26[i - 1] * 26) % MOD;
  }
  COMinit();
}

int main()
{
  int64_t K, ans = 0;
  string S;
  cin >> K >> S;
  int N = S.size();
  init();
  for (int i = 0; i <= K; i++)
  {
    int64_t tmp = POW26[K - i];
    (tmp *= POW25[i]) %= MOD;
