	for (int i = len + k - 1; i >= 0; i--)
	{
		inv[i] = inv[i + 1] * (i + 1) % mod;
	}
}
ll C(int m, int n)
{
	return  fac[m] * inv[m - n] % mod * inv[n] % mod;
