#define N 1000005
int fact[N],invfact[N];

void fun()
{
	fact[0]=1;
	for(int i=1;i<N;i++)
		fact[i]=mul(fact[i-1],i);
	invfact[N-1]=modinv(fact[N-1]);
	for(int i=N-2;i>=0;i--)
		invfact[i]=mul(invfact[i+1],i+1);
}

int ncr(int n,int r)
{
	int ans=fact[n];
	ans=mul(ans,invfact[n-r]);
	ans=mul(ans,invfact[r]);
	return ans;
}

