  constexpr auto gen = [](long long ini, long long o) {
    std::array<long long, 100000> res = {{ini}};
    for (size_t i = 0; i < 100000 - 1; ++i)
      res[i + 1] = res[i] * (o + i + 1) % kMod;
    return res;
  };

  constexpr auto fact0 = gen(1, 0);
  constexpr auto fact1 = gen(fact0.back()*100000%kMod,100000);
  constexpr auto fact2 = gen(fact1.back()*200000%kMod,200000);
  constexpr auto fact3 = gen(fact2.back()*300000%kMod,300000);
  constexpr auto fact4 = gen(fact3.back()*400000%kMod,400000);
  constexpr auto fact5 = gen(fact4.back()*500000%kMod,500000);
  constexpr auto fact6 = gen(fact5.back()*600000%kMod,600000);
  constexpr auto fact7 = gen(fact6.back()*700000%kMod,700000);
  constexpr auto fact8 = gen(fact7.back()*800000%kMod,800000);
  constexpr auto fact9 = gen(fact8.back()*900000%kMod,900000);
  constexpr std::array<std::array<long long, 100000>, 10> fact = {
    {fact0, fact1, fact2, fact3, fact4, fact5, fact6, fact7, fact8, fact9}
  };
  constexpr long long factM = fact9.back() * 1000000 % kMod;

  auto get = [&](int n) {
  	return n < 1000000 ? fact[n/100000][n%100000] : factM;
  };

  constexpr auto mpow = [=](long long a, int b) {
  	long long res = 1;
  	for (; b; b >>= 1) {
  		if (b & 1) res = res * a % kMod;
  		a = a * a % kMod;
  	}
  	return res;
  };

  auto inv = [&](int n) { return mpow(n, kMod - 2); };
  auto c = [&](int n, int r) {
  	return get(n) * inv(get(n-r) * get(r) % kMod) % kMod;
  };

