int mi(int x, int n) 
{
   int res = 1;
   while(n) {
      if(n & 1) 
         res = (1LL * res * x) % mod;
      x = (1LL * x * x) % mod;
      n >>= 1;
   }
   return res;
}

void fact() 
{
   fac[0] = 1;
   rep(i, 1, N) {
      fac[i] = (1LL * fac[i-1] * i) % mod;
   }

   inv[N-1] = mi(fac[N-1], mod-2);
   for(int i=N-1; i>0; i--) {
      inv[i-1] = (1LL * inv[i] * i) % mod;
   }
}

int nCr(int n, int k) 
{
   if(k > n)
      return 0;

   int ans = (1LL * fac[n] * inv[k]) % mod;
   ans = (1LL * ans * inv[n-k]) % mod;
   return ans;
}


