struct fast_combination {
    fast_combination(i64 n, i64 mod_) :fac(n+1, 0), finv(n+1, 0), inv(n+1, 0), mod_(mod_) {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for (i64 i=2; i<=n; ++i) {
            fac[i] = fac[i-1] * i % mod_;
            inv[i] = mod_ - inv[mod_%i] * (mod_/i) % mod_;
            finv[i] = finv[i-1] * inv[i] % mod_;
        }
    }

    i64 operator()(i64 n, i64 k) {
        if (n > fac.size()-1) return -1;
        if (n < k || n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n-k] % mod_) % mod_;
    }


