    int mod_;
};

template<typename IntType>
IntType all_pattern(IntType a, IntType b, IntType mod_) {
  IntType res = 1;
  for (a %= mod_; b; a = a * a % mod_, b >>= 1)
    if (b & 1) res = res * a % mod_;
  return res;
}

