using large = long long;
constexpr auto mod = 1'000'000'007;

static array<int, 2'000'005> power26_table;
static array<int, 2'000'005> power25_table;
static array<int, 2'000'005> factorial_table;
static array<int, 2'000'005> inv_factr_table;

template <large M> static large power(large b, large e) {
    assert(e >= 0);
    if (e == 0)
        return 1;
    if (e == 1)
        return b % M;

    auto p = (e % 2 == 0 ? large{1} : b % M);
    return p * power<M>(b * b % M, e / 2) % M;
}

template <large M> static large factorial(large x) {
    assert(x >= 0);
    if (x <= 1)
        return 1;

    auto f = 1LL;
    while (x >= 2) {
        f *= x;
        f %= M;
        --x;
    }
    return f;
}

template <large M> static large inverse(large x) { return power<M>(x % mod, M - 2); }

template <large M> static large combination(large n, large k) {
    auto fn = factorial<M>(n);
    auto fk = factorial<M>(k);
    auto fnk = factorial<M>(n - k);

    //    n!
    // ---------
    // k! (n-k)!
    return fn * inverse<M>(fk * fnk % M) % M;
}

int main() {
    {
        auto x = 1LL;
        for (auto& elem : power26_table) {
            elem = x;
            x *= 26;
            x %= mod;
        }
        x = 1LL;
        for (auto& elem : power25_table) {
            elem = x;
            x *= 25;
            x %= mod;
        }
        x = 1LL;
        auto y = 1LL;
        for (auto& elem : factorial_table) {
            elem = x;
            x *= y;
            x %= mod;
            ++y;
            y %= mod;
        }
    }

    int k;
    string s;
    cin >> k >> s;

    const auto result_length = int(k + s.length()); // <= 2'000'000

    auto cases = 0LL;
    for (auto Sn_pos = int(large(s.length()) - 1); Sn_pos < result_length; ++Sn_pos) {
        const auto free_chars = Sn_pos - int(large(s.length()) - 1);
        assert(free_chars >= 0);
        const auto trailing = result_length - (Sn_pos + 1);
        assert(trailing >= 0);

        const auto fn = factorial_table[Sn_pos];
        const auto fk = factorial_table[s.length() - 1];
        const auto fnk = factorial_table[Sn_pos - (s.length() - 1)];
        const auto c = large(fn) * inverse<mod>(large(fk) * fnk % mod) % mod;
        const auto d = large(power25_table[free_chars]) * power26_table[trailing] % mod;
        cases += (c * d % mod);
        if (auto tmp = cases - mod; tmp >= 0)
            cases = tmp;
    }

    cout << cases << "\n";
    return 0;
}

