		temp = temp * n25[k - N + 1];
		temp %= MOD;
		temp = temp * n26[N + K - k-1];
		temp %= MOD;
		sum = (sum + temp) % MOD;
	}
	cout << sum << "\n";
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int64_t MAX = 1e+6+10;
const int64_t MOD = 1000000007;

int64_t fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int64_t i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
int64_t COM(int64_t n, int64_t k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main() {
    int64_t K;
    string S;
    cin >> K;
    cin >> S;
    int64_t N = S.size();

    // 前処理
    COMinit();

    vector<int64_t> POW26(K+10),POW25(K+10);
    POW26[0] = 1;
    POW25[0] = 1;
    for ( int64_t i = 1; i < K+10; ++i){
        POW25[i] = POW25[i-1] * 25 % MOD;
        POW26[i] = POW26[i-1] * 26 % MOD;
    }

    int64_t sum = 0;
    for ( int64_t k = 0; k <= K; ++k){
        sum = ( sum + ( COM(N+K-k-1,N-1) * POW26[k] ) % MOD * POW25[K-k] % MOD ) % MOD;
    }

    if ( sum < 0 ) sum += MOD;

    cout << sum << endl;


    return 0;
}

