class combination {
 public:
  using mint = modular<T, MOD>;
 private:
  mint fact_[MAX+1];
  mint ifact_[MAX+1];

 public:
  constexpr combination() {
    fact_[0] = 1;
    for (size_t i = 1; i <= MAX; ++i) {
      fact_[i] = fact_[i-1] * i;
    }
    ifact_[MAX] = mint(1)/fact_[MAX];
    for (int i = MAX-1; i >= 0; i--) {
      ifact_[i] = ifact_[i+1] * (i+1);
    }
  }

  mint operator()(T p, T q) const {
    if (p < q) return 0;
    return fact_[p] * ifact_[q] * ifact_[p-q];
  }

  mint fact(int p) const {
    return fact_[p];
  }
  mint ifact(int p) const {
    return ifact_[p];
  }

};

