ll power(ll n, ll k){
	ll res = 1;
	while(k){
		if(k % 2) res = (res * n) % MOD;
		n = (n * n) % MOD;
		k /= 2;
	}
	return res;
}

ll inverse(ll n){
	return power(n, MOD - 2);
}

ll ncr(ll n, ll k){
	if(n < k) return 0;
	if(k == 0 || n == k) return 1;
	ll fact_n = fact[n];
	fact_n = (fact_n * inverse(fact[n - k])) % MOD;
	fact_n = (fact_n * inverse(fact[k])) % MOD;
	return fact_n;
}

