const int N = 2e6 + 5;

int fact[N], invFact[N];

void pre() {
  fact[0] = invFact[0] = 1;
  for (int i = 1; i < N; i++) {
    fact[i] = mul(fact[i - 1], i);
  }
  invFact[N - 1] = inv(fact[N - 1]);
  for (int i = N - 2; i >= 1; i--) {
    invFact[i] = mul(invFact[i + 1], i + 1);
  }
  invFact[0] = 1;
}

int nCr(int n, int r) {
  if (r > n) return 0;
  int ans = fact[n];
  ans = mul(ans, invFact[r]);
  ans = mul(ans, invFact[n - r]);
  return ans;
}
int cnt[26];
int n, k;

int dp[27][N];

int fun(int ind, int cur) {
  if (ind == 26) {
    return (cur == (n + k)) * fact[n + k];
  }
  if (~dp[ind][cur]) return dp[ind][cur];
  int ans = 0;
  for (int i = 0; i <= n + k; i++) {
    if (cur + i <= n + k)
      ans = add(ans, mul(invFact[cnt[ind] + i], fun(ind + 1, cur + i)));
  }
  return dp[ind][cur] = ans;
}

