void combi_prepare(int mod)
{
  fac[0] = 1;
  fac[1] = 1;
  finv[0] = 1;
  finv[1] = 1;
  inv[1] = 1;

  for (int i = 2; i < kFacMax; i++)
  {
    fac[i] = fac[i - 1] * i % mod;
    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
    finv[i] = finv[i - 1] * inv[i] % mod;
  }
}

long long combi(int n, int k, long long mod)
{
  if (n < 0 || k < 0 || n < k)
    return 0;

  return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

long long mod_pow(long long a, long long n, long long mod)
{
  long long pow = 1;

  while (n > 0)
  {
    if (n & 1)
      pow = pow * a % mod;

    a = a * a % mod;
    n = n >> 1;
  }

  return pow;
}

int main()
{
  const int MOD = 1000000007;

  combi_prepare(MOD);

  int K;
  cin >> K;

  string S;
  cin >> S;

  long long sum = 0;
  for (int i = S.size(); i <= K + S.size(); i++)
  {
    long long left = combi(i - 1, S.size() - 1, MOD) * mod_pow(25, (i - 1) - (S.size() - 1), MOD) % MOD;
    long long right = mod_pow(26, K + S.size() - i, MOD);
    sum += left * right % MOD;
    sum %= MOD;
  }
  cout << sum << endl;

  return 0;
}

