struct CombiTbl {
	mints fac;
	mints ifac;

	CombiTbl(int N) : fac(N), ifac(N) {
		fac[0] = 1;
		ifac[0] = 1;
		FOR(i, 1, N) {
			fac[i] = fac[i - 1] * i;
			ifac[i] = fac[i].inv();
		}
	}

	mint Combi(int a, int b) const {
		return fac(a) * ifac(b) * ifac(a - b);
	}
};

struct MyMain {
	int K = in;
	string S = in;
	mints fac;
	mints ifac;
	mints pow25;
	mints pow26;

	void Run() {
		int MAX = 2000001;
		pow25.init(MAX);
		pow26.init(MAX);
		pow25[0] = 1;
		pow26[0] = 1;
		CombiTbl ctbl(MAX);
		FOR(i, 1, MAX) {
			pow25[i] = pow25[i - 1] * 25;
			pow26[i] = pow26[i - 1] * 26;
		}

		int L = S.size();
		int N = L + K;

		mint ans = 0;
		FOR(i, L, N + 1) {
			mint v = ctbl.Combi(i - 1, L - 1);
			v = v * pow25(i - L) * pow26(N - i);
			ans += v;
		}

		out << ans;
	}
};

