ll gcd(ll a, ll b){
    if(b==0) return a;
    return gcd(b, a%b);
}


ll extend_gcd(ll a, ll b, ll &x, ll &y) {  
    if (b == 0) {  
	x = 1, y = 0;  
	return a;  
    }  
    else {  
	ll r = extend_gcd(b, a % b, y, x);  
	y -= x * (a / b);  
	return r;  
    }  
}  
ll inv(ll a, ll mod) {  
    ll x, y;  
    extend_gcd(a, mod, x, y);  
    x = (x % mod + mod) % mod;  
    return x;  
}  

