ll fastExp(ll base, int p) {
	ll ret = 1;
	while (p) {
		if (p & 1) {
			ret = (ret * base) % MOD;
		}
		base = (base * base) % MOD;
		p >>= 1;
	}
	return ret;
}

ll comb(int n, int k) {
	ll ret = fact[n];
	ret = (ret * revfact[k]) % MOD;
	ret = (ret * revfact[n-k]) % MOD;
	return ret;
}

