const int K = 30;
const int maxn = 2000010;
const i64 P = 1000000000 + 7;
i64 sm[K + 1][maxn + 1];
i64 l[maxn + 1];
i64 d_26[maxn + 1], d26[maxn + 1], d25[maxn + 1], fact[maxn + 1], tcaf[maxn + 1];

i64 deg(i64 x, i64 d) {
    d %= P - 1;
    if (d < 0) d += P - 1;
    i64 y = 1;
    while (d) {
        if (d & 1) y *= x, y %= P;
        x *= x, x %= P;
        d /= 2;
    }
    return y;
}

void add(i64 &x, i64 y) {
    x += y;
    x %= P;
}

i64 cnk(int n, int k) {
    return fact[n] * tcaf[k] % P * tcaf[n - k] % P;
}

int k;

void recount() {
    if (k <= K) return;
    forn(i, maxn + 1) l[i] = 0;
    for (int i = k; i <= maxn; ++i) {
        l[i] = (l[i - 1] + d_26[i] * d25[i - k] % P * cnk(i - 1, k - 1)) % P;
    }
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);

    fact[0] = tcaf[0] = d25[0] = d_26[0] = d26[0] = 1;
    for1(i, maxn) {
        fact[i] = i * fact[i - 1] % P;
        tcaf[i] = deg(fact[i], -1);
        d25[i] = d25[i - 1] * 25 % P;
        d_26[i] = d_26[i - 1] * deg(26, -1) % P;
        d26[i] = d26[i - 1] * 26 % P;
    }

    for1(k, K) for (int i = k; i <= maxn; ++i) {
            sm[k][i] = (sm[k][i - 1] + d_26[i] * d25[i - k] % P * cnk(i - 1, k - 1)) % P;
        }

    int m;
    string s;
    int n;
    cin >> n >> s;
    k = s.size();
    n += k;
    recount();
    cout << d26[n] * (k <= K ? sm[k][n] : l[n]) % P << '\n';
}

