const ll inf = 2e18;
const int mod = 1e9 + 7;
const int N = 2e6 + 10;

int modpow(int x, int n, int m) {
	x %= m;
	int res = 1;
	while(n > 0) {
		if(n & 1)
			res = res * x % m;
		x = x * x % m;
		n >>= 1;
	}
	return res;
}

int fact[N], invfact[N];

void pre() {
	fact[0] = 1;
	for(int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i % mod;
	}
	invfact[N - 1] = modpow(fact[N - 1], mod - 2, mod);
	for(int i = N - 2; i >= 0; i--) {
		invfact[i] = invfact[i + 1] * (i + 1) % mod;
	}
}

int ncr(int x, int y) {
	if(y < 0 || y > x)
		return 0;
	int res = fact[x] * invfact[y] % mod * invfact[x - y] % mod;
	return res;
}

signed main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	pre();
	int k;
	string s;
	cin >> k >> s;
	int n = s.length();
	int ans = modpow(26, n + k, mod);
	for(int i = 0; i < n; i++) {
		ans = (ans - ncr(n + k, i) * modpow(25, n + k - i, mod) % mod + mod) % mod;
	}
	cout << ans;

	return 0;
}

