const int mod = 1e9+7;

long long mpow(long long a, int n) {
	if (n == 0) return 1;
	if (n == 1) return a;
	if (n%2) return (a * (mpow(a, n-1) % mod)) % mod;
	else {
		long long tmp = mpow(a, n/2) % mod;
		return tmp * tmp % mod;
	}
}

