    hoge1[i+1] = hoge1[i]*(diff-1);
    hoge2[i+1] = hoge2[i]*(diff);
    hoge1[i+1] %= MOD;
    hoge2[i+1] %= MOD;
  }

  ll ans = 0;
  REP(i,K+1){
    ll tmp = hoge1[i]*hoge2[K-i];
    tmp %= MOD;
    tmp *= que.ModCom(i+S.size()-1, i);
    tmp %= MOD;
    ans += tmp;
    //debug_print(i, hoge1[i], hoge2[K-i], tmp);
    ans %= MOD;
  }

  OUT(ans);

  return 0;
}

