using namespace std;

class mint {
  uint64_t value;
  static vector<uint64_t> _fact;
  static void fill(long n) {
    mint val = _fact.back();
    for (int i = _fact.size(); i <= n; ++i) {
      _fact.push_back(uint64_t(val *= i));
    }
  }

public:
  static const int32_t MOD = 1e9 + 7;
  constexpr mint(const int64_t x = 0) noexcept
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  constexpr explicit operator uint64_t() const noexcept {
    return value;
  }
  constexpr mint operator+() const noexcept {
    return mint(*this);
  }
  constexpr mint operator-() const noexcept {
    return mint(MOD - value);
  }
  constexpr mint operator+(const mint &rhs) const noexcept {
    return mint(*this) += rhs;
  }
  constexpr mint operator-(const mint &rhs) const noexcept {
    return mint(*this) -= rhs;
  }
  constexpr mint operator*(const mint &rhs) const noexcept {
    return mint(*this) *= rhs;
  }
  constexpr mint &operator+=(const mint &rhs) noexcept {
    if ((value += rhs.value) >= MOD) value -= MOD;
    return *this;
  }
  constexpr mint &operator-=(const mint &rhs) noexcept {
    return *this += MOD - rhs.value;
  }
  constexpr mint &operator*=(const mint &rhs) noexcept {
    if ((value *= rhs.value) >= MOD) value %= MOD;
    return *this;
  }
  constexpr static mint pow(mint a, long n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
  constexpr mint inv() const {
    return pow(value, MOD - 2);
  }
  constexpr mint operator/(const mint &rhs) const noexcept {
    return mint(*this) *= rhs.inv();
  }
  static mint fact(long n) {
    fill(n);
    return _fact[n];
  }
  static mint comb(long n, long k) {
    return fact(n) / fact(k) / fact(n - k);
  }
};
vector<uint64_t> mint::_fact = {1};

