// 二項係数
template<typename T> struct Combination {
    ll n_max;
    vector<T> fac, finv, inv;
    Combination(ll n_max) {
        fac.resize(n_max+1);
        finv.resize(n_max+1);
        inv.resize(n_max+1);
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[0] = 0, inv[1] = 1;
        for (int i = 2; i <= n_max; i++){
            fac[i] = fac[i - 1] * i;
            inv[i] = - inv[MOD%i] * (MOD / i);
            finv[i] = finv[i - 1] * inv[i];
        }
    }
    T C(ll n, ll k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * finv[k] * finv[n - k];
    }
    T P(ll n, ll k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * finv[n - k];
    }
    T H(ll n, ll k) {
        return C(n+k-1, k);
    }
};

using Int = ModInt<MOD>;


ll solve() {
    ll K;
    string S;
    cin >> K >> S;
    ll M = S.size();
    Combination<Int> cb(M+K+1);
    vector<Int> a1(K), a2(M);
    Int dp1(0), dp2(0);
    for ( ll k = 0; k < K; k++ ) {
        a1[k] = cb.C(M-1+k, k) * Int(25).pow(k);
        dp1 *= 26;
        dp1 += a1[k];
    }
    for ( ll k = 0; k < M; k++ ) {
        a2[k] = cb.C(K-1+k, k) * Int(25).pow(K-1);
        dp2 += a2[k] * 25;
    }
    Int ans = dp1 * 26 + dp2;
    return ans.value;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

