    ll ans = 0;
    for (int l = 0; l <= K; l++) {
        ans += tool.fast_pow(26, l) * tool.fast_pow(25, K - l) % M * tool.hcomb(s.size(), K - l) % M;
        ans %= M;
    }
    cout << ans << endl;

    return 0;
}

