typedef long long ll;

const ll MOD = 1000000007;

vector<ll> sil(3000000);

ll Pot(ll p, ll w)
{
    if (w == 0)
        return 1;
    if (w % 2 == 0)
    {
        ll pol = Pot(p, w / 2);
        return pol * pol % MOD;
    }
    return Pot(p, w - 1) * p % MOD;
}

ll Inv(ll x)
{
    return Pot(x, MOD - 2);
}

ll C(ll n, ll k)
{
    return sil[n] * (Inv(sil[k]) * Inv(sil[n - k]) % MOD) % MOD;
}

