    for (ll i = n; i <= n + k; ++i)
    {
        ll il = (C(i - 1, n - 1) * Pot(25, i - n)) % MOD;
        il = (il * Pot(26, n + k - i)) % MOD;
        odp = (odp + il) % MOD;
    }
    cout << odp;
    return 0;
}

