ll modpow(ll a, ll b) {
	if (b == 0) return 1;
	if (b & 1) return modpow(a, b - 1) * a % MOD;
	ll half = modpow(a, b / 2) % MOD;
	return (half * half) % MOD;
}

ll fact[2200000];
ll nCk(ll N, ll K) {
	ll A = fact[N], B = fact[N-K] * fact[K] % MOD; //A = n!, B = k!(n-k)!
	ll invB = modpow(B, MOD - 2); // B2 = B^(MOD-2)
	ll ans = A * invB;
	ans %= MOD;
	return ans;
}

