using namespace std;

const int N = 2e6 + 5, md = 1e9 + 7;
int fac[N], ifac[N];

int power(int x, int p) {
  int res = 1;
  while (p > 0) {
    if (p & 1) {
      (res *= x) %= md;
    }
    (x *= x) %= md;
    p >>= 1;
  }
  return res;
}

void precalc() {
  fac[0] = 1;
  for (int i = 1; i < N; i++) {
    fac[i] = fac[i - 1] * i % md;
  }
  ifac[N - 1] = power(fac[N - 1], md - 2);
  for (int i = N - 2; ~i; i--) {
    ifac[i] = ifac[i + 1] * (i + 1) % md;
  }
}

int C(int n, int k) {
  return fac[n] * ifac[k] % md * ifac[n - k] % md;
}

signed main() {
  int k;
  string s;
  cin >> k >> s;
  precalc();
  int n = s.size();
  int res = power(26, n + k);
  for (int i = 0; i < n; i++) {
    res += md - C(n + k, i) * power(25, n + k - i) % md;
    res %= md;
  }
  cout << res << '\n';
  return 0;
}

