ll binpow(ll a, ll b) {
	if (b == 0) return 1ll;
	if (b & 1) return (binpow(a, b - 1) * a) % inf;
	ll c = binpow(a, b / 2);
	return (c * c) % inf;
}

int cnk(int n, int k) {
	return 1ll * f[n] * binpow(f[k], inf - 2) % inf * 1ll * binpow(f[n - k], inf - 2) % inf;
}

