    finv[n+k]=fpow(f[n+k],mod-2);
    for(ll i=n+k-1;i>=0;i--) finv[i]=(finv[i+1]*(i+1))%mod;
    auto ch=[&](ll a,ll b)->ll
    {
        ll res=f[a];
        res=(res*finv[b])%mod;
        res=(res*finv[a-b])%mod;
