	cin >> k >> s;

	n = s.size();
	Combination com(n+k, mod);

	long long sum = 0;
	for (int i = 0; i <= k; i++) {
		sum += modpow(25, i, mod) * modpow(26, k - i, mod) * com.comb(i + n - 1, n - 1);
		sum %= mod;
	}

	cout << sum << endl;
	return 0;
}

