long long* factMemo;
long long* modInvMemo; // 数字で割るとき
long long* modInvFactMemo; // 階乗で割るとき

long long Mul(long long a, long long b) {
	long long c = a * b;
	c %= D;
	return c;
}

long long CalcModInv(long long a) {
	long long u = 1, v = 0;
	long long b = D;
	while (b) {
		long long t = a / b;
		a -= t * b;
		swap(a, b);
		u -= t * v;
		swap(u, v);
	}
	u %= D;
	if (u < 0)
		u += D;
	return u;
}

