		a = Mul(a, modInvFactMemo[len - 1]);

		// 挿入文字のパターン
		a = Mul(a, powMemo25[i]);
		a = Mul(a, powMemo26[K - i]);

		ans += a;
		ans %= D;
	}

	cout << ans << endl;

	delete[] factMemo;
	delete[] modInvMemo;
	delete[] modInvFactMemo;
	delete[] powMemo25;
	delete[] powMemo26;
	return 0;
}

