class mint {
  uint32_t value;
  static vector<uint32_t> _fact;
  static void fill(const long n) {
    mint val = _fact.back();
    for (long i = _fact.size(); i <= n; ++i) {
      _fact.push_back(val *= i);
    }
  }

public:
  static const uint32_t MOD = 1e9 + 7;
  mint(const int64_t x)
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  operator int() const {
    return value;
  }
  mint operator+(const mint y) const {
    return mint(value + y.value);
  }
  mint &operator+=(const mint a) {
    return *this = *this + a;
  }
  mint operator*(const mint y) const {
    return mint(int64_t(value) * y.value);
  }
  mint &operator*=(const mint a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(const mint y) const {
    return *this + (-y);
  }
  mint &operator-=(const mint a) {
    return *this = *this - a;
  }
  static mint fact(const long n) {
    fill(n);
    return _fact[n];
  }
  static mint pow(mint a, long n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
  mint inv() const {
    return pow(value, MOD - 2);
  }
  mint operator/(const mint y) const {
    return *this * y.inv();
  }
  static mint comb(const long n, const long k) {
    return fact(n) / fact(k) / fact(n - k);
  }
};
