  for (ll i = 1LL; i <= 2000000; i++) {
    kai[i] = kai[i - 1] * i;
    kai[i] %= MOD;
  }
  inv[2000000] = mod_pow(kai[2000000], MOD - 2LL, MOD);
  for (ll i = 1999999; i >= 0; i--) {
    inv[i] = inv[i + 1] * (i + 1);
    inv[i] %= MOD;
  }
}

ll comb(ll r, ll c) {
