const ll mod = 1000000007;

ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

ll choose(ll n, ll r) {
    ll ret = 1;
    for (ll i = n; i > n-r;--i){
        ret *= i;
        ret %= mod;
    }
    for (ll i = 1; i < r+1; ++i) {
        // ret /= i;
        ret %= mod;
        ret = ret * modinv(i,mod) % mod;
    }
    return ret;
}

