	for(ull i = 1; i < 2000005; i++)
		facMemo[i] = (facMemo[i - 1] * i) % modConst;

	ull ans = 0, sLen = (ull)(S.length());
	for(ull i = 0; i <= K; i++)
	{
		ull numLettersPart1 = K - i, numLettersPart2 = i;

		ull part1 = (choose(numLettersPart1 + sLen - 1, numLettersPart1) * fastExp(25, numLettersPart1)) % modConst;
		ull part2 = fastExp(26, numLettersPart2);

		ans += (part1 * part2) % modConst;
		ans %= modConst;
	} 

