struct Func {
    ll mod;
    vector<ll> fact, ifact;
    ll mod_pow(ll x, ll n){
        ll ans = 1;
        while(n){
            if(n & 1) ans = ans*x%mod;
            x = x*x%mod;
            n >>= 1;
        }
        return ans;
    }
    Func(ll n, ll mod) : fact(n+1), ifact(n+1), mod(mod) {
        fact[0] = 1;
        for(ll i = 1; i <= n; i++) fact[i] = fact[i-1] * i % mod;
        ifact[n] = mod_pow(fact[n], mod-2);
        for(ll i = n; i >= 1; i--) ifact[i-1] = ifact[i] * i % mod;
    }
    ll comb(ll n, ll k) {
        if (k < 0 || k > n) return 0;
        return fact[n]*ifact[k]%mod*ifact[n-k]%mod;
    }
    ll perm(ll n, ll k) {
        if (k < 0 || k > n) return 0;
        return fact[n]*ifact[n-k]%mod;
    }
};

