  for (int i = N; i <= K; i++) {
    long tmp = com(i - 1, N - 1);
    (tmp *= mpow(25, i - N)) %= MOD;
    (tmp *= mpow(26, K - i)) %= MOD;
    (ans += tmp) %= MOD;
  }
  cout << ans << "\n";
}

