ll mod = 1000000007;

ll po(ll k, ll x) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return k % mod;
  }
  ll y = po(k, x/2);
  y = y * y % mod;
  if (x % 2 == 1) {
    y = y * k % mod;
  }
  return y;
}

ll combination(ll n, ll k, const vll& frac) {
  k = min(k, n-k);
  if (k == 0) {
    return 1;
  }
  ll ret = frac.at(n);
  ll denomi = frac.at(k) * frac.at(n-k) % mod;
  ret = ret * po(denomi, mod-2) % mod;
  return ret;
}

ll mod_mult(vll& a) {
  ll ret = 1;
  for (ll x : a) {
    ret = ret * x % mod;
  }
  return ret;
}

ll calc(ll k, string& s) {
  ll m = s.length();
  ll n = k + m;
  ll ans = 0;
  vll po25(n+1), po26(n+1), frac(n+1);
  po25.at(0) = 1;
  po26.at(0) = 1;
  frac.at(0) = 1;
  rep (i, n) {
    po25.at(i + 1) = po25.at(i) * 25 % mod;
    po26.at(i + 1) = po26.at(i) * 26 % mod;
    frac.at(i + 1) = frac.at(i) * (i + 1) % mod;
  }
  FOR (i, m-1, n) {
    vll a = {combination(i, m-1, frac), po(25, i - (m-1)), po(26, n-1 - i)};
    ans = (ans + mod_mult(a)) % mod;
  }
  return ans;
}

void solve() {
  ll k;
  scan(k);
  string s;
  scan(s);
  ll ans = calc(k, s);
  print(ans);
}

int main() {
  solve();
  return 0;
}

