typedef long long ull;
const ull modConst = 1E9 + 7;

ull facMemo[2000005];
ull fastExp(ull A, ull B)
{
	if(B == 0)
		return 1 % modConst;

	ull Sqrt = fastExp(A, B / 2), ans = (Sqrt * Sqrt) % modConst;
	if(B % 2 == 1)
		ans *= A % modConst;

	return ans % modConst;
}

ull modInverse(ull X)
{
	return fastExp(X, modConst - 2);
}

ull choose(int N, int R)
{
	ull ans = (facMemo[N] * modInverse(facMemo[N - R])) % modConst;
	ans = (ans * modInverse(facMemo[R])) % modConst;

	return ans;
}

int main()
{
	ull K;
	scanf("%lld", &K);

	string S;
	cin >> S;

	facMemo[0] = 1 % modConst;
	for(ull i = 1; i < 200005; i++)
		facMemo[i] = (facMemo[i - 1] * i) % modConst;

	ull ans = 0, sLen = (ull)(S.length());
	for(ull i = 0; i <= K; i++)
	{
		ull numLettersPart1 = K - i, numLettersPart2 = i;

		ull part1 = (choose(numLettersPart1 + sLen - 1, numLettersPart1) * fastExp(25, numLettersPart1)) % modConst;
		ull part2 = fastExp(26, numLettersPart2);

		ans += (part1 * part2) % modConst;
		ans %= modConst;
	} 

	printf("%lld", ans);
}

