// Based on official editorial
vector <ll> factorials, inv_factorials;
ll mod=1e9+7;
ll modExp(ll x, ll n)
{
    if (n==0) return 1;
    if (n==1) return x%mod;
    ll ans = modExp(x,n/2);
    ans = (ans*ans)%mod;
    if (n%2) ans*=x;
    return ans%mod;
}

ll modInv(ll a)
{
    return modExp(a, mod-2);
}

void calculate(ll N)
{
    factorials.resize(N+1);
    inv_factorials.resize(N+1);
    factorials[0]=1;
    for (int i=1; i<=N; ++i) factorials[i]=(factorials[i-1]*i)%mod;
    inv_factorials[N]=modInv(factorials[N]);
    for (int i=N-1; i>=0; --i) inv_factorials[i]=((i+1)*inv_factorials[i+1])%mod;
}

ll choose(ll N, ll K)
{
    if (N<0 || K<0) return 0;
    if (K>N) return 0;
    return (((factorials[N]*inv_factorials[N-K])%mod)*inv_factorials[K])%mod;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    ll K; cin >> K;
    string S; cin >> S;
    ll N=S.length();
    calculate(N+K);
    ll total=S.length()+K;
    /*
    * Total length of resulting string = total
    * N = S.length()
    * S = S_1...S_N (S_i = character at ith position)
    * resulting string T looks like <S_1*>S_1<S_2*>S_2...<S_N*>S_N<*>
    * here <S_i*> denotes inserted characters between S_{i-1} (or start of string) and S_i
    * Length of <S_1*>+...+<S_N*>+<*> = K
    * To count distinct string, let us count number of strings such that S_i is first occurence of 
    * (whichever character is there at S_i) after S_{i-1}.
    * This means <S_i*> cannot contain the character S_i.
    * But <*> at the end of T, can have any character. 
    * This leads to the formula in the editorial
    * Ans for a particular arrangement = 25^( Sum i=1 to N (|<S_i*>|) ) * 26^(K - (Sum i=1 to N (|<S_i*>|)) )
    * Now let's iterate over all possible values for Sum i=1 to N (|<S_i*>|)
    */
    ll ans=0;
    vector <ll> power25(K+1, 1), power26(K+1,1);
    for (int i=1; i<=K; ++i) {
        power25[i]=(power25[i-1]*25)%mod;
        power26[i]=(power26[i-1]*26)%mod;
    }
    for (int i=0; i<=K; ++i) // i = len(<*>) = number of characters after S_N
    {
        // Since i is fixed, since means position of S_N must be already fixed as well.
        // Only the places for rest N-1 characters can be chosen.
        ll waysToSelectPlacesForStringS= choose(N+K-(i+1), N-1);
        ll waysToSelectCharactersInRemainingPlaces = (power25[K-i]*power26[i])%mod;
        ans=(ans+(waysToSelectPlacesForStringS*waysToSelectCharactersInRemainingPlaces)%mod)%mod;
    }
    cout << ans << "\n";
    return 0;
}

