class Combinatorics {
private:

	ll MOD;
	vector<ll> fac, inv_fac;

	ll takemod(ll a){
		ll ret = a % MOD;
		if(ret < 0) ret += MOD;
		return ret;
	}

public:

	Combinatorics(int maxn, ll _MOD)
	    : MOD(_MOD), fac(maxn + 1, 1), inv_fac(maxn + 1, 1)
	{
		// fac(i) = fac(i - 1) * i
		for(int i = 1; i <= maxn; ++i)
			fac[i] = mul(fac[i - 1], i);

		// inv_fac(maxn) = (fac(maxn)) ^ (-1)
		inv_fac[maxn] = modinverse(fac[maxn], MOD);
		// inv_fac(i) / (i + 1) = inv_fac(i + 1) => inv_fac(i) = inv_fac(i + 1) * (i + 1)
		for(int i = maxn - 1; i > 1; --i)
			inv_fac[i] = mul(inv_fac[i + 1], i + 1); 
	}

	ll add(ll a, ll b){ return takemod(a + b); }
	ll mul(ll a, ll b){ return takemod(a * b); }

	ll nPr(ll n, ll r){
		if(n < r) return 0;
		return mul(fac[n], inv_fac[n - r]);
	}

	ll nCr(ll n, ll r){
		if(n < r) return 0;
		return mul(fac[n], mul(inv_fac[n - r], inv_fac[r]));
	}

	ll count_derangements_of_length_n_from_m(ll n, ll m){
		/*
		 * Principle of Inclusion-Exclusion
		 * Let S_k be number of permutations with >= k positions fixed (as given permutation).
		 * S_k = (no of ways to choose set of k positions) * (no of ways to permute (n - k) positions from (m - k) elements)
		 *     = (n)C(k) * (m - k)P(n - k)
		 * Then, Derangements = \Sigma{i = 0 ... n} [(-1) ^ i] * S_i
		 */

		ll cou = 0;

		for(int i = 0; i <= n; ++i){
			ll curr = mul(nCr(n, i), nPr(m - i, n - i));
			cou = add(cou, i & 1 ? -curr : curr);
		}

		return cou;
	}
};

void solve(){
	const int MOD = 1e9 + 7;

	int k;
	cin >> k;

	string s;
	cin >> s;

	int n = s.size();

	ll ans = 0;

	Combinatorics combi{n + k, MOD};

	ll factor = fastpow(26, k, MOD);
	ll factor_delta = combi.mul(modinverse(26, MOD), 25);

	for(int i = 0; i <= k; ++i){
		ans = combi.add(ans, combi.mul(factor, combi.nCr(n - 1 + i, n - 1)));
		factor = combi.mul(factor, factor_delta);
	}

	cout << ans << "\n";
}

