LL fac[SIZE], inv[SIZE];
LL mypow(LL x, LL y) {
	LL res = 1;
	while (y) {
		if (y & 1)res = res * x % MOD;
		y >>= 1;
		x = x * x % MOD;
	}
	return res;
}
LL C(int x, int y) {
