struct{
    template<typename T>
    bool operator()(const T p1, const T p2) const {
        ll q1 = p1.which_quadrant();
        ll q2 = p2.which_quadrant();
        if (q1 != q2) return q1 < q2;
        // judge for parallel lines
        // if p1 cross p2 > 0 -> sin arg(p1 -> o -> p2) > 0
        return p1.cross(p2) > 0;
    }
