void cal_factor(){factor[0]=1;for(int u=1;u<MAXN;u++){factor[u]=(factor[u-1]*u)%MOD;}}
ll C(ll n,ll k){return factor[n]*qpow(factor[n-k],MOD-2)%MOD*qpow(factor[k],MOD-2)%MOD;}
void solve()
{
    cal_factor();
    ll K,N;
    string s;
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin>>K>>s;
    N=K+s.size();
    ll ans=qpow(26,N);
    for(ll k=0;k<s.size();k++){
        ans=(ans-C(N,k)*qpow(25,N-k)%MOD+MOD)%MOD;
    }
    cout<<ans;
}
int main()
{
#ifdef LOCAL
    freopen("in.txt","r",stdin);
#endif
    solve();
}

