int main(){
    int n, k;
    string s;
    cin >> k >> s;
    n = s.size();

    static modint<mod> fact[2000001], finv[2000001];
    fact[0] = 1;
    for(int i=0;i<2000000;++i) fact[i+1] = fact[i] * (i+1);
    finv[2000000] = fact[2000000].inverse();
    for(int i=2000000;i>0;--i) finv[i-1] = finv[i] * i;
    auto comb = [&](int n, int r){ return fact[n] * finv[r] * finv[n-r]; };
    modint<mod> ans = 0;
    for(int x=n;x<=n+k;++x) ans += comb(n+k, x) * pow(modint<mod>{25}, n+k-x);
    cout << ans << endl;

    return 0;
}

