  if(dp.find({i,j}) != dp.end()) return dp[{i,j}];
  if(j == n){
    return dp[{i,j}] = Rec(i+1,j)*26;
  } else {
    return dp[{i,j}] = Rec(i+1,j)*25 + Rec(i+1,j+1);
  }
  return 0;
}

