        mint sum = cnk.get(n+k-i,k-i) - 1;
        sum *= cnk.get(n+k,i);
        sum *= power(25,i);

        ans += sum;
    }
    mint all = power(26,k);
    all *= cnk.get(n+k,k);
    cout << (all - ans)() << endl;
}

