ll power(ll x, ll y, ll p = mod) {
    ll res = 1;
    x      = x % p;
    while (y) {
        if (y & 1) res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

ll modInverse(ll n, ll p = mod) { return power(n, p - 2, p); }

ll fac[MX + 5];
void init(ll p = mod) {
    fac[0] = 1;
    for (int i = 1; i <= MX; i++) fac[i] = fac[i - 1] * i % p;
}

ll C(ll n, ll r, ll p = mod) {
    if (r == 0) return 1;
    if (n - r < r) return C(n, n - r, p);
    if (n <= MX)
        return (fac[n] * modInverse(fac[r], p) % p * modInverse(fac[n - r], p) %
                p) %
               p;
    ll num = 1, den = 1;
    for (int i = 0; i < r; ++i) {
        (den *= i + 1) %= p;
        (num *= (n - i)) %= p;
    }
    return num * modInverse(den, p) % p;
}


