#define MOD 1000000007

ULL RepSq(ULL n, ULL m, ULL mod);
ULL Comb(ULL a, ULL b, ULL mod);

int main() {
	int K, a, iCnt = 0;
	scanf("%d", &K);

	getchar();
	while ((a = getchar()) != '\n')
		iCnt++;
	ULL ans = 0;

	for (int i = 0; i <= K; i++) {
		//inserted place patterns
		ULL tmpChairs4OtherLetters = iCnt + K - i - 1;
		//printf("tmpChairs4OtherLetters	%llu\n", tmpChairs4OtherLetters);
		ULL insPlacePatterns = Comb(tmpChairs4OtherLetters, (ULL)(iCnt - 1), (ULL)MOD);

		//inserted letter patterns
		ULL insLetsBeforeLastLet = K - i;
		//printf("insLetsBeforeLastLet	%llu\n", insLetsBeforeLastLet);
		ULL insLetPatterns = RepSq((ULL)26, (ULL)i, (ULL)MOD);
		insLetPatterns *= RepSq((ULL)25, insLetsBeforeLastLet, (ULL)MOD);
		insLetPatterns %= MOD;
//		printf("insLetPatterns		%llu\n", insLetPatterns);
//		printf("insPlacePatterns	%llu\n", insPlacePatterns);

		ans += (insPlacePatterns * insLetPatterns % MOD);
		ans %= MOD;
	}

	printf("%lld\n", ans);

	return 0;
}

ULL RepSq(ULL n, ULL m, ULL mod){
    if (m == 0)	return 1;
    if (m == 1) return n % mod;

	if (m % 2 == 0) {
        ULL t = RepSq(n, m / 2, mod);
        return t * t % mod;
    }

    return n * RepSq(n, m - 1, mod) % mod;
}

ULL Comb(ULL a, ULL b, ULL mod) {
	if (a == b || !b)
		return 1;

	//Fermat's little theorem
	ULL A = 1, B = 1, AB = 1, ab = a - b;

	while (a > 0) {
		A *= a--;
		A %= mod;
	}
	while (b > 0) {
		B *= b--;
		B %= mod;
	}
	while (ab > 0) {
		AB *= ab--;
		AB %= mod;
	}
	B = RepSq(B, mod - 2, mod);
	AB = RepSq(AB, mod - 2, mod);

	return (A * B % mod) * AB % mod;
}

