ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

struct combination {
    vector<modint_t> fact, ifact;
    combination(int n)
        : fact(n + 1)
        , ifact(n + 1)
    {
        fact[0] = 1;
        for (int i = 1; i <= n; ++i)
            fact[i] = fact[i - 1] * modint_t(i);
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i)
            ifact[i - 1] = ifact[i] * modint_t(i);
    }
    modint_t operator()(int n, int k)
    {
        if (k < 0 || k > n)
            return 0;
        return fact[n] * ifact[k] * ifact[n - k];
    }
};

void solution()
{
    int k;
    string s;
    cin >> k >> s;
    const int n = s.size();

    combination comb(n+k);

    modint_t answer;
    for(int i = 0; i <= k; ++i){
        answer += modint_t(26).pow(k-1) * comb(i+n-1,n-1) * modint_t(25).pow(i);
    }
    cout << answer << '\n';
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);
    solution();
    return 0;
}

