#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
#define int long long
const int N = 1000001;
const int mod = 1e9 + 7;
LL a[N + 20], fact[N + 20], inv[N + 20];
LL qpow(LL a, LL b, LL p = mod) {
	LL ans = 1;
	for (; b; b >>= 1) {
		if (b & 1) ans = ans * a % p;
		a = a * a % p;
	}
	return ans % p;
}
void prework() {
	fact[0] = 1;
	for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % mod;
	inv[N - 1] = qpow(fact[N - 1], mod - 2) % mod;
	for (int i = N - 2; ~i; i--) inv[i] = inv[i + 1] * (i + 1) % mod;
}
LL nCr(int n, int r) {  // calculate nCr
	if (n - r < 0 || r < 0) return 0;
	return fact[n] % mod * inv[r] % mod * inv[n - r] % mod % mod;
}
main() {
  int k; cin >> k;
  string s; cin >> s;
  int n = s.length();
  prework();
  int S = 26;  // alphabet size
  LL ans = qpow(S, n + k);
  for (int r = 0; r < n; r++) {
    LL v = nCr(n + k, r) * qpow(S - 1, n + k - r) % mod;
    ans = (ans - v + mod * 10) % mod;
  }
  cout << ans << endl;
  return 0;
}

