	pw25[0] = pw26[0] = fac[0] = 1;
	for(int i=1;i<k+len;i++) {
		pw25[i] = ma.mul(pw25[i-1], 25);
		pw26[i] = ma.mul(pw26[i-1], 26);
		fac[i] = ma.mul(fac[i-1], i);
	}
	rfac[k+len-1] = ma.rev(fac[k+len-1]);
	for(int i=k+len-2;i>=0;i--)
		rfac[i] = ma.mul(rfac[i+1], i+1);

	int ans = 0;
