    combination c(n+k);
    mint ans = 0;
    for(int i = 0; i <= k; i++){
        mint now = mint(26).pow(k-i);
        now *= mint(25).pow(i);
        now *= c(i+n-1, n-1);
        ans += now;
    }
    cout << ans << endl;
}

