ll powmod(ll x, int y)
{
	ll res=1;
	while(y){
		if(y&1) (res*=x)%=MOD;
		(x*=x)%=MOD;
		y>>=1;
	}
	return res;
}

ll nCk(int n, int k)
{
    if(k<0||k>n) return 0;
    return (((fact[n]*invf[n-k])%MOD)*invf[k])%MOD;
}

void solve()
{
	fact[0]=1;
	for(int i=1;i<MAX_N;++i) fact[i]=1LL*i*fact[i-1]%MOD;
	invf[MAX_N-1]=powmod(fact[MAX_N-1], MOD-2);
	for(int i=MAX_N-2;i>=0;--i) invf[i]=1LL*invf[i+1]*(i+1)%MOD;

	ll res = 0;
	const int n = S.length();
	for(int len=0;len<n;++len){
		(res+=1LL*nCk(n+K, len)*powmod(25,n+K-len)%MOD)%=MOD;
	}
	ll ans = (powmod(26,n+K)-res+MOD)%MOD;
	cout<<ans;
}

