using namespace std;
typedef long long ll;

const double PI = 3.1415926535897932384626;
const ll MODN = 1000000007;
const ll MODN2 = 998244353;
const double EPS = 1e-10;

class ModInt{
public:
    long long n;
    int p;

    ModInt(){
    }

    //値と割る値を受け取って、オブジェクトを返す
    ModInt(long long _n, int _p){
        p = _p;
        n = _n % _p;

        //負の値を受け取ったときには正の値に戻す
        if(n < 0){
            n += p;
        }
    }

    ModInt operator+(ModInt a){

        ModInt tmp = ModInt(*this);

        tmp.n += a.n;

        if(tmp.n > tmp.p){
            tmp.n -= tmp.p;
        }

        return tmp;
    }

    ModInt operator-(ModInt a){

        ModInt tmp = ModInt(*this);

        tmp.n -= a.n;

        if(tmp.n < 0){
            tmp.n += tmp.p;
        }

        return tmp;
    }

    ModInt operator*(ModInt a){

        ModInt tmp = ModInt(*this);

        tmp.n = (tmp.n * a.n) % tmp.p;

        return tmp;
    }

    int modpow(int b, int k){
        if(k == 0){
            return 1;
        }else if(k % 2 == 1){
            long long tmp = b;
            tmp = tmp * modpow(b, k - 1) % p;

            return tmp;
        }else{
            long long tmp = modpow(b, k / 2);
            return tmp * tmp % p;
        }
    }

    int modinv(int b){
        return modpow(b, p - 2);
    }

    ModInt operator/(ModInt a){

        ModInt tmp = ModInt(*this);

        tmp.n = tmp.n * modinv(a.n) % tmp.p;
        return tmp;
    }
};

int main(){

    int k;
    cin >> k;
    string s;
    cin >> s;

    int size = s.size();

    vector<ModInt> fact(k + size + 1);
    fact[0] = ModInt(1, MODN);

    for(int i = 1; i <= k + size; i++){
        fact[i] = fact[i - 1] * ModInt(i, MODN);
    }

    function<ModInt(int, int)> combi = [&](int n, int m) -> ModInt{
        return fact[n] / fact[n - m] / fact[m];
    };

    ModInt ans = ModInt(0, MODN);

    vector<ModInt> pow25(k + size + 1, ModInt(1, MODN));
    vector<ModInt> pow26(k + size + 1, ModInt(1, MODN));

    for(int i = 1; i <= k + size; i++){
        pow25[i] = pow25[i - 1] * ModInt(25, MODN);
    }

    for(int i = 1; i <= k + size; i++){
        pow26[i] = pow26[i - 1] * ModInt(26, MODN);
    }

    for(int i = size; i <= size + k; i++){

        int before = i - size;
        int after = size + k - i;

        ans = ans + combi(i - 1, size - 1) * pow25[before] * pow26[after];
    }

    cout << ans.n << endl;

    return 0;
}

