#include <bits/stdc++.h>
using namespace std;

constexpr int64_t mod = 1000000007;
vector<int64_t> fact, inv;

int64_t power(int64_t n, int64_t k) {
  if (k == 0) return 1;
  int64_t res = power(n * n % mod, k / 2);
  if (k % 2) {
    res = res * n % mod;
  }
  return res;
}

void init(int n) {
  fact.push_back(1);
  inv.push_back(1);
  for (int i = 1; i <= n; i++) {
    fact.push_back(i * fact.back() % mod);
    inv.push_back(power(fact.back(), mod - 2));
  }
}

int64_t ncr(int64_t n, int64_t r) {
  if (r < 0 or n - r < 0) return 0;
  return fact.at(n) * inv.at(r) % mod * inv.at(n - r) % mod;
}

