ll laip(ll a, ll b, ll liek) {
	a=a%liek;
	if (b==0) {return 1;}
	if (b==1) {return a;}
	ll c=(a*a)%liek;
	ll x=laip(c,b/2,liek);
	if (b%2==0) {return x;}
	else {return (a*x)%liek;}
	}


ll cnk (int i, int s, vector <ll> &F) {
	ll li=1000000006-1;
	ll liek=li+2;
	ll a=F[i];
	ll b=F[s];
	ll c=F[i-s];
	ll bb=laip(b,li,liek);
	ll cc=laip(c,li,liek);
	ll x=a*bb;
	x=x%liek;
	x=x*cc;
	x=x%liek;
	return x;
	}


