ll fp(ll base, ll exp)
{
    if (exp == 0)
        return 1;
    ll ans = fp(base, exp / 2);
    ans = (ans * ans) % mod;
    if (exp % 2 != 0)
        ans = (ans * (base % mod)) % mod;
    return ans;
}

void calcFacAndInv(ll n)
{
    fact[0] = inv[0] = 1;
    for (ll i = 1; i <= n; i++)
    {
        fact[i] = (i * fact[i - 1]) % mod;
        inv[i] = fp(fact[i], mod - 2);
    }
}

ll ncr(ll n, ll r)
{
    return ((fact[n] * inv[r]) % mod * inv[n - r]) % mod;
}

int main()
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    calcFacAndInv(N-1);

    cin >> k >> s;

    ll ans = 0 , sz=s.size() , n = sz+k;

    for(int i=sz; i<=n; i++)
    {
        ll tmp = (ncr(i-1 , sz-1)*fp(25,i-sz))%mod;
        tmp = (tmp*fp(26,n-i))%mod;
        ans = (ans + tmp)%mod;
    }

    cout << ans << '\n';

    return 0;
}

