const int NMAX = 1010000;
ll fac[NMAX],finv[NMAX],inv[NMAX];
void combinit(){
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;

	for(int i = 2; i <= NMAX-1; ++i){
		fac[i] = fac[i-1] * i % MOD;
		inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
		finv[i] = finv[i-1] * inv[i] % MOD;
	}
}

long long comb(int n,int r){
	if (n<r) return 0;
	if (n < 0 || r < 0) return 0;
	return fac[n] * (finv[r] * finv[n-r] % MOD) % MOD;
}

int main() {
    combinit();
    ll K; cin >> K;
    string S; cin >> S;
    ll N = S.length();
    mint ans = 0;
    FORq(l,N,N+K){
        ans += (mint)comb(l-1,N-1) * modpow((mint)25,l-N) * modpow((mint)26,N+K-l);
    }
    cout << ans << endl;
}

