int add(int a, int b){
	a += b;
	if(a >= mod) a -= mod;
	return a;
}

int mul(int a, int b){
	return 1ll * a * b % mod;
}

int pwr(int a, int b){
	int r = 1;
	for(; b; b>>=1, a = mul(a,a))
		if(b&1)
			r = mul(r, a);
	return r;
}

int fact[N+5], ifact[N+5];

void init(){
	fact[0] = 1;
	for(int i = 1; i < N; i++)
		fact[i] = mul(i, fact[i-1]);
	ifact[N-1] = pwr(fact[N-1], mod-2);
	for(int i = N-2; i >= 0; i--)
		ifact[i] = mul(ifact[i+1], i+1);
}

int ncr(int n, int r){
	if(n < r) return 0;
	return mul(fact[n], mul(ifact[r], ifact[n-r]));
}

void solve(){
	init();
	int k;
	string s;
	cin >> k >> s;
	int sum = 0, len = k + sz(s);
	for(int m = 0; m < sz(s); m++){
		sum = add(sum, mul(ncr(len, m), pwr(25, len-m)));
	}
	int total = pwr(26, len);
	total = add(total, -sum+mod);
	cout << total << '\n';
}

