  vector<mint> pow26(N + K + 1);
  pow25[0] = pow26[0] = 1;
  cache.resize(N + K + 1);
  cached.resize(N + K + 1);
  REP(i, N + K) {
    pow25[i + 1] = pow25[i] * 25;
    pow26[i + 1] = pow26[i] * 26;
  }

