  for (int i = 2000000; i > 0; --i)
    finv[i - 1] = finv[i] * modint(i);
  auto comb = [&](int n, int r) { return fact[n] * finv[r] * finv[n - r]; };
  modint ans = 0;
  for (int x = n; x <= n + k; ++x)
    ans += comb(n + k, x) * modint::pow(25, n + k - x);
  cout << 1 + ans << endl;

  return 0;
}

