struct combination {
  vi fact, ifact;
  combination(int n): fact(n + 1), ifact(n + 1) {
    assert(n < MOD);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = m_mul(fact[i - 1], i);
    ifact[n] = m_inv(fact[n]);
    for (int i = n; i >= 1; --i) ifact[i-1] = m_mul(ifact[i], i);
  }
  int operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    return m_mul(fact[n], ifact[k], ifact[n - k]);
  }
} comb(2000001);

void solve(int k, string s) {
  int n = sz(s);
  int ans = 0;
  rep(i, k + 1) {
    int c = comb(n + k - i - 1, n - 1);
    c = m_mul(c, m_mul(m_bipow(25, k - i), m_bipow(26, i)));
    ans = m_add(ans, c);
  }
  COUT(ans);
}


