lli comb(int n, int k)
{
  lli res = fac[n];
  res *= facrev[k];
  res %= MOD;
  res *= facrev[n - k];
  res %= MOD;
  return res;
}

lli solve() // ここに処理を書く。型はansに合わせる。
{
  int N = SIZ(S);
  fac[0] = 1;
  pow25[0] = 1;
  pow26[0] = 1;

  FOR(n, 1, L)
  {
    fac[n] = (n * fac[n - 1]) % MOD;
    pow25[n] = (25 * pow25[n - 1]) % MOD;
    pow26[n] = (26 * pow26[n - 1]) % MOD;
  }

  facrev[L - 1] = pow_fast(fac[L - 1], MOD - 2, MOD);
  REP_R(n, L - 1)
  {
    facrev[n] = ((n + 1) * facrev[n + 1]) % MOD;
  }

  lli ret = 0;

  FOR(nl, N, N + K + 1)
  {
    lli res = comb(nl-1, N-1);
    res *= pow25[nl - N];
    res %= MOD;
    res *= pow26[N + K - nl];
    res %= MOD;
    ret += res;
    ret %= MOD;
  }
  return ret;
}

