long long power(long long X,long long Y,long long P){
  vector<long long> digit2(1000),XX(1000);
  long long I,N,mod;
  I=0;

  if(Y==0){
    return 1;
  }

  while(Y!=0){
    digit2.at(I)=Y%2;
    Y=Y/2;
    I++;
  }
  N=I;

  XX.at(0)=X%P;
  for(I=1;I<N;I++){
    XX.at(I)=(XX.at(I-1)*XX.at(I-1))%P;
  }

  mod=1;
  for(I=0;I<N;I++){
    if(digit2.at(I)==1){
      mod=(mod*XX.at(I))%P;
    }
  }

  if(mod<0){
    mod=mod+P;
  }

  return mod;
}

