template <std::uint_fast64_t Modulus> class modint {

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
	*this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

template <std::uint_fast64_t Modulus>
modint<Modulus> pow(modint<Modulus> x, u64 exp){
  modint<Modulus> ret = 1;

  for(;exp>0;exp>>=1,x=x*x){
    if(exp%2==1) ret = ret * x;
  }
  return ret;

}

void solve(void){

  int k;
  std::cin >> k;
  std::string s;
  std::cin >> s;

  u64 total_len = k + s.size();

  modint<1000000007> ret = 0;
  modint<1000000007> combi = 1;
  for(int i=s.size(); i<=total_len; i++){
    if(i != s.size()){
      combi *= i-1;
      combi /= i-s.size();
    }

    modint<1000000007> tmp1 = 25;
    modint<1000000007> tmp2 = 26;
    tmp1 = pow(tmp1, i-s.size());
    tmp2 = pow(tmp2, total_len-i);
    //std::cout << tmp1.a << " " << tmp2.a << " " << combi.a << std::endl;
    ret += tmp1 * tmp2 * combi; 

  }

  std::cout << ret.a << std::endl;

}

