i64 bpow(i64 a, i64 p) {
    if (p == 1) {
        return a;
    }
    if (p == 0) {
        return 1;
    }

    i64 res = bpow(a, p / 2);
    res *= res;
    res %= M;

    if (p % 2) {
        res *= a;
        res %= M;
    }

    return res;
}

i64 inv(i64 a) {
    return bpow(a, M - 2);
}

