	scanf("%s", s);
	n = strlen(s);
	init();
	ll ans = 0;
	for (int i = 0; i <= k; i++) {
		ans = (ans + power(26, i)*C(n + k - i - 1, n - 1) % mod*power(25, k - i) % mod) % mod;
	}
