  static void fill(const uint64_t n) {
    mint val = _fact.back();
    for (uint64_t i = _fact.size(); i <= n; ++i) {
      _fact.push_back(val *= i);
    }
  }

public:
  static const uint32_t MOD = 1e9 + 7;
  mint(const int64_t x)
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  operator int() const {
    return value;
  }
  mint operator+(const mint &y) const {
    return mint(value + y.value);
  }
  mint &operator+=(const mint &a) {
    return *this = *this + a;
  }
  mint operator*(const mint &y) const {
    return mint(int64_t(value) * y.value);
  }
  mint &operator*=(const mint &a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(const mint &y) const {
    return *this + (-y);
  }
  mint &operator-=(const mint &a) {
    return *this = *this - a;
  }
  static mint fact(const uint64_t n) {
    fill(n);
    return _fact[n];
  }
  static mint pow(mint a, uint64_t n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
