	rep(i, k+1) {
		int tmp = modpow(25, k - i);
		tmp *= modpow(26, i);
		tmp %= mod;
		tmp *= nCk((k -i+n-1), (n - 1));
		tmp %= mod;
		ans += tmp;
		ans %= mod;
	}
	print(ans);
}

