            if(p&1) r = r*b%MOD;
            b = (b*b)%MOD; 
            p >>= 1; 
        } return r;
    }
    Comb(){
        fac[0] = inv[0] = 1;
        for(int i = 1; i < N; i++){
            fac[i] = fac[i-1]*i%MOD;
        }
        inv[N-1] = modPow(fac[N-1], MOD-2);
        for(int i = N-2; i >= 0; i--){
            inv[i] = inv[i+1]*(i+1)%MOD;
        }
    }
    int ncr(int n, int r){
        if(r > n || r < 0 || n < 0) return 0;
        return fac[n]*inv[r]%MOD*inv[n-r]%MOD;
