lli power(lli base,lli power)
{
    base %= mod;
    lli ans = 1;

    while(power > 0)
    {
        if (power%2)
        {
            ans *= base;
            ans %= mod;
        }

        base *= base;
        base %= mod;
        power /= 2;
    }

    return ans;
}

