        fact[i] = (fact[i-1] * i) % MOD;
        frev[i] = rev(fact[i], MOD-2);
    }

    ll size = S.size();

    ll ans = 0;
    for(ll m = 0; m <= K; m++){
        ll right = mod_pow(26, m, MOD);
        ll left = mod_pow(25, K-m, MOD);
        //ll com = comb_mod(K-m+size-1, size-1, MOD);
        ll com = comb(K-m+size-1, size-1);

        ll add = right * left;
        add %= MOD;
        add *= com;
        add %= MOD;

        ans += add;
        ans %= MOD;
    }

