int po(int x, int y) {
    int ans = 1;
    while (y > 0) {
        if (y & 1) ans = static_cast<long>(ans) * x % MOD;
        x = static_cast<long>(x) * x % MOD;
        y >>= 1;
    }
    return ans;
}

int fac[MAX_N + MAX_K], inv[MAX_N + MAX_K];

int main() {
    scanf("%d", &k);
    scanf("%s", s);
    int n = strlen(s);

    fac[0] = 1;
    for (int i = 1; i <= n + k - 1; i++) {
        fac[i] = static_cast<long>(fac[i - 1]) * i % MOD;
    }
    inv[n + k - 1] = po(fac[n + k - 1], MOD - 2);
    for (int i = n + k - 2; i >= 0; i--) {
        inv[i] = static_cast<long>(inv[i + 1]) * (i + 1) % MOD;
    }
    pow26[0] = 1;
    for (int i = 1; i <= k; i++) {
        pow26[i] = static_cast<long>(pow26[i - 1]) * 26 % MOD;
    }

    int ans = 0;
    for (int i = 0, pow25 = 1; i <= k; i++) {
        int temp = static_cast<long>(fac[n + i - 1]) * inv[n - 1] % MOD
                 * inv[i] % MOD * pow25 % MOD * pow26[k - i] % MOD;
        ans = (ans + temp) % MOD;
        pow25 = static_cast<long>(pow25) * 25 % MOD;
    }
    printf("%d\n", ans);
    return 0;
}

