// n^e mod m
template<typename T = int> T modpow(T n, T e, T m) {
  T result = 1;
  while (e > 0) {
    if (e & 1) result = (result * n) % m;
    e >>= 1;
    n = (n * n) % m;
  }
  return result;
}

