const int MOD = 1000000007;

const int MAX = 2000005;


//---------------------------------------------------------------------------------------------------
LL f[MAX];
void init() 
{
    f[0] = 1;
    for(int i = 1; i < MAX; ++i) f[i] = (f[i - 1] * i) % MOD;
}

//---------------------------------------------------------------------------------------------------
LL inv(LL x) 
{
    LL res = 1;
    LL k = MOD - 2;
    LL y = x;
    while (k) {
        if (k & 1) res = (res * y) % MOD;
        y = (y * y) % MOD;
        k /= 2;
    }
    return res;
}
//---------------------------------------------------------------------------------------------------
LL comb(int n, int k) 
{
    LL a = f[n]; // = n!
    LL b = f[n-k]; // = (n-k)!
    LL c = f[k]; // = k!

    LL bc = (b * c) % MOD;

    return (a * inv(bc)) % MOD;
}


class Mint {
public:
  typedef long long val_type;

  Mint(val_type x=0, int m=MOD) : val((x%m+m)%m), mod(m) {}
  val_type value() const { return val; }
  Mint& operator+=(const Mint a) {
    if ((val += a.val) >= mod) val -= mod;
    return *this;
  }
  Mint& operator-=(const Mint a) {
    if ((val += mod-a.val) >= mod) val -= mod;
    return *this;
  }
  Mint& operator*=(const Mint a) {
    (val *= a.val) %= mod;
    return *this;
  }
  Mint operator+(const Mint a) const {
    Mint res(*this);
    return res+=a;
  }
  Mint operator-(const Mint a) const {
    Mint res(*this);
    return res-=a;
  }
  Mint operator*(const Mint a) const {
    Mint res(*this);
    return res*=a;
  }
  Mint pow(val_type t) const {
    if (!t) return 1;
    Mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  Mint inv() const {
    return pow(mod-2);
  }
  Mint& operator/=(const Mint a) {
    return (*this) *= a.inv();
  }
  Mint operator/(const Mint a) const {
    Mint res(*this);
    return res/=a;
  }

private:
  val_type val;
  int mod;
};


