int pow1(int x, int y){
    if (y == 0){
        return 1;
    }
    if (y % 2 == 0){
        return pow1(x*x % C, y/2);
    }
    return pow1(x, y-1)*x % C;
}

void facts(int n){
    for (int q = 1; q <= n; q++){
        fact.push_back(fact.back()*q % C);
    }
}

int c(int k, int n){
    if (k > n){
        return 0;
    }
    return fact[n]*pow1(fact[k], C-2) % C*pow1(fact[n-k], C-2) % C;
}

