ll factorial(ll n,ll mod=mod){
  static ll dp[4000000];
  static ll max_n=0;
  dp[0] = 1;
  while(n > max_n){
      dp[max_n+1] = dp[max_n]*(max_n+1) % mod;
      max_n++;
  }
  return dp[n];
}

ll powl(ll x,ll r,ll mod=mod){
  ll ret = 1;
  for(;r != 0;r >>= 1){
    if(r&1 != 0) ret *= x,ret %= mod;
    x *= x,x %= mod;
  }
  return ret;
}

ll inverse(ll x,ll mod=mod){
  return powl(x,mod-2,mod);
}

ll combination(ll n,ll m,ll mod){
  if(n < m) return 0;
  return (((factorial(n,mod)*inverse(factorial(m,mod),mod))%mod)*inverse(factorial(n-m,mod),mod))%mod;
}


