    for(ll i = n;i <= n+k;i++){
        ret += (combination(i-1, n-1, mod) * powl(25, i-n, mod) % mod) * powl(26, n+k-i) % mod;
        ret %= mod;
    }
    return ret;

}

int main(){
    cin >> k;
    cin >> s;
    n = s.size();
    cout << solve2(k, n) << endl;
}

