// index が条件を満たすかどうか
bool isOK(vector<ll>& v, int index, int key, bool flag)
{
	if (flag) {

		if (v[index] >= key)
			return true;
		else
			return false;
	}
	else {
		if (v[index] > key)
			return true;
		else
			return false;
	}
}

// 汎用的な二分探索
// flag == 1 >=, flag == 0 >
ll bs(vector<ll>& v, ll key, bool flag)
{
	int ng = -1;	//「index = 0」が条件を満たすこともあるので、初期値は -1
	int ok = SZ(v); // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1)
	{
		int mid = (ok + ng) / 2;

		if (isOK(v, mid, key, flag))
			ok = mid;
		else
			ng = mid;
	}
	return ok;
}

// 最大公約数
ll gcd(ll a, ll b)
{
	if (a < b)
		swap(a, b);
	ll r = a % b;
	while (r != 0)
	{
		a = b;
		b = r;
		r = a % b;
	}
	return b;
}

