ull fastExp(ull A, ull B)
{
	if(B == 0)
		return 1 % modConst;

	ull Sqrt = fastExp(A, B / 2), ans = (Sqrt * Sqrt) % modConst;
	if(B % 2 == 1)
		ans *= A % modConst;

	return ans % modConst;
}

ull modInverse(ull X)
{
	return fastExp(X, modConst - 2);
}

ull choose(int N, int R)
{
	if(N < R)
		return 0;

	ull ans = (facMemo[N] * modInverse(facMemo[N - R])) % modConst;
	ans = (ans * modInverse(facMemo[R])) % modConst;

	return ans;
}

