/** * Raises a number to the given power using iterative fast power algorithm. * Note that if (base=0, exp=0) is passed to the function it will return 1. * * Complexity: O(log(exp)) * * @param base the base number. * @param exp the exponent. * @param mod the modulus. * * @return ((base^exp) % mod). */
template<class T>
T power(T base, T exp, T mod) { 
T ans = 1; 
base %= mod; 
while (exp > 0) { 
if (exp & 1) ans = (ans * base) % mod; 
exp >>= 1; 
base = (base * base) % mod; 
} 
return ans;
} 
template<class T>
T modInverse(T a, T m) { return power(a, m - 2, m);} 

