class mint {
  int value;
  static vector<int> *_fact;
  static vector<int> *_finv;

public:
  static const int MOD = 1e9 + 7;
  mint(long long x)
      : value((x % MOD + MOD) % MOD) {}
  mint operator+(mint y) const {
    return mint(value + y.value);
  }
  mint &operator+=(mint a) {
    return *this = *this + a;
  }
  mint operator*(mint y) const {
    return mint(long(value) * y.value);
  }
  mint &operator*=(mint a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(mint y) const {
    return *this + (-y);
  }
  mint &operator-=(mint a) {
    return *this = *this - a;
  }
  operator int() const {
    return value;
  }
  static mint pow(mint a, int n) {
    if (n <= 0) {
      return 1;
    }
    mint half = mint::pow(a, n / 2);
    return n % 2 ? half * half * a : half * half;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static void init(int n) {
    _fact = new vector<int>(n + 1);
    _finv = new vector<int>(n + 1);
    (*_fact)[0] = (*_finv)[0] = 1;
    mint val = 1;
    for (int i = 1; i <= n; i++) {
      val *= i;
      (*_fact)[i] = val;
      (*_finv)[i] = val.inv();
    }
  }
  static mint fact(int n) {
    return (*_fact)[n];
  }
  static mint finv(int n) {
    return (*_finv)[n];
  }
  static mint comb(int n, int k) {
    return fact(n) * finv(k) * finv(n - k);
  }
};
