/*
k = 1, s = "aa"
aaa ... aaz 26
aba ... aza 25
baa ... zaa 25
-> 76
k = 1, s = "ab"
aba ... abz 26
aab, acb ... azb 25
bab ... zab
-> 76
*/

ll mod = 1000000007;

ll po(ll k, ll x) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return k % mod;
  }
  ll y = po(k, x/2);
  y = y * y % mod;
  if (x % 2 == 1) {
    y = y * k % mod;
  }
  return y;
}

ll combination(ll n, ll k) {
  k = min(k, n-k);
  if (k == 0) {
    return 1;
  }
  ll ret = 1;
  FOR (i, n-k+1, n+1) {
    ret = ret * i % mod;
  }
  ll denomi = 1; // denominator
  FOR (i, 1, k+1) {
    denomi = denomi * i % mod;
  }
  ret = ret * po(denomi, mod-2) % mod; // inverse
  return ret;
}

ll calc(ll k, string& s) {
  ll m = s.length();
  ll n = k + m;
  ll ans = 0;
  FOR (i, m-1, n) {
    ans = (ans + combination(i, m-1) * po(25, i - (m-1)) % mod * po(26, n-1 - i)) % mod;
  }
  return ans;
}

void solve() {
  ll k;
  scan(k);
  string s;
  scan(s);
  ll ans = calc(k, s);
  print(ans);
}

int main() {
  solve();
  return 0;
}

