ll modpow(ll p, ll q) {
	ll ans = 1;
	ll pp = p % MOD;
	while (q) {
		if (q & 1) {
			ans *= pp;
			ans %= MOD;
		}
		q = q >> 1;
		pp *= pp;
		pp %= MOD;
	}
	return ans;
}
V<ll> fac, invfac;
void precom(int n) {
	fac.resize(0);invfac.resize(0);
	rep(i, n + 1) {
		if (i == 0)fac.push_back(1);
		else fac.push_back((fac[i - 1] * i) % MOD);
		invfac.push_back(modpow(fac[i], MOD - 2));
