using namespace std;
typedef long long int lli;
const lli M=1e9+7,N=1e6+5;
lli fact[N];

lli binpow(lli a,lli b) 
{
    if (b == 0) return 1;
    lli res = binpow(a,b/2);
    res= (res*res)%M;

    if(b%2) return (res*a)%M;
    return res;
}

lli inv(lli a)
{
    return binpow(a,M-2);
}

lli add(lli a, lli b)
{
	lli res = a + b;
	if(res >= M)
		return res - M;
	return res;
}

lli mul(lli a, lli b)
{
	lli  res = a * b;
	if(res >= M)
		return res % M;
	return res;
}

lli sub(lli a, lli b)
{
	return (a%M -b%M +M) %M;
}

void pre()
{
    fact[0]=1;
    for(int i=1;i<N;i++)
        fact[i] = mul(fact[i-1], i);
}

lli ncr(lli n, lli r)
{
    return mul(fact[n], inv(mul(fact[n-r], fact[r])));    
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    pre();

    lli k;
    string s;
    cin>>k>>s;
    lli i,n=s.length(),ans=binpow(26, n+k);

    for(i=0;i<n;i++) ans=sub(ans, mul(ncr(n+k, i), binpow(25, n+k-i)));
    cout<<ans;
    return 0;
}

