const ll md = 1e9 + 7;

void add_self(ll& a, ll b) {
    a = MOD((a + b), md);
}

void sub_self(ll& a, ll b) {
    a = MOD((a - b), md);
}

void mul_self(ll& a, ll b) {
    a = MOD((a * b), md);
}

ll power(ll a, ll b) {
    ll res = 1;
    while (b > 0) {
        if (b & 1) {
            mul_self(res, a);
        }
        mul_self(a, a);
        b >>= 1;
    }
    return res;
}

ll mod_inverse(ll a) {
    return power(a, md-2); // only when md is prime
}

vll factorial;
void computeFactorials(ll n) {
    factorial.resize(n + 1);
    factorial[0] = 1;
    for (ll i = 1; i <= n; i++) {
        factorial[i] = MOD(factorial[i - 1] * i, md);
    }
}

ll choose(ll n, ll k) {
    ll a = mod_inverse(factorial[k]);
    ll b = mod_inverse(factorial[n - k]);
    ll ab = MOD(a * b, md);
    return MOD(factorial[n] * ab, md);
}

void solve() {
    ll k;
