    computeFactorials(n+k);
    ll res = 0;
    FOR(i, 0, k+1) {
        ll cur = 1;
        mul_self(cur, power(26, i));
        mul_self(cur, choose(n+k-1-i, n-1));
        mul_self(cur, power(25, k-i));
        res += cur;
    }
    // cout << fixed << setprecision(6);
    cout << res << "\n";
}

