template<ll Modulus>
class ModInt {
  ll value;
public:
  inline ModInt(ll val = 0) noexcept :
    value((val >= Modulus) ? (val % Modulus) : (val < 0) ? ((val + Modulus) % Modulus) : val) {}

  template<class Int>
  explicit inline operator Int() const noexcept { return static_cast<Int>(value); }

  inline ModInt inv() const noexcept {
    return ModInt<Modulus>::pow(value, Modulus-2);
  }

  inline ModInt& operator+=(ModInt x) noexcept {
    if ((value += x.value) >= Modulus) value -= Modulus;
    return *this;
  }
  inline ModInt& operator-=(ModInt x) noexcept {
    if ((value -= x.value) < 0) value += Modulus;
    return *this;
  }
  inline ModInt& operator*=(ModInt x) noexcept {
    value = (value * x.value) % Modulus; return *this;
  }
  inline ModInt& operator/=(ModInt x) noexcept {
    value = (value * x.inv().value) % Modulus; return *this;
  }

  inline ModInt operator+(ModInt x) const noexcept { return ModInt(*this) += x; }
  inline ModInt operator-(ModInt x) const noexcept { return ModInt(*this) -= x; }
  inline ModInt operator*(ModInt x) const noexcept { return ModInt(*this) *= x; }
  inline ModInt operator/(ModInt x) const noexcept { return ModInt(*this) /= x; }
  inline bool operator==(ModInt x) const noexcept { return value == x.value; }
  inline bool operator!=(ModInt x) const noexcept { return !(this->operator==(x)); }

  friend ostream& operator<<(ostream &os, ModInt x) noexcept { os << x.value; return os; }
  friend istream& operator>>(istream &is, ModInt &x) noexcept { is >> x.value; return is; }

  static constexpr inline ModInt pow(ll n, ll p) noexcept {
    ll ret = 1;
    for(; p > 0; p >>= 1) {
      if (p & 1) ret = (ret * n) % Modulus;
      n = (n * n) % Modulus;
    }
    return ret;
  }

  ModInt p(ll p){
	ll n = value;
    ll ret = 1;
    for(; p > 0; p >>= 1) {
      if (p & 1) ret = (ret * n) % Modulus;
      n = (n * n) % Modulus;
    }
    return value = ret;
  }
};

