//Extended Euclidean Algorithm
ll extended_euclidean(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll d = extended_euclidean(b, a % b, x1, y1);
    x = y1;
    y = x1 - y1 * (a / b);
    return d;
}

void loadModFact(ll n) {
    modfact[0] = 1;//0!
    for(ll i=1; i<=n; i++) {
        modfact[i] = (modfact[i-1]*i) % mod;
    }
}

// Mod arithmetic mod
ll inverse(ll n, ll m) {
    ll x, y;
    ll g = extended_euclidean(n, m, x, y);
    if (g != 1) {
        //No solution should never occur if m is prime
        return 0l;
    }
    x = (x % m + m) % m;
    return x;
}

ll n_choose_k(ll n, ll k) {
    ll res = modfact[n];
    ll div = inverse(modfact[k], mod)*inverse(modfact[n-k], mod) % mod;
    res*=div;
    return res % mod;
}

//all positive in our case
ll powermod(ll n, ll e) {
    if(e==0) {
        return 1l;
    }
    if(e==1) {
        return n;
    }
    ll res = (powermod(n, e/2)*powermod(n, e/2))%mod;
    if(e%2==1)
        res*=n;
    res = res % mod;
    return res;
}

