    string s;
    cin >> k >> s;
    int n = k+s.size();
    //26^(n)-(number of strings which don't have s as subsequence)
    ll all = powermod(26, n);
    //consider strings with 0,1,s.size-1 subsequence of s
    loadModFact(n);
    for(int i=0; i<s.size(); i++) {
        ll rem = (n_choose_k(n,i)%mod)*powermod(25, n-i);
        rem = rem % mod;
        all-=rem;
    }
    while(all<0) {
        all+=mod;
    }
    cout << all << "\n";
    return 0;
}

