void solve() {
    int K; string S; cin >> K >> S;

    COMinit();

    mint ans = 0;

    int len = S.size() + K;

    for (int i = S.size(); i <= len; i++) {
        ans += (mint)COM(i-1, S.size()-1) * modpow((mint)25, i-S.size()) * modpow((mint)26, len-i);
    }

    cout << ans << '\n';
}

