struct mint {
    ll n;
    mint(ll a = 0) {n = a % mod;}
    mint& operator+=(mint a) {n += a.n; n %= mod; return *this;}
    mint& operator-=(mint a) {n += mod; n -= a.n; n %= mod; return *this;}
    mint& operator*=(mint a) {n *= a.n; n %= mod; return *this;}
    mint& operator%=(mint a) {n %= a.n; return *this;}
    mint& operator++() {n++;n %= mod; return *this;}
    mint& operator--() {n += mod; n--; n %= mod; return *this;}
};
mint operator+(mint a, mint b) {a += b; return a;}
mint operator-(mint a, mint b) {a -= b; return a;}
mint operator*(mint a, mint b) {a *= b; return a;}

mint factMod(ll n) {
    if (n == 0)
    {
        return 1;
    }
    mint ans = 1;
    while (n > 1) {
        ans *= n;
        n--;
    }
    return ans;
}

mint powMod(mint x, ll y) {
    if (x.n <= 1)
    {
        return x;
    }
    if (y == 0)
    {
        return 1;
    }
    else if (y == 1)
    {
        return x;
    }
    else if (y % 2 == 0)
    {
        mint tmp = powMod(x, y / 2);
        return tmp * tmp;
    }
    else
    {
        mint tmp = powMod(x, y / 2);
        return tmp * tmp * x;
    }
}

// modは素数
mint modinv(mint n)
{
    return powMod(n, mod - 2);
}

// modは素数でなくてもいい
long long modinv(long long a, long long m = mod) {
    long long b = m, u = 1, v = 0;
    while(b){
        long long t = a / b;
        a -= t * b; swap(a,b);
        u -= t * v; swap(u,v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

