class mint {
  int32_t value;
  static vector<int32_t> *_fact;

public:
  static const int32_t MOD = 1e9 + 7;
  mint(int64_t x)
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  mint operator+(mint y) const {
    return mint(value + y.value);
  }
  mint &operator+=(mint a) {
    return *this = *this + a;
  }
  mint operator*(mint y) const {
    return mint(long(value) * y.value);
  }
  mint &operator*=(mint a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(mint y) const {
    return *this + (-y);
  }
  mint &operator-=(mint a) {
    return *this = *this - a;
  }
  operator int() const {
    return value;
  }
  static mint pow(mint a, long n) {
    if (n <= 0) {
      return 1;
    }
    mint half = pow(a, n / 2);
    return (n & 1) ? half * half * a : half * half;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static void init(long n) {
    _fact = new vector<int32_t>(n + 1);
    (*_fact)[0] = 1;
    mint val = 1;
    for (long i = 1; i <= n; i++) {
      val *= i;
      (*_fact)[i] = val;
    }
  }
  static mint fact(long n) {
    return (*_fact)[n];
  }
  static mint comb(long n, long k) {
    return fact(n) * fact(k).inv() * fact(n - k).inv();
  }
};
vector<int32_t> *mint::_fact;

int main() {
  int K;
  cin >> K;

  string S;
  cin >> S;

  int W = S.size();
  int L = W + K;

  mint::init(L);
  mint ans = 0;
  for (int i = W - 1; i < L; i++) {
    ans += mint::pow(25, i - (W - 1)) * mint::pow(26, L - 1 - i) * mint::comb(i, W - 1);
  }
  cout << (1 + ans) << endl;
}

