	for(int i = 1; i <= m; ++i)
		fac[i] = mul(fac[i - 1], i);
	for(int i = 0; i <= m; ++i)
		inv[i] = qpow(fac[i], mod - 2);

	for(int i = 0; i <= n - 1; ++i) {
		mis = (mis + mul(C(m, i), qpow(25, m - i))) % mod;
	}

	tot = ((tot - mis) % mod + mod) % mod;

	printf("%d", tot);

	return 0;
}

