const ll mod = 1e9 + 7;

const ll N = 2e6 + 10;
ll fact[N];

void prefact() {
    fact[0] = 1;
    for(ll i = 1; i < N; i++) {
        fact[i] = (i * fact[i - 1]) % mod;
    }
}

ll powmod(ll a, ll p) {
    ll res = 1;
    while(p) {
        if(p & 1) {res = (res * a) % mod;}
        p /= 2;
        a = (a * a) % mod;
    }
    return res;
}

ll modinv(ll a) {
    return powmod(a, mod - 2);
}

ll ncr(ll n, ll r) {
    return (fact[n] * (modinv((fact[r] * fact[n - r]) % mod) % mod)) % mod;
}

void solve() {
    prefact();
    ll k;
    string s;
    cin >> k;
    cin >> s;
    ll ans = 0, n = s.size();
    for(ll i = 0; i <= k; i++) {
        ans = (ans + (ncr(n + i - 1, n - 1) * ((powmod(25, i) * powmod(26, k - i)) % mod) % mod)) % mod;
    }
    cout << ans;
}

