int fact[N], infact[N];

int qmi(int a, int b)
{
	int res = 1;
	while(b)
	{
		if(b & 1)	res = (ll)res * a % mod;
		a = (ll)a * a % mod;
		b >>= 1;
	}
	return res;
}

void init()
{
	fact[0] = 1, infact[0] = 1;
    for(int i = 1; i < N; ++i)
    {
        fact[i] = (ll)fact[i - 1] * i % mod;
        infact[i] = (ll)infact[i - 1] * qmi(i, mod - 2) % mod;
    }
}

ll C(int a, int b)
{
	return (ll)fact[a] * infact[b] % mod * infact[a - b] % mod;
}

int main()
{
	int k;
	string s;
	cin >> k >> s;

	int len = s.length();
	int n = k + len;
	init();						// 预处理阶乘 

	int ans = 0;
	for(int i = len; i <= n; i++)
	{
		ll t = C(i - 1, len - 1) * (ll)qmi(25, i - len) % mod * (ll)qmi(26, n - i) % mod;
		ans = (ans % mod + t % mod) % mod;
	}
	cout << ans << endl;
	return 0;
}

