    int now = 1;
    now = modpow(25, i, MOD);
    now %= MOD;
    now *= COM(i+N-1, N-1);
    now %= MOD;
    now *= modpow(26, K-i, MOD);
    now %= MOD;
    ans += now;
    ans %= MOD;
  }
  cout << ans << endl;

}

