const ll mod = 1e9 + 7;

long long modPow(long long a, long long r) {
	if (r == 0) return 1;
	if (r % 2 == 0) {
		int t = modPow(a, r / 2);
		return t * t % mod;
	}
	return a * modPow(a, r - 1);
}

vector<ll> pow26;
vector<ll> pow25;

struct combination {
	const int MAX = 2e6 + 100;
	const int MOD;
	vector<long long> fac, finv, inv;

	combination(int mod) :MOD(mod) {
		fac.resize(MAX);
		finv.resize(MAX);
		inv.resize(MAX);
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (int i = 2; i < MAX; i++) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

	long long COM(int n, int k) {
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}
};

