class mint {
  uint64_t value;
  static vector<uint64_t> fact;
  static void fill(long n) {
    mint val = fact.back();
    for (int i = fact.size(); i <= n; ++i) {
      fact.push_back(uint64_t(val *= i));
    }
  }

public:
  static const int32_t MOD = 1e9 + 7;
  constexpr mint(const int64_t x = 0) noexcept
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  constexpr explicit operator uint64_t() const noexcept {
    return value;
  }
  constexpr mint operator+() const noexcept {
    return mint(*this);
  }
  constexpr mint operator-() const noexcept {
    return mint(MOD - value);
  }
  constexpr mint operator+(const mint &rhs) const noexcept {
    return mint(*this) += rhs;
  }
  constexpr mint operator-(const mint &rhs) const noexcept {
    return mint(*this) -= rhs;
  }
  constexpr mint operator*(const mint &rhs) const noexcept {
    return mint(*this) *= rhs;
  }
  constexpr mint &operator+=(const mint &rhs) noexcept {
    if ((value += rhs.value) >= MOD) value -= MOD;
    return *this;
  }
  constexpr mint &operator-=(const mint &rhs) noexcept {
    return *this += MOD - rhs.value;
  }
  constexpr mint &operator*=(const mint &rhs) noexcept {
    if ((value *= rhs.value) >= MOD) value %= MOD;
    return *this;
  }
  static mint pow(mint a, long n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static mint factfunc(long n) {
    fill(n);
    return fact[n];
  }
  static mint finvfunc(long n) {
    return factfunc(n).inv();
  }
};
