	int n = s.size();

	Polynomial p(2);
	p.set(0, 25); p.set(1, 1);
	p ^= n + k;
	i64 ans = 0;
	FOR(i, n, n + k + 1) (ans += p[i]) %= MOD;
	OUT(ans)BR;

	return 0;
}

