// Returns nCr % p using Fermat's little 
// theorem. 
unsigned long long nCrModPFermat(unsigned long long n, 
								int r, int p) 
{ 
	// Base case 
	if (r == 0) 
		return 1; 

	// Fill factorial array so that we 
	// can find all factorial of r, n 
