template<size_t MAXV, class T = mint>
struct Comb {
    array<T, MAXV + 1> fact, fact_inv;

    constexpr Comb() noexcept {
        fact[0] = 1;
        for (size_t i = 1; i <= MAXV; i++) {
            fact[i] = fact[i - 1] * i;
        }

        fact_inv[MAXV] = fact[MAXV].inv();
        for (size_t i = MAXV; i > 0; i--) {
