  lint N = S.size();

  mint sum = 0;
  for(lint i=N; i<=N+K; i++) {
    sum += cnt.comb(i-1, N-1) * mint::pow(25, i-N) * mint::pow(26, N+K-i);
  }

  cout << sum << endl;
}

