const int MAX = 510000;
const ll MOD = 1000000007;

ll fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll powmod(ll a, ll p){
  ll res = 1;
  while(p > 0){
    if(p & 1){
      res *= a;
      res %= MOD;
    }
    a *= a;
    a %= MOD;
    p >>= 1;
  }
  return res;
}

int main(){
  COMinit();
  ll k; cin >> k;
  string s; cin >> s;
  ll n = s.size() + k;
  ll ans = 0;
  for(ll i = s.size(); i <= n; i++){
    ans += powmod(25, i - (int)s.size())*powmod(26, n - i) % MOD * COM(i-1,(ll)s.size() - 1) % MOD;
  }
  ans %= MOD;
  cout << ans << endl;
}

