ll modpow(ll a, ll b)
{
    if (b == 0)
    {
        return 1;
    }
    if (b % 2 == 0)
    {
        ll r = modpow(a, b/2);
        return r * r % modulo;
    }
    else
    {
        return modpow(a, b-1) * a % modulo;
    }
}

ll modinv(ll n)
{
    return modpow(n, modulo-2);
}

ll modfact(ll n)
{
    dpfact[0] = 1;
    if (dpfact.at(n) == 0)
    {
        ll r = modfact(n-1);
        dpfact[n] = n * r % modulo;
    }
    return dpfact.at(n);
}

// n C (len-1)
ll modcomb(ll n)
{
    return (modfact(n) * modinv(modfact(len - 1)) % modulo) * modinv(modfact(n - len + 1)) % modulo;
}

