ll POW(ll b, ll e) {
  if(e==0) { return 1LL; }
  else if(e%2==0) {
    return POW(MUL(b,b),e/2);
  } else {
    return MUL(b, POW(b,e-1));
  }
}
ll INV(ll x) { return POW(x,MOD-2); }

// How many strings of length i have a specific string of length j as a subsequence?
ll dp(ll i, ll j) {
  assert(i>=0 && j>=0 && j<=i);
  if(i==j) { return 1LL; }
  if(j==0) {
    // 26**i
    return MUL(26,dp(i-1,j));
  } else {
    return ADD(MUL(25,dp(i-1,j)),dp(i-1,j-1));
  }
}

