using namespace std;

class comb
{
	ll inf;
	vector <ll> fact, inv;

public:
	comb(ll n, ll infi)
	{
		fact.resize(n + 1);
		inv.resize(n + 1);
		inf = infi;
		fact[0] = 1;
		for(ll i = 1; i <= n; i++)
			fact[i] = (fact[i - 1]  * i) % inf;
		for(ll i = 0; i <= n; i++)
			inv[i] = exp(fact[i], inf - 2);
	}

	ll ncr(ll n, ll r)
	{
		ll ans = fact[n];
		ans = (ans * inv[r]) % inf;
		ans = (ans * inv[n - r]) % inf;
		return ans;
	}

	ll f(ll n)
	{
		return fact[n];
	}

	ll iv(ll n)
	{
		return inv[n];
	}

	ll exp(ll a, ll b)
	{
		ll res = 1;
		while(b > 0)
		{
			if(b & 1)
				res = (res * a) % inf;
			a = (a * a) % inf;
			b >>= 1;
		}
		return res;
	}
};

void solve()
{
	ll k;
	cin >> k;
	string s;
	cin >> s;
	ll m = s.size(), inf = 1e9 + 7, ans = 0;
	comb c(m + k, inf);
	for(ll i = 0; i <= k; i++)
	{
		ll tans = c.exp(26, i);
		tans = (tans * c.exp(25, k - i)) % inf;
		tans = (tans * c.ncr(m + k - i - 1, m - 1)) % inf;
		ans = (ans + tans) % inf;
	}
	cout << ans << endl;
}

int main()
{
