using mint = ModInt<long long>;

class Comb {
public:
    Comb() : fac(0), finv(0) {}
    Comb(int n) : fac(n + 1), finv(n + 1) {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i)
            fac[i] = fac[i - 1] * i;
        finv[n] = fac[n].inv();
        for (int i = n; i >= 1; --i)
            finv[i - 1] = finv[i] * i;
    }
    void resize(int size) { *this = {size}; }
    mint C(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k]);
    }
    mint P(int n, int k) {
        if (k < 0) return 0;
        return C(n, k) * fac[k];
    }
    // n!
    mint Fac(int n) {
        if (n < 0) return 0;
        return fac[n];
    }
    mint FInv(int n) {
        if (n < 0) return 0;
        return finv[n];
    }

    mint S(int n, int k) {
        mint res = 0;
        for (int i = 0; i <= k; ++i) {
            if ((k - i) % 2 == 0)
                res += C(k, i) * mint(i).pow(n);
            else
                res -= C(k, i) * mint(i).pow(n);
        }
        return res;
    }

private:
    std::vector<mint> fac;
    std::vector<mint> finv;
};

void solve() {
    int k;
    string s;
    cin >> k >> s;

    int n = sz(s);
    Comb com(n + k + 1);
    mint ans = 0;
    loop(i, n - 1, n + k) {
        ans += com.C(i, n - 1) * mint(25).pow(i - (n - 1)) * mint(26).pow(n + k - (i + 1));
    }
    cout << ans << endl;
}

