void precompute(ll mod)
{
    fact[0]=1;
    ifact[0]=1;
    for(int i=1;i<maxn;i++)
    {
        fact[i]=fact[i-1]*i;
        fact[i] = fact[i]%mod;
        ifact[i] = mpowe(fact[i],mod-2,mod);
