ll ncr(ll n,ll r,ll mod)
{
    if(r>n)
        return 0;
    ll ans = fact[n]*ifact[n-r];
    ans = ans%mod;
    ans = ans*ifact[r];
    ans = ans%mod;
    return ans;
}

