template <unsigned P>
struct ModInt
{
		using M = ModInt;
		unsigned v;
		ModInt() : v(0) {}
		ModInt(auto x) : v(x >= 0 ? x % P : (P - -x % P) % P) {}
		constexpr ModInt(unsigned v, int) : v(v) {}
		static constexpr unsigned p() { return P; }
		M operator+() const { return *this; }
		M operator-() const { return {v ? P - v : 0, 0}; }
		explicit operator bool() const noexcept { return v; }
		bool operator!() const noexcept { return !(bool)*this; }
		M operator*(M r) const { return M(*this) *= r; }
		M operator/(M r) const { return M(*this) /= r; }
		M operator+(M r) const { return M(*this) += r; }
		M operator-(M r) const { return M(*this) -= r; }
		bool operator==(M r) const { return v == r.v; }
		bool operator!=(M r) const { return !(*this == r); }
		M &operator*=(M r)
		{
				v = (uint64_t)v * r.v % P;
				return *this;
		}
		M &operator/=(M r) { return *this *= r.inv(); }
		M &operator+=(M r)
		{
				if ((v += r.v) >= P)
						v -= P;
				return *this;
		}
		M &operator-=(M r)
		{
				if ((v += P - r.v) >= P)
						v -= P;
				return *this;
		}
		M inv() const
		{
				int a = v, b = P, x = 1, u = 0;
				while (b)
				{
						int q = a / b;
						swap(a -= q * b, b);
						swap(x -= q * u, u);
				}
				assert(a == 1);
				return x;
		}
		M pow(auto n) const
		{
				if (n < 0)
						return pow(-n).inv();
				M res = 1;
				for (M a = *this; n; a *= a, n >>= 1)
						if (n & 1)
								res *= a;
				return res;
		}
		friend M operator*(auto l, M r) { return M(l) *= r; }
		friend M operator/(auto l, M r) { return M(l) /= r; }
		friend M operator+(auto l, M r) { return M(l) += r; }
		friend M operator-(auto l, M r) { return M(l) -= r; }
		friend ostream &operator<<(ostream &os, M r) { return os << r.v; }
		friend istream &operator>>(istream &is, M &r)
		{
				ll x;
				is >> x;
				r = x;
				return is;
		}
		friend bool operator==(auto l, M r) { return M(l) == r; }
		friend bool operator!=(auto l, M r) { return !(l == r); }
};

ModInt<MOD> modpow(ll i, ll n){
	vector<ModInt<MOD>> tmparr;
	vector<bool> b;
	ModInt<MOD> tmp = i;
	ll ntmp = n;
	while(ntmp!=0){
		if (ntmp%2 == 1){b.push_back(true);}else{b.push_back(false);}
		ntmp/=2;
		tmparr.push_back(tmp);
		tmp*=tmp;
	}
	ModInt<MOD> ans = 1;
	rep(i,b.size()) if(b[i]) ans *= tmparr[i];
	return ans;
}

