typedef long long ll;


const int MOD = 1000000007;
int MAX_SZ;
int K, N;
string S;
vector<ll> fac, finv, inv;
vector<ll> pow25, pow26;

void COMB_init() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i <= MAX_SZ; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

ll COMB(int n, int k){
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

void input_init(void) {
	cin >> K;
	cin >> S;
	N = S.length();
	MAX_SZ = K + N - 1;
	fac.resize(MAX_SZ + 1);
	finv.resize(MAX_SZ + 1);
	inv.resize(MAX_SZ + 1);
	pow25.resize(K + 1);
	pow26.resize(K + 1);
	pow25[0] = pow26[0] = (ll)1;
	for (int i = 1; i <= K; ++i) {
		pow25[i] = (pow25[i - 1] * 25) % MOD;
		pow26[i] = (pow26[i - 1] * 26) % MOD;
	}
}

ll solve(void) {
	ll sum = (ll)0;
	for (int i = 0; i <= K; ++i) {
		ll val = (pow25[i] * COMB(i + N - 1, N - 1)) % MOD;
		val = (val * pow26[K - i]) % MOD;
		sum = (sum + val) % MOD;
	}
	return sum;
}

int main(void) {
	input_init();
	COMB_init();
	ll ans = solve();
	cout << ans << '\n';
	return 0;
}

