        if( s[i] >= 'a' && s[i] <= 'z' ) n++;
    }

    int t = n + k;

    ModFactorial f(t + 1);

    ModInt ans = ModInt::modpow(26, t);
    for( int i = 0; i < n; i++ )
    {
        ModInt tmp = f.getCombination(t, i);
        tmp *= ModInt::modpow(25, t - i);
        ans -= tmp;
    }

    cout << ans.getint();

    return 0;    
}

