      (a *= a) %= mod;
      b >>= 1;
  }
  return res;
}

bool Math::isPrime(ll n) {
  bool flg = true;
  for(ll i=2; i*i<=n; i++){
      if(n%i == 0) {
          flg = false;
          break;
      }
  }
  return flg;
}

vector<ll> Math::changeBase(ll n, int b){
  vector<ll> v;
  while(n > 0){
    ll r = n%b;
    if(r == 0) --n;
    n /= n;
    v.push_back((r-1+b)%b);
  }
  return v;
}

