void preprocess(){
    powers_of_25[0]=1;
    powers_of_26[0]=1;
    for(int i=1;i<=1000000;i++)
    {
        powers_of_25[i]=powers_of_25[i-1]*25ll;
        powers_of_25[i]%=hell;
        powers_of_26[i]=powers_of_26[i-1]*26ll;
        powers_of_26[i]%=hell;
    }
}

inline int fast_expo(int base,int power,int modulo=hell){
    base%=modulo;
    if (base<0) base+=modulo;
    ll x=base,cnt=power,ans=1;
    while(cnt){
        if (cnt&1) ans=(ans*x)%modulo;
        x=(x*x)%modulo;
        cnt>>=1;
    }
    return ans;
}
inline int inv(int base,int modulo=hell){
    return fast_expo(base,modulo-2,modulo);
}

