const int nax = 1e6 + 44, mod = 1e9 + 7;
ll fac[nax * 2], fin[nax * 2];

ll power(ll a, ll b){
	ll result = 1;
	while(b>0){
		if(b%2) result = (result*a)%mod;
		(a*=a)%=mod;
		b/=2;
	}
	return result;
}

ll inv(ll x) {
	ll e = mod - 2, r = 1;
	while (e) {
		if (e & 1) r = r * x % mod;
		x = x * x % mod;
		e >>= 1;
	}
	return r;
}
ll cho(int a, int b) {
	if (b < 0 || b > a) return 0;
	return fac[a] * fin[b] % mod * fin[a - b] % mod;
}

void solve(){
	int k; string s; cin >> k >> s;
	int n = s.size();
	fac[0] = 1;
	for (int i = 1; i < nax * 2; ++i) fac[i] = fac[i - 1] * i % mod;
	fin[nax * 2 - 1] = inv(fac[nax * 2 - 1]);
	for (int i = nax * 2 - 2; i >= 0; --i) fin[i] = fin[i + 1] * (i + 1) % mod;
	ll ans = 0;
	forn(i,0,k+1) {
		(ans += cho(n + i - 1, i) * power(26, k - i) % mod * power(25, i)) %= mod;
	}
	cout << ans;
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	solve();
	return 0;
}

