void calc()
{
  fact[0] = 1;
  inv[0] = modInverse(fact[0]);
  for (int i = 1; i < N; i++) {
    fact[i] = modMul(fact[i - 1], i);
    inv[i] = modInverse(fact[i]);
  }

  P[0] = 1;// power of 25
  for (int i = 1; i < N; i++) {
    P[i] = modMul(P[i - 1], 25);
    //dbg(P[i]);
  }
}

ll nCr(int n, int r)
{
  if (n < r)return 0;
  return modMul(fact[n], modMul(inv[n - r], inv[r]));
}


