using namespace std;
const int MAX=2000005;
const long long MOD=1000000007;

typedef long long ll;

ll fac[MAX],finv[MAX],inv[MAX];

ll mod_pow(ll x, ll n){ //べき乗
    ll ans=1;
    x%=MOD;
    while(n!=0){
        if(n&1) ans=ans*x%MOD;
        x=x*x%MOD;
        n=n>>1;
    }
    return ans%MOD;
}

void com_init(){ //初期化
    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;
    for(int i=2;i<MAX;i++){
        fac[i]=fac[i-1]*i%MOD;
        //inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
        //finv[i]=finv[i-1]*inv[i]%MOD;
        finv[i]=finv[i-1]*mod_pow(i,MOD-2)%MOD;//フェルマーの小定理より
    }
}

ll comb(ll n, ll k){ //nCk
    if(n<k) return 0;
    if(n<0||k<0) return 0;
    return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
}

int main(){
    int k; cin >> k;
    string s; cin >> s;
    com_init();
    int N=s.size();
    ll ans=0;
    for(int i=1;i<=(k+N);i++){
        if(N<=i){
            ans+=((comb(i-1,N-1)*mod_pow(25,i-N))%MOD*mod_pow(26,k+N-i))%MOD;
        }
        ans%=MOD;
    }
    cout << ans << endl;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn = 1<<20, mod = 1e9 + 7;
int fact[maxn], inv[maxn];
void pre() {
	for(int i = 0; i < maxn; i++)
		if(i < 2) fact[i] = inv[i] = 1;
		else fact[i] = i, inv[i] = mod - (mod/i)*1ll*inv[mod%i]%mod;
	for(int i = 1; i < maxn; i++)
		fact[i] = fact[i]*1ll*fact[i-1]%mod,
		inv[i] = inv[i]*1ll*inv[i-1]%mod;
}
int bp(int a, int p) {
	int r = 1;
	while(p) {
		if(p&1) r = r*1ll*a%mod;
		a = a*1ll*a%mod, p>>=1;
	}
	return r;
}
int nck(int i, int j) {
	if(i < j || j < 0) return 0;
	int t = fact[i]*1ll*inv[j]%mod;
	return t*1ll*inv[i-j]%mod;
}
int get(int i, int j) {
	int t = bp(25, i-j);
	return t*1ll*nck(i, j)%mod;
}
int main() {
	cin.tie(0)->sync_with_stdio(0);
	pre();
	int ans = 0, n, k;
	string s;
	cin >> k >> s;
	n = s.size();
	for(int i = n; i <= n+k; i++) ans = (ans + get(n+k, i))%mod;
	cout << ans;
	return 0;
}
