        ansi *= modpow((ll)25, (ll)k - i, inf);
        ansi %= inf;
        ansi *= modpow((ll)26, (ll)i, inf);
        ansi %= inf;
        ans += ansi;
        ans %= inf;
    }
    cout << ans << endl;
}

