ll fac[N];

ll binpow(ll a,ll b)
{
    ll res=1; a%=mcc;
	if (a==1 || b==0) return 1;
	else if (a==0) return 0;
    while(b)
    {
        if (b&1) res=(res*a)%mcc;
        b>>=1;
        a=(a*a)%mcc;
    }
    return res%mcc;
}

void pre()
{
    fac[0]=fac[1]=1;
    for (int i=2;i<N;i++)
    {
        fac[i]=((fac[i-1]%mcc)*i)%mcc;
    }
}
ll inv(ll n)
{
    return binpow(n,mcc-2);
}

ll ncr(ll n, ll r)
{
    return (((fac[n]*inv(fac[r]))%mcc)*(inv(fac[n-r])%mcc))%mcc;
}


void solve()
{
