#include <bits/stdc++.h>
using namespace std;

class mint {
  int32_t value;

public:
  static const int32_t MOD = 1e9 + 7;
  mint(int64_t x)
      : value(x % MOD + (x < 0 ? MOD : 0)) {}
  mint operator+(mint y) const {
    return mint(value + y.value);
  }
  mint &operator+=(mint a) {
    return *this = *this + a;
  }
  mint operator*(mint y) const {
    return mint(long(value) * y.value);
  }
  mint &operator*=(mint a) {
    return *this = *this * a;
  }
  mint operator-() const {
    return *this * mint(-1);
  }
  mint operator-(mint y) const {
    return *this + (-y);
  }
  mint &operator-=(mint a) {
    return *this = *this - a;
  }
  operator int() const {
    return value;
  }
  static mint pow(mint a, long n) {
    if (n <= 0) {
      return 1;
    }
    mint half = pow(a, n / 2);
    return (n & 1) ? half * half * a : half * half;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static mint comb(long n, long k) {
    mint bunbo = 1, bunshi = 1;
    for (long i = 0; i < k; i++) {
      bunbo *= (k - i);
      bunshi *= (n - i);
    }
    return bunshi * bunbo.inv();
  }
};

int main() {
  int K;
