  int W = S.size();
  int L = W + K;

  mint ans = 0;
  for (int i = W - 1; i < L; i++) {
    ans += mint::pow(25, i - (W - 1)) * mint::pow(26, L - 1 - i) * mint::comb(i, W - 1);
  }
  cout << (1 + ans) << endl;
}

