int k;

ll qp(ll a, ll b) {
    ll res = 1;
    while(b) {
        if(b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void init() {
    fac[0] = fac[1] = 1;
    for(int i = 2; i < N; i++) fac[i] = fac[i - 1] * i % mod;
    inv[N - 1] = qp(fac[N - 1], mod - 2);
    for(int i = N - 2; i >= 0; i--) inv[i] = inv[i + 1] * (i + 1) % mod;
}

ll C(ll a, ll b) {
    if(b > a) return 0ll;
    return fac[a] * inv[b] % mod * inv[a - b] % mod;
}

ll add(ll a, ll b) {
    return (a + b) % mod;
}

int main()
{
    init();
    scanf("%d", &k);
    scanf("%s", s);

