    for(int i = len; i <= k + len; i++) //枚举前i个字符为S的所在地，即第i个位置是字符s[len-1]的所在地
        res = add(res, C(i - 1, len - 1) * qp(25ll, i - len) % mod * qp(26ll, k + len - i) % mod);
    printf("%lld\n", res);

    return 0;
}

