    for(int i = 0; i <= k; ++i)
    {
        rtn = rtn % MOD + (Modpow(26, k - i, MOD) * ((Modpow(25, i, MOD) * ModComb(n + i - 1, n - 1, MOD)) % MOD)) % MOD;
    }

    std::cout << rtn << std::endl;
}

