    add = (add * inv_fanc[i-(n-1)])%MOD;
    add = (add * inv_fanc[(n-1)])%MOD;
    add = (add * modpow(26, k+n-(i+1), MOD))%MOD;
    ans = (ans + add) %MOD;
  }
