using namespace std;

typedef unsigned long long ull;
const ull modConst = 1E9 + 7;

ull facMemo[2000005];
ull fastExp(ull A, ull B)
{
	if(B == 0)
		return 1 % modConst;

	ull Sqrt = fastExp(A, B / 2), ans = (Sqrt * Sqrt) % modConst;
	if(B % 2 == 1)
		ans *= A % modConst;

	return ans % modConst;
}

ull modInverse(ull X)
{
	return fastExp(X, modConst - 2);
}

ull choose(int N, int R)
{
	ull ans = (facMemo[N] * modInverse(facMemo[N - R])) % modConst;
	ans = (ans * modInverse(facMemo[R])) % modConst;

	return ans;
}

ull starsAndBars(ull stars, ull bars)
{
	return choose(stars + bars, stars);
}

int main()
{
	ull K;
	scanf("%llu", &K);

	string S;
	cin >> S;

	facMemo[0] = 1 % modConst;
	for(ull i = 1; i < 200005; i++)
		facMemo[i] = (facMemo[i - 1] * i) % modConst;

	ull ans = 0;
	for(ull i = 0; i <= K; i++)
	{
		ull stars = K - i, bars = (ull)(S.length()) - 1;
		ull temp = ((starsAndBars(stars, bars) * fastExp(25, stars)) % modConst)  * fastExp(26, i);

		ans += temp % modConst;
		ans %= modConst;
	} 

	printf("%llu", ans);
}

