using namespace std;
template<typename T>
T fastPow(T a, T b, T mod = 0) {
	if (a == 0 and b == 0) {
		return -1;
	}
	if (a == 0) {
		return 0;
	}
	if (b == 0) {
		return 1;
	}
	long long tmp = fastPow(a, b / 2, mod);
	if (mod != 0) {
		if (b % 2 == 0) {
			return (tmp * tmp) % mod;
		}
		else {
			return ((tmp*tmp) % mod * (a % mod)) % mod;
		}
	}
	else {
		if (b % 2 == 0) {
			return (tmp*tmp);
		}
		else {
			return tmp * tmp * a;
		}
	}
}
template <typename T>
T extGCD(T a, T b, T &x, T &y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	T d = extGCD(b, a%b, y, x); // 再帰的に解く
	y -= a / b * x;
	return d;
}

// 負の数にも対応した mod 
template <typename T>
T mod(T a, T m) {
	return (a % m + m) % m;
}

// 逆元計算 
template <typename T>
T modinv(T a, T m) {
	T x, y;
	extGCD(a, m, x, y);
	return mod(x, m);
}

ll calc(ll i) {
	ll rev = 26 * (i+1) - i;
	return rev;
}
typedef unsigned long long ull;
template <typename T1, typename T2, typename T3>
ull nCr(T1 n, T2 r, T3 mod = 0) {
	ull ans = 1;
	if (mod == 0) {
		for (T2 i = 1; i <= r; ++i) {
			ans = ans * (n - i + 1) / i;
		}
	}
	else {
		for (T2 i = 1; i <= r; i++) {
			ans = ans * (n - i + 1) * modinv(i, mod) % mod;
			// modinv(i, mod)を定義しておくこと
		}
	}
	return ans;
}


int main() {
	ll k;
	string s;
	cin >> k >> s;
	ll n = s.length();
	vector<ll> combinations(k + n, 0);

	for (ll x = 0; x <= k; x++) {
		if (x == 0) {
			combinations[k - x + n - 1] = nCr(k - x + n - 1, n - 1, mop);
		}
		else {
			combinations[k - x + n - 1] = combinations[k - x + n] * modinv(k - x + n, mop);
			combinations[k - x + n - 1] = mod(combinations[k - x + n - 1], mop);
			combinations[k - x + n - 1] *= (k - x + n) - (n - 1);
			combinations[k - x + n - 1] = mod(combinations[k - x + n - 1], mop);
		}
	}
	ll ans = 0;
	for (ll x = 0; x <= k; x++) {
		ll tmp = mod(fastPow(25LL, k - x, mop) * fastPow(26LL, x, mop), mop);
		tmp *= combinations[k - x + n - 1];
		tmp = mod(tmp, mop);
		ans += tmp;
		ans = mod(ans, mop);
	}
	cout << ans << endl;

}

