int cnk(int n, int k) {
    int chisl = fact[n];
    int zn = fact[k] * fact[n - k];
    zn %= mod;
    int x, y;
    gcd(zn, mod, x, y);
    x %= mod;
    x += mod;
    x %= mod;
    return (chisl * x) % mod;
}

