    for (int i = 0; i <= n; i++) {
        ll a = (p25[i] * p26[n-i]) % M;
        a *= C(k-1+i, k-1);
        a %= M;
        s += a;
        s %= M;
    }

    cout << s << endl;

    return 0;
}

