using namespace std;
typedef long long int ll;
const ll mod = 1e9+7;

const int MAX = 1e7;
ll fac[MAX], finv[MAX], inv[MAX];

//前処理
void COMinit (){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1]*i%mod;
        inv[i] = mod-inv[mod%i]*(mod/i)%mod;
        finv[i] = finv[i-1]*inv[i]%mod;
    }
}
//二項係数
ll COM(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n]*(finv[k]*finv[n-k]%mod)%mod;
}

//繰り返し二乗法
ll EX(ll x,ll n){
    if(n == 0)return 1;
    else if(n%2 == 1)return EX(x,n-1)*x%mod;
    else return EX(x*x%mod,n/2)%mod;
};

int main(){
    int k;
    cin >> k;
    string s;
    cin >> s;
    ll ans = 0;
    int n = s.size();
    COMinit();
    for(int i = 0; i <= k; i++){
        ans += (COM(n-1+k-i,n-1)*EX(25,k-i))%mod*EX(26,i)%mod;
        ans %= mod;
    }
    cout << ans%mod << endl;
    return 0;
}

