//a^b % modを求める
int64_t MODpow(int64_t a, int64_t b, int64_t mod) {
    int64_t result = 1;
    while (b) {
        if (b % 2 == 1) {
            result *= a;
            result %= mod;
        }

        b /= 2;
        a *= a;
        a %= mod;
    }

    return result;
}

class Combination {
public:
    Combination(int64_t max_num, int64_t mod) {
        fact_.resize(max_num + 1, 1);
        inv_fact_.resize(max_num + 1, 1);
        mod_ = mod;
        for (int64_t i = 2; i <= max_num; i++) {
            fact_[i] = i * fact_[i - 1] % mod_;
            inv_fact_[i] = MODpow(fact_[i], mod_ - 2, mod_);
            assert(fact_[i] * inv_fact_[i] % mod_ == 1);
        }
    }
    int64_t operator()(int64_t n, int64_t m) const {
        if (m < 0 || m > n) return 0;
        return fact_[n] * inv_fact_[n - m] % mod_ * inv_fact_[m] % mod_;
    }
private:
    vector<int64_t> fact_, inv_fact_;
    int64_t mod_;
};

int main() {
    int64_t K;
    string S;
    cin >> K >> S;

    constexpr int64_t MOD = 1e9 + 7;

    Combination comb(S.size() + K, MOD);

    int64_t ans = 0;
    for (int64_t i = S.size() - 1; i < K + S.size(); i++) {
        (ans += comb(i, S.size() - 1) * MODpow(25, i - S.size() + 1, MOD) % MOD * MODpow(26, K + S.size() - 1 - i, MOD) % MOD) %= MOD;
    }

    cout << ans << endl;
}

