#include <bits/stdc++.h>
using namespace std;
#define mod ((long long)(1e9 + 7))
vector<long long> fact;
vector<long long> factInv;

long long pow_mod(long long a, long long b) {
  long long ret = 1;
  while (b > 0) {
    if (b & 1) ret = ret * a % mod;
    a = a * a % mod;
    b = b >> 1;
  }
  return ret;
}

void comb_init(long long n) {
  fact.resize(n + 1);
  factInv.resize(n + 1);
  fact[0] = 1;
  for (long long i = 1; i <= n; i++) {
    fact[i] = (fact[i - 1] * i) % mod;
    fact[i] %= mod;
  }
  factInv[n] = pow_mod(fact[n], mod - 2);
  for (long long i = n - 1; i >= 0; i--) {
    factInv[i] = factInv[i + 1] * (i + 1) % mod;
  }
}

long long comb(long long n, long long r) {
  if (n == 0 && r == 0) return 1;
  if (r > n) return 0;
  long long ret = factInv[n - r] * factInv[r] % mod;
  return ret * fact[n] % mod;
}

int main(void) {
  long long K;
  cin >> K;
  string S;
  cin >> S;
  long long N = S.length();
  comb_init(N + K - 1);
  long long ans = 0;
  for (long long i = N - 1; i <= N + K - 1; i++) {
    ans += (((comb(i, N - 1) * pow_mod(25, i - (N - 1))) % mod) *
            pow_mod(26, N + K - 1 - i)) %
           mod;
    ans %= mod;
  }
  cout << ans << endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

using LL = long long;
const LL M = 1e9+7;

LL combination(LL n, LL r) {
  if(n < r) return 0;
  if(n < 0 || r < 0) return 0;
  static std::vector<LL> fact{1, 1}, inv{1, 1}, finv{1, 1};
  for(LL i = fact.size(); i <= n; ++i) {
    fact.emplace_back(fact.back() * i % M);
    inv.emplace_back(inv.at(M % i) * (M - M / i) % M);
    finv.emplace_back(finv.back() * inv.back() % M);
  }
  return (fact[n] * finv[n - r] % M) * finv[r] % M;
}

LL power(LL m, LL n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}

int main() {
  int K; string S;
  cin >> K >> S;
  int N = K + S.size();
  LL ans = 0;
  for(int i=S.size(); i<=N; ++i) (ans += power(25,N-i) * combination(N,i) % M) %= M;
  cout << ans << endl;
}

