#define MOD 1000000007
#define MAX 1000000

/* Factorial modulo MOD */
LL fact[2*MAX];
char s[2*MAX];

void factorial() {
	fact[0] = 1;
	for(int i=1;i<MAX;i++) {
		fact[i] = (i * fact[i-1]) % MOD;
	}
}

/* Modulo exponentiation */
LL power(LL base, LL exp, LL ans) {
	if(!exp) return ans % MOD;
	if(exp&1) ans = (ans * base) % MOD;
	return power((base * base) % MOD, exp>>1, ans);
}

/* nCr modulo MOD */
LL nCr(LL n, LL r) {
	if(n < r) return 0;
	LL numerator = fact[n];
	LL denominator = (fact[n-r] * fact[r]) % MOD;
	return (numerator * power(denominator, MOD-2, 1)) % MOD;
}

int main() {

	int k, n, i;
	LL ans = 0;
	factorial();

	cin>>k;
	cin>>s;

	n = strlen(s);
	for(i = 0 ; i <=k ; i++) {

		LL lp = power(26, i, 1);

		LL rp = (power(25, k-i, 1) * nCr(k-i + n -1, n-1)) % MOD;
		ans = (ans + (lp * rp) % MOD) %MOD;
	}

	cout<<ans<<endl;
	return 0;
}

