struct Factorial {

  int modpow(int a, u64 n) noexcept {
    if (n == 0) return 1;
    auto t = modpow(a, n / 2);
    t = (int)((i64)t * t % mod);
    if (n & 1) t = (int)((i64)t * a % mod);
    return t;
  }

  Factorial(int count, int mod, bool calcInverse = true) : mod(mod) {

    f.reserve(count + 1);
    if (calcInverse) fi.reserve(count + 1);

    f.push_back(1);
    if (calcInverse) fi.push_back(1);
    FOR(i, 1, count + 1) {
      f.push_back((int)(((i64)f[i - 1] * i) % mod));
      if (calcInverse) fi.push_back(modpow(f[i], mod - 2));
      //cout << i << " " << f[i] << " " << fi[i] << newl;
    }
  }

  int Ncr(int n, int r) {
    if (n < r) return 0;
    return (int)((i64)f[n] * fi[r] % mod * fi[n - r] % mod);
  }

  // without inverse array
  int Ncr2(int n, int r) {
    if (n < r) return 0;
    return Div(Div(f[n], f[r]), f[n - r]);
  }

  int Div(int l, int r) noexcept {
    long long a = r, b = mod, u = 1, v = 0;
    while (b) {
      long long t = a / b;
      a -= t * b; swap(a, b);
      u -= t * v; swap(u, v);
    }
    l = l * u % mod;
    if (l < 0) l += mod;
    return l;
  }

  int mod;

  // 階乗
  vector<int> f;

  // 階乗の逆元
  vector<int> fi;
};

