struct mint
{   
    long long x;

    mint(long long xx = 0) : x(xx % mod){}

    mint(const mint&) = default;
    mint& operator=(const mint& rhs) = default;

    mint operator-() const
    {
        return mint(-x);
    }

    mint& operator+=(const mint rhs)
    {
        x += rhs.x;
        if(x >= mod)
        {
            x -= mod;
        }

        return *this;
    }

    mint& operator-=(const mint rhs)
    {
        x += mod - rhs.x;
        if(x >= mod)
        {
            x -= mod;
        }

        return *this;
    }

    mint& operator*=(const mint rhs)
    {
        x *= rhs.x;
        x %= mod;
        return *this;
    }

    mint operator+(const mint rhs) const
    {
        return mint(*this) += rhs;
    }

    mint operator-(const mint rhs) const
    {
        return mint(*this) -= rhs;
    }

    mint operator*(const mint rhs) const
    {
        return mint(*this) *= rhs;
    }

    mint pow(long long t) const
    {
        mint rtn = 1;
        mint tmp = *this;
        while(t > 0)
        {
            if(t & 1)
            {
                rtn *= tmp;
            }
            tmp *= tmp;
            t >>= 1;
        }
        return rtn;
    }

    mint inv() const
    {
        return pow(mod - 2);
    }
    mint& operator/= (const mint rhs)
    {
        return *this *= rhs.inv();
    }
    mint operator/ (const mint rhs) const
    {
        return mint(*this) /= rhs;
    }
};
