ll qp(ll a,ll b){
    ll res=1;
    while(b){
        if(b&1){
            res=res*a%mod;
        }
        a=a*a%mod;
        b>>=1;
    }
    return res%mod;
}

ll prepare(ll n){
    fun[0]=fun[1]=1;
    for(int i=2;i<=n;++i){
        fun[i]=fun[i-1]*i%mod;
    }
    infun[n]=qp(fun[n],mod-2);
    for(int i=n-1;i>=0;--i){
        infun[i]=infun[i+1]*(i+1)%mod;
    }
}

ll C(ll n,ll m){
    if(n<m)return 0;
    return ((fun[n]*infun[n-m]%mod)*infun[m])%mod;
}

