int bp(int x, int n)
{
    if (n == 0)
        return 1;
	if (n == 1)
		return x;
	if (n % 2)
	{
		return (x * bp(x, n - 1)) % mod;
	}
	int y = bp(x, n / 2);
	return y * y % mod;
}

int f[2000000];

int c(int n, int k)
{
	return ((f[n] * bp(f[k], mod - 2)) % mod) * bp(f[n - k], mod - 2) % mod;
}

void solve()
{
	f[0] = 1;
	for (int i = 1; i < 2000000; ++i)
