int toPower(int a, int p){
    int res = 1;
    while (p){
        if (p & 1) res = ll(res) * a % mod;
        p >>= 1; a = ll(a) * a % mod;
    }
    return res;
}

int Inv(int x){  return toPower(x, mod - 2); }
int add(int a, int b) { a %= mod; b %= mod; return ((a + b) % mod); }
int sub(int a, int b) { a %= mod; b %= mod; return  ((a - b + mod) % mod);}
