        fact[0] = fact[1] = 1;
        for (int i=2; i<=N; ++i) fact[i] = (fact[i-1] * i) % MOD;
        for (int i=0; i<=N; ++i) inv[i] = powmod(fact[i], MOD-2);
    }

public:
    Combination(int N, lint MOD) : N(N), MOD(MOD), fact(N + 1), inv(N + 1) {
        precomputation();
    }

    lint compute(int n, int k, bool duplicate = false) {
        if (duplicate) return compute(n+k-1, k);
        if (k == 0) return 1;
        if (n < k) return 0;
        lint res = fact[n];
        res = (res * inv[n-k]) % MOD;
        res = (res * inv[k]) % MOD;
        return res;
    }
};

lint powmod(lint x, lint k, lint MOD) {
	lint ret = 1;	
	while (k > 0) {
		if (k & 1) ret = (ret * x) % MOD;
        x = (x * x) % MOD;
		k >>= 1;
	}
	return ret;
}

int main() {
    int K;
    cin >> K;

    string S;
    cin >> S;

    int N = S.size();
    const lint MOD = lint(1e9) + 7;

    Combination comb(N + K, MOD);
    lint ans = 0;
    for_(i,0,K+1) {
        lint add = comb.compute(N, i, true);
        add = (add * powmod(25, i, MOD)) % MOD;
        add = (add * powmod(26, K - i, MOD)) % MOD;
        ans += add;
        ans %= MOD;
    }
    cout << ans << endl;
}

