    return *this = *this + a;
  }
  constexpr mint operator*(const mint &y) const {
    return mint(long(value) * y.value);
  }
  constexpr mint &operator*=(const mint &a) {
    return *this = *this * a;
  }
  constexpr mint operator-() const {
    return *this * mint(-1);
  }
  constexpr mint operator-(const mint &y) const {
    return *this + (-y);
  }
  constexpr mint &operator-=(const mint &a) {
    return *this = *this - a;
  }
  static mint pow(mint a, long n) {
    mint ans = 1;
    while (n > 0) {
      if (n & 1) ans *= a;
      a *= a;
      n >>= 1;
    }
    return ans;
  }
  mint inv() {
    return pow(value, MOD - 2);
  }
  static mint fact(const long n) {
    fill(n);
    return _fact[n];
  }
  static mint comb(const long n, const long k) {
    return fact(n) * fact(k).inv() * fact(n - k).inv();
