template<class T>
constexpr auto my_pow(T a, ll n) {
    if (n <= 0) {
        return T(1);
    } else if (n == 1) {
        return T(a);
    } else if (n % 2 == 0) {
        auto work = my_pow(a, n / 2);
        return work * work;
    } else {
        return my_pow(a, n - 1) * a;
    }
}

