//MODを考慮して、組み合わせ数を計算
class CombMod {
public:
	CombMod(int maxNo) {
		fac.resize(maxNo + 3);
		ifac.resize(maxNo + 3);
		//大した量ではないので，先にfax[i]とifax[i]を全て計算しておく
		fac[0] = 1;
		ifac[0] = 1;
		for (ll i = 0; i < fac.size() - 1; i++) {
			fac[i + 1] = fac[i] * (i + 1) % MOD; // n!(mod M)
			ifac[i + 1] = ifac[i] * mpow(i + 1, MOD - 2) % MOD; // k!^{M-2} (mod M) ←累乗にmpowを採用
		}
	}
	ll comb(ll a, ll b) { //aCbをmod計算
		if (a == 0 && b == 0)return 1;
		if (a < b || a < 0)return 0;
		ll tmp = ifac[a - b] * ifac[b] % MOD;
		return tmp * fac[a] % MOD;
	}
private:
	vector<ll> fac; //n!(mod M)
	vector<ll> ifac; //k!^{M-2} (mod M)
};

