int binpow(int a, int b, int mo) {
  if (a >= mo) a %= mo;
  int ans = 1;
  do {
    if (b & 1) ans = 1ll * ans * a % mo;
    a = 1ll * a * a % mo;
  } while (b >>= 1);
  return ans;
}
int modInv(int p) {
  if (p >= MOD) p %= MOD;
  return binpow(p, MOD - 2, MOD);
}
