constexpr long long MOD = 1e9 + 7;

constexpr int N = 1e6;

ll factorials[N];
ll inversed[N];

long long binExp(long long a, long long e) {
	if (e == 0) {
		return 1;
	}

	if (e % 2 == 1) {
		return (binExp(a, e - 1) * a) % MOD;
	}

	long long b = binExp(a, e / 2);
	return (b * b) % MOD;
}

long long f(long long a) {
	long long r = 1;
	for (long long i = 2; i <= a; ++i) {
		r = (r * i) % MOD;
	}

	return r;
}

long long c(long long n, long long k) {
	long long a = factorials[n];
	long long b = inversed[k];
	long long d = inversed[n - k];

	return ((a * b) % MOD * d) % MOD;
}

int main() {
	ll k;
	cin >> k;

	string s;
	cin >> s;

	ll n = s.length();

	for (int i = 0; i <= (n + k); ++i) {
		ll fact = f(i);
		factorials[i] = fact;
		inversed[i] = binExp(fact, MOD - 2);
	}

	ll ans = 0;
	for (int i = n; i <= (n + k); ++i) {
		ll a = (c(n + k, i) * binExp(25, n + k - i)) % MOD;
		ans = (ans + a) % MOD;
	}

	cout << ans;

	return 0;
}

