template <typename T> T ExtendedEuclidean(T a, T b, T &x, T &y) {
  if (b == 0) {
    x = 1;
    y = 0;
    return a;
  }
  T x1, y1;
  T d = ExtendedEuclidean(b, a % b, x1, y1);
  x = y1;
  y = x1 - y1 * (a / b);
  return d;
}
template <typename T> T invmod(T a, T b) {
  T x = 0, y = 0;
  ExtendedEuclidean(a, b, x, y);
  if (x < 0)
    x = (x % b) + b;
  return x;
}
ll ncr(ll n, ll r) {
  if (r > n)
    return 0;
  ll f = fac[n];
  f = (f * ifac[r]) % lmod;
  f = (f * ifac[n - r]) % lmod;
  return f;
}
inline ll mult(initializer_list<ll> il) {
  ll ret = 1;
  for (auto &x : il) {
    ret = (ret * (x % lmod)) % lmod;
  }
  return ret;
}
inline ll add(initializer_list<ll> il) {
  ll ret = 0;
  for (auto &x : il) {
    ret = (ret + (x % lmod)) % lmod;
  }
