template<usize N, typename T, T M>
struct factorial_mod {
	constexpr factorial_mod() : mod(), inv_mod() {
		mod[0] = 1;
		for (isize i = 0; i < N; ++i) {
			mod[i + 1] = (mod[i] * (T(i) + 1)) % M;
		}
		inv_mod[N] = power(mod[N], M - 2);
		for (isize i = N - 1; i >= 0; --i) {
			inv_mod[i] = (inv_mod[i + 1] * (T(i) + 1)) % M;
		}
	}

	constexpr auto power(T a, T b) const -> T {
		T r = 1;
		while (b > 0) {
			if ((b & 1) != 0) r = (r * a) % M;
			a = (a * a) % M;
			b >>= 1;
		}
		return r;
	}

	constexpr auto comb(T n, T r) const -> T {
		if (r < 0 || r > n || n < 0) {
			return 0;
		} else {
			return (((mod[n] * inv_mod[r]) % M) * inv_mod[n - r]) % M;
		}
	}

	constexpr auto H(T n, T r) -> T {
		return comb(n + r - 1, r);
	}

	T mod[N + 1];
	T inv_mod[N + 1];
};

