int mod = 1000000007;
struct mint{
    ll x;
    //コンストラクタ
    mint(ll x=0):x((x%mod+mod)%mod){}

    // %は若干遅いから，%を使わないようにしている
    mint& operator+=(const mint a){
        if((x += a.x) >= mod) x-= mod;
        return *this;
    }

    mint& operator-=(const mint a){
        if((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a){
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint power(ll t) const { // x^t
        if(!t) return 1;
        mint ans = power(t >> 1);
        ans *= ans;
        if(t&1) ans *= *this;
        return ans;
    }

    //素数が絡むやつ
    mint inv() const{
        return power(mod-2);
    }
    mint& operator/=(const mint a){
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const{
        mint res(*this);
        return res /= a;
    }
};

istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

struct combination{
    vector<mint> factorial, ifactorial;
    combination(int n) :factorial(n+1), ifactorial(n+1){
        factorial[0] = 1;
        //分子　そのまま計算
        for(int i = 1; i <= n; i++) factorial[i] = factorial[i-1] * i;

        //分母　処理が重いので一発で済ませたい
        ifactorial[n] = factorial[n].inv();
        for(int i = n; i >= 1; i--) ifactorial[i-1] = ifactorial[i] * i;
    }
    mint operator()(int n , int k){
        if(k < 0 || n < k) return 0;
        return factorial[n] * ifactorial[k] * ifactorial[n-k];
    }
};

