    long long Ans = C.modpow(26, M);
    for (int i = 0; i < N; i++) {
        long long tmp = C(M, i) * C.modpow(25, M-i) % mod;
        Ans += mod - tmp;
    }
    cout << Ans % mod << "\n";
    return 0;
}

