int exp(int A, int B, int C)  
{  
    if (A == 0)  
        return 0;
    if (B == 0)  
        return 1;
    long long y;  
    if (B % 2 == 0) {  
        y = exp(A, B / 2, C);  
        y = (y * y) % C;  
    }
    else {  
        y = A % C;
        y = (y * exp(A, B - 1, C) % C) % C;
    }
    return (int)((y + C) % C);  
}  

