template<int N> struct Mod {ll fact[N+1],invfact[N+1];Mod():fact(),invfact(){fact[0]=1;xrep(i,N)fact[i]=fact[i-1]*i%MOD;invfact[N]=modpow(fact[N],MOD-2);for(int i=N;i>0;i--)invfact[i-1]=invfact[i]*i%MOD;}};
