void solve(long long K, string S) {
  ll N = S.size();
  ll ans = 0;
  for (ll i = 0; i <= K; i++) {
    ll tmp = modpow((ll)26, K-i);tmp %= MOD;
    tmp *= modpow((ll)25, i);tmp %= MOD;
    tmp *= modnCr(i+N-1, N-1);tmp %= MOD;
    ans += tmp;ans %= MOD;
  }
  printf("%lld\n", ans);
}

int main() {
  long long K;
  scanf("%lld",&K);
  string S;
  cin >> S;
  solve(K, S);
  return 0;
}

