int power(int a, int b)
{
	int res = 1;
	while(b)
	{
		if(b & 1)
			res = (res * a) % mod;
		b >>= 1;
		a = (a * a) % mod;
	}
	return res % mod;
}

int modInv(int a)
{
	return power(a, mod - 2);
