void precompute()
{
	f[0] = f[1] = 1;
	for(int i = 2; i < M; i++)
		f[i] = (f[i - 1] * i) % mod;
	inv[M - 1] = modInv(f[M - 1]);
	for(int i = M - 2; i >= 0; i--)
		inv[i] = (inv[i + 1] * (i + 1)) % mod;
}

int nCr(int n, int r)
{
	if(n < r)	return 0;
	int res = f[n];
	res = (res * inv[r]) % mod;
	res = (res * inv[n - r]) % mod;
	return res % mod;
}

