        an *= modpow<ll>(26,i,mod);
        an %= mod;
        an *= C.com(N+K-i-1,N-1);
        an %= mod;
        an *= modpow<ll>(25,K-i,mod);
        an %= mod;

        //cout << an << endl;

        ans += an;
        ans %= mod;
    }

    cout << ans << endl;





    return 0;
}

