ll exp(ll x, ll n) {
	if (n == 1) {
		return x;
	}
	ll ans = exp(x, n >> 1) % MOD;
	if (n & 1) {
		return ans * ans % MOD * x % MOD;
	}
	else {
		return ans * ans % MOD;
	}
}

