ll solve(int K, string& s) {
  int oof_len = s.size();

  ll ans = 0;
  for (int r = 0; r <= K; ++r) {
    ll m25 = POW(25, r), m26 = POW(26, K - r), mag = MUL(m25, m26);

    ll c = nCk(oof_len + r - 1, oof_len - 1);
    ll local = MUL(c, mag);

    ans = ADD(ans, local);
  }
  return ans;
}

