// https://drken1215.hatenablog.com/entry/2018/06/08/210000
const lint MAX = 2e6+9;  // nCkのn,kの最大値
const lint MOD = mod;
lint fac[MAX];  // i!
lint inv[MAX];  // i^(-1)
lint finv[MAX];  // (i!)^(-1)

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
// 二項係数計算
lint COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
