class CombinationGenerator {
  int MAX_N_;
  int MOD_;
  long long* fac;
  long long* finv;
  long long* inv;

  public:
  CombinationGenerator(int MAX_N, int MOD) {
    MAX_N_ = MAX_N; MOD_ = MOD;
    fac = new long long[MAX_N];
    finv = new long long[MAX_N];
    inv = new long long[MAX_N];
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX_N; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
  }
  ~CombinationGenerator() {
    delete[] fac;
    delete[] finv;
    delete[] inv;
  }
  long long get(long long n, long long r) {
    if (n < r) return 0;
    if (n < 0 || r < 0) return 0;
    return fac[n] * (finv[r] * finv[n - r] % MOD_) % MOD_;
  }
};

long long modpow(long long a, long long n, long long mod) {
  long long res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

int main() {
  const int MOD = 1000000007;
  const int M = 26;

  int K;
  cin >> K;
  assert(K >= 1);

  string S;
