  assert(N >= 1);

  CombinationGenerator c(K+N, MOD);

  long long ans = 0;
  for (int i = K + N; i >= N; i--) {
    ans = (ans + (c.get(i-1, N-1) * modpow(M-1, i - N, MOD) % MOD) * modpow(M, K+N-i, MOD) % MOD) % MOD;
  }

  cout << ans << endl;

  return 0;
}

