{
	if (x.n <= 1)
	{
		return x;
	}
	if (y == 0)
	{
		return 1;
	}
	else if (y == 1)
	{
		return x;
	}
	else if (y % 2 == 0)
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp;
	}
	else
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp * x;
	}
}
