{
  int K;
  std::string S;
  std::cin >> K >> S;
  constexpr uint64_t p = std::pow(10, 9) + 7;
  unsigned int len = S.size() + K;
  ModComb mc(p, len);

  uint64_t ret = 0;
  for(uint64_t l=S.size(); l<=len; l++) {
    uint64_t r = mc.combination(l-1,  S.size()-1);
    r *= mc.pow(25, l - S.size());
    r %= p;
    r *= mc.pow(26, len - l);
    r %= p;
    ret += r;
    ret %= p;
  }

  std::cout << ret << std::endl;
  return 0;
}

