    for(int i=n-1;i>=0;--i){
        infun[i]=infun[i+1]*(i+1)%mod;
    }
}

ll C(ll n,ll m){
    if(n<m)return 0;
    return ((fun[n]*infun[n-m]%mod)*infun[m])%mod;
}

int main(){
    ll k;
    cin>>k;
    string s;
    cin>>s;
    ll ans=0;
    ll n = s.length();
    prepare(n+k);
    for(int i=n;i<=n+k;++i){
        ans=(ans+((C(i-1,n-1)*qp(25,i-n)%mod)*qp(26,n+k-i))%mod)%mod;
    }
    cout<<ans<<endl;
    return 0;
}

