int bpow(int a, int n, int mod = MOD) {
    int res = 1;

    for (; n > 0; n /= 2, (a *= a) %= mod)
        if (n & 1)
            (res *= a) %= mod;

    return res;
}

int rev(int x) {
    return bpow(x, MOD - 2, MOD);
}

int binomial(int n, int k) {
    return F[n] * rev(F[k] * F[n - k] % MOD) % MOD;
}

