using namespace std;
typedef long long ll;

#define MOD 1000000007


ll modpow(ll a, int n)
{
	ll res = 1;
	while (n > 0) {
		//ビットが立っていれば計算
		if (n & 1) {
			res = res * a % MOD;
		}
		//桁を二乗分ずらす
		a = a * a % MOD;
		n >>= 1;
	}
	return res;
}


class Combination
{
	vector<ll> fact;	//n!
	vector<ll> finv;	//n!の逆元
public:Combination(int n)
{
	vector<ll> inv(n + 1, 1);	//iの逆元
	fact.resize(n + 1, 1);
	finv.resize(n + 1, 1);
	for (int i = 2; i <= n; ++i) {
		fact[i] = fact[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

public:ll cmb(int n, int k)
{
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fact[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
};


int main()
{
	int K; cin >> K;
	string S; cin >> S;
	int len = K + S.size();
	Combination cmb = Combination(len);

	ll ans = 0;
	ll buf;
	//k文字を最後に置く。26**k通り
	//最後のk文字の前に固定の一文字
	//残りの文字の置き場所の選び方 cmb(len-k-1, S.size()-1) * 25**(K-k)
	for (int k = 0; k <= K; ++k) {
		//ans = ans + cmb.cmb(len - k - 1, S.size() - 1) * modpow(25, K - k) * modpow(26, k);
		buf = cmb.cmb(len - k - 1, S.size() - 1) * modpow(25, K - k) % MOD;
		buf = buf * modpow(26, k) % MOD;
		ans += buf;
		ans = ans % MOD;
	}
	cout << ans << endl;
}

