long long ksm(long long a, long long b) {
    if (b == 0) return 1;
    if (b & 1) return a * ksm(a * a % mod, b >> 1) % mod;
    return ksm(a * a % mod, b >> 1);
}
long long C(long long a, long long b) {
    return fac[a] * inv(fac[b] * fac[a - b] % mod) % mod;
}
