       val *= z;
     return val;
    };

    vector<mint> tf(n + k + 10, 1);
    for(int i = 0; i < n + k + 9; ++i)
        tf[i + 1] = tf[i] * 25;
    vector<mint> ts(n + k + 10, 1);
    for(int i = 0; i < n + k + 9; ++i)
        ts[i + 1] = ts[i] * 26;

    auto calc_fact = [mpow]{
     constexpr int N = 3e6;
     vector<mint> fact(N + 1, 1);
     vector<mint> inv(N + 1, 1);
     for(int i = 1; i < N; ++i){
      fact[i + 1] = fact[i] * (i + 1);
      inv[i + 1] = mpow(fact[i + 1], MOD - 2);
     }
     return make_pair(fact, inv);
    };
    vector<mint> fact, inv;
