LL gcdExtended(LL a, LL b, LL *x, LL *y) 
{ 
    // Base Case 
    if (a == 0) 
    { 
        *x = 0, *y = 1; 
        return b; 
    } 

    LL x1, y1; // To store results of recursive call 
    LL gcd = gcdExtended(b%a, a, &x1, &y1); 

