  static ll dp[4000000];
  static ll max_n=0;
  dp[0] = 1;
  while(n > max_n){
      dp[max_n+1] = dp[max_n]*(max_n+1) % mod;
      max_n++;
  }
  return dp[n];
}

ll powl(ll x,ll r,ll mod=mod){
  ll ret = 1;
  for(;r != 0;r >>= 1){
    if(r&1 != 0) ret *= x,ret %= mod;
    x *= x,x %= mod;
  }
  return ret;
}

