template<typename T>
struct Vector2 {
    T x, y;
    Vector2() {}
    Vector2(T x, T y) : x(x), y(y) {}
    void operator=(const Vector2 &other) {
        x = other.x;
        y = other.y;
    }
    Vector2 operator+(const Vector2 &other) {
        return Vector2(x + other.x, y + other.y);
    }
    Vector2 operator-(const Vector2 &other) {
        return Vector2(x - other.x, y - other.y);
    }
    bool operator==(const Vector2 &other) {
        return (x == other.x && y == other.y);
    }
    T dot(Vector2 other) {
        return x * other.x + y * other.y;
    }
    T det(Vector2 other) {
        return x * other.y - y * other.x;
    }
    T squared_norm() {
        return x * x + y * y;
    }
};

int N;
Vector2<double> P[55];
double ans=10000000.0;

tuple<Vector2<double>,double> calc_cent(Vector2<double> p1,Vector2<double> p2,Vector2<double> p3){
    double s=p1.x-p2.x,t=p1.y-p2.y,u=p2.x-p3.x,v=p2.y-p3.y;
    double a=(v*(p1.squared_norm()-p2.squared_norm())-t*(p2.squared_norm()-p3.squared_norm()))/(2.0*(s*v-t*u));
    double b=(-u*(p1.squared_norm()-p2.squared_norm())+s*(p2.squared_norm()-p3.squared_norm()))/(2.0*(s*v-t*u));
    Vector2<double> cent=Vector2<double>(a,b);
    Vector2<double> r=p1-cent;
    return make_tuple(cent,sqrt(r.squared_norm()));
}

bool check(int i,int j,int k){
    tuple<Vector2<double>,double> v=calc_cent(P[i],P[j],P[k]);
    Vector2<double> cent=get<0>(v);
    double r=get<1>(v);
    for(int i=0;i<N;++i){
        double d=sqrt((P[i].x-cent.x)*(P[i].x-cent.x)+(P[i].y-cent.y)*(P[i].y-cent.y));
        if(d>r)return false; 
    }
    chmin(ans,r);
    return true;
}

