ll bpow(ll x, ll p) {
	if (p == 0)
		return 1;
	if (p % 2)
		return (x * bpow(x, p - 1)) % mod;
	else {
		ll b = bpow(x, p / 2);
		return (b * b) % mod;
	}
}

ll inv(ll x) {
	return bpow(x, mod - 2);
}

void calc_fact() {
	fact[0] = 1;
	for (int i = 1; i < sz; i++)
		fact[i] = (fact[i - 1] * i) % mod;
}

ll cnk(ll nn, ll kk) {
	return fact[nn] * inv(fact[nn - kk]) % mod * inv(fact[kk]) % mod;
}

void solve() {
	cin >> k >> s;
