	calc_fact();
	ll ans = 0;
	for (int i = 0; i <= k; i++) {
		ans += cnk(n + k - i - 1, n - 1) * bpow(25, k - i) % mod * bpow(26, i) % mod;
		ans %= mod;
	}
	cout << ans;
}

