ll const MOD = 1000000007;
const ll MAX = 4000001;
ll fac[MAX], finv[MAX], inv[MAX];

ll mod_pow(ll a, ll n, ll p) {
  if (n == 1) return a % p;
  if (n % 2 == 1) return (mod_pow(a, 1, p) * mod_pow(a, n-1, p)) % p;
  ll t = mod_pow(a, n / 2, p);
  return (t * t) % p;
}

ll mod_multi(ll a, ll b, ll p) {
  ll res = 1;
  rep(i, b) {
    res = res * a % p;
    a--;
  }
  return res % p;
}

ll mod_com(ll a, ll b, ll p) {
  b = min(b, a-b);
  ll res = mod_multi(a, b, p);
  ll tmp = mod_multi(b, b, p);
  tmp = mod_pow(tmp, MOD-2, MOD) % MOD;

  res = (res * tmp) % MOD;
  return res;
}

void comb_init() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long comb(int n, int k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

