using ll = long long;
constexpr ll MOD=1e9+7;

ll inv(ll a, ll b = MOD){
    ll x0 = 1, y0 = 0, x1 = 0, y1 = 1;
    while (b != 0) {
        const ll q = a / b;
        ll tmp = a % b;
        a = b;
        b = tmp;
        tmp = x0 - q * x1;
        x0 = x1;
        x1 = tmp;
        tmp = y0 - q * y1;
        y0 = y1;
        y1 = tmp;
    }
    return (x0 + MOD) % MOD;
}

ll ncr(int n, int r){
    ll ret = 1;
    for(int i=0; i<r; ++i){
        ret = ((ret * (n-i)) % MOD) * inv(1+i) % MOD;
    }
    return ret;
}

ll pow_mod(ll x, ll n){
    if(n==0)return 1;
    if(n==1)return x;
    ll pow_half = pow_mod(x, n/2);
    return (pow_half * pow_half % MOD) * (n%2==0 ? 1 : x) % MOD;
}

constexpr int MAX_N = 2000000;
ll i_c_n[MAX_N+1], pow_25[MAX_N+1], pow_26[MAX_N+1];
void preprocess(ll n){
    pow_25[0]=1;
