    for(int i=1; i<=MAX_N; ++i){
        pow_25[i] = (pow_25[i-1] * 25) % MOD;
        pow_26[i] = (pow_26[i-1] * 26) % MOD;
    }
    i_c_n[n]=1;
    for(int i=n+1; i<=MAX_N; ++i){
        i_c_n[i] = (inv(i-n) * (i-1) % MOD) * i_c_n[i-1] % MOD;
    }
}

