		ULL tmpChairs4OtherLetters = iCnt + K - i - 1;
		ULL insPlacePatterns = nCk(tmpChairs4OtherLetters, (ULL)(iCnt - 1), (ULL)MOD);

		//inserted letter patterns
		ULL insLetsBeforeLastLet = K - i;
		ULL insLetPatterns = RepSq((ULL)26, (ULL)i, (ULL)MOD);
		insLetPatterns *= RepSq((ULL)25, insLetsBeforeLastLet, (ULL)MOD);
		insLetPatterns %= MOD;

		ans += (insPlacePatterns * insLetPatterns % MOD);
		ans %= MOD;
	}

	printf("%lld\n", ans);

	return 0;
}

ULL RepSq(ULL x, ULL n, ULL mod){
	if (n == 0)	return 1;

	ULL ret = 1;
	while (0 < n) {
		if (n & 1)
			ret = ret * x % mod;
		x = x * x % mod;
		n >>= 1;
	}
	return ret;
}

void nCk_init(ULL mod) {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++){
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		finv[i] = finv[i - 1] * inv[i] % mod;
	}
}

ULL nCk(int n, int k, ULL mod){
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	//Fermat's little theorem
	return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

