long long int modpow(long long int base, long long int turn, long long int mod)
{
	long long int ret = 1;
	while (turn > 0)
	{
		if (turn % 2 > 0)
			ret = ret * base % mod;
		base = base * base % mod;
		turn /= 2;
	}
	return ret;
}

