void cfact(){
  long long i;
  factorial[0]=1;
  factorial[1]=1;
  for(i=2;i<2097152;i++){
    factorial[i]=factorial[i-1]*i;
    factorial[i]%=mod;
  }
  invfact[2097151]=modular_inverse(factorial[2097151]);
  for(i=2097150;i>=0;i--){
    invfact[i]=invfact[i+1]*(i+1);
    invfact[i]%=mod;
  }
}

long long calcnCr(long long n,long long k){
  if(k<0 || n<k){return 0;}
  return (factorial[n]*((invfact[k]*invfact[n-k])%mod))%mod;
}

