	fact[0] = 1;
	for (i = 1; i < 2000006; i++)
		fact[i] = fact[i - 1] * i % p;
	long long int ans = 0;
	for (i = n; i <= n + k; i++)
		ans = (ans + comb(i - 1, n - 1, p) * modpow(25, i - n, p) % p * modpow(26, n + k - i, p) % p) % p;
	printf("%lld\n", ans);
	return 0;
}

