uint32_t add(uint32_t a, uint32_t b) {
	uint32_t r = a + b;
	if (r >= MOD_BY) r -= MOD_BY;
	return r;
}

uint32_t sub(uint32_t a, uint32_t b) {
	return b == 0 ? a : add(a, MOD_BY - b);
}

uint32_t mul(uint32_t a, uint32_t b) {
	return (uint32_t)((uint64_t)a * b % MOD_BY);
}

uint32_t pou(uint32_t a, uint32_t b) {
	uint32_t r = 1;
	while (b > 0) {
		if (b & 1) r = mul(r, a);
		a = mul(a, a);
		b >>= 1;
	}
	return r;
}

uint32_t inv(uint32_t a) {
	return pou(a, MOD_BY - 2);
}

