const long long mod = 1000000007LL;

ll fac[3300000];
ll finv[3300000];
ll inv[3300000];

void compre() {
  fac[0] = fac[1] = 1LL;
  finv[0] = finv[1] = 1LL;
  inv[1] = 1LL;
  for(ll i = 2LL; i<3050000; i++) {
    fac[i] = fac[i-1] * i % mod;
    inv[i] = mod - inv[mod%i] * (mod/i) % mod;
    finv[i] = finv[i-1] * inv[i] % mod;
  }
}

long long modcom(long long n, long long k) {
  if(n<k) return 0;
  if(n<0 || k<0) return 0;
  return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}

ll modpow(ll n, ll p, ll m) {
  if(p==0) return 1LL;
  if(p%2==0) {
    ll t = modpow(n, p/2, m);
    return t * t % m;
  }
  return n * modpow(n, p-1, m) % m;
}

int main() {
  ll k;
  cin >> k;
  string s;
  cin >> s;
  ll len = s.size();
  compre();
  ll ans = 0LL;
  for(int i = 0; i<=k; i++) {
    ll now = modpow(26LL,k-i,mod);
    now *= modpow(25LL,i,mod);
    now %= mod;
    now *= modcom(i+len-1,len-1);
    now %= mod;
    ans += now;
    ans %= mod;
  }
  cout << ans << endl;
  return 0;
}

