	public void solve() {
		int K = ni();
		int N = ns().length();
		long ans = 0, wk;
		COMinit();
		for (int i = 0; i <= K; i++) {
			wk = modpow(26, K-i);
			wk = (wk * modpow(25, i)) % mod;
			wk = (wk * COM(i + N - 1, i)) % mod;
			ans = (ans + wk) % mod;
		}
		out.println(ans);
