	// a の p 乗を求めるアルゴリズム				
	// p = 30 の時、p の変化は　30 -> 15 -> 14 -> 7 -> 6 -> 3 -> 2 -> 1 -> 0				
	// と、半分半分になっていくので、計算量は O(log p) となる				
	int mod = (int)(1e9) + 7;				
	long modpow(long a, int p) {				
		if(p == 0)	return 1;		
		if(p % 2 == 0) {			
			int halfP = p / 2;                        // 偶数なら		
			long half = modpow(a, halfP);    // 乗数を半分にする		
			return half * half % mod;           // 計算結果を２回かける　→　乗数を戻す		
		} else {			
			return a * modpow(a, p - 1) % mod; // 乗数から１を引いた結果に a を掛ける		
		}			
	}				
	int MAX = 2100000;
	int MOD = (int)(1e9) + 7;;
	long[] fac, finv, inv;			// a! (fac[a])   (a!)の-1乗 (finv[a])

	// テーブルを作る前処理　→　これを呼んでから COM() を呼ぶ
	void COMinit() {
		fac = new long[MAX];
		finv = new long[MAX];
		inv = new long[MAX];
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (int i = 2; i < MAX; i++){
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}
	// 組み合わせの数を計算する(a個の中からb個を選ぶ）
	long COM(int n, int k){
		if (n < k)		return 0;
		if (n < 0 || k < 0)		return 0;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}

