            long last=maxx-len;
            long ch_last=poww(26,last);
            long pos=bino(len-1,n-1);
            long ch25=poww(25,len-n);
            long cur=mul(mul(pos,ch25),ch_last);
            ans+=cur;
            ans%=mod;
        }
