            fact[j] = mul(fact[j-1],j);
        }
        factInv = new int[MAX];
        factInv[MAX-1] = BigInteger.valueOf(fact[MAX-1]).modInverse(md).intValue(); 
        for (int j = MAX-1; j >=1; j--) {
            factInv[j-1] = mul(factInv[j],j);
        }
        int[] d25 = new int[K+1];
