    static class FStrivore {
        private static final int MOD = (int) 1e9 + 7;
        private static final int MAX = 2_000_010;

        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int k = in.ints();
            int n = in.string().length();
            long ans = 0;
            ModMath mod = new ModMath();
            Exponentiation pow25 = mod.getExponentiation(25, MAX);
            Exponentiation pow26 = mod.getExponentiation(26, MAX);
            Factorial fact = mod.getFactorial(MAX);
            for (int j = 0; j <= k; j++) {
                long d = pow26.pow(j);
                d %= MOD;
                d *= pow25.pow(k - j);
                d %= MOD;
                d *= fact.nhr(n, k - j);
                d %= MOD;
                ans += d;
            }
            out.ans(ans % MOD).ln();
        }

    }

    static class Exponentiation {
        private final ModMath mod;
        private final long base;
        private final int max;
        private final long[] natural;
        private final long[] reverse;

        public Exponentiation(ModMath mod, long base, int max) {
            this.mod = mod;
            this.base = base;
            this.max = max;
            this.natural = new long[max];
            this.reverse = new long[max];
            natural[0] = 1;
            for (int i = 1; i < max; i++) {
                natural[i] = mod.mod(natural[i - 1] * base);
            }
            reverse[max - 1] = mod.inv(natural[max - 1]);
            for (int i = max - 1; i > 0; i--) {
                reverse[i - 1] = mod.mod(reverse[i] * base);
            }
        }

        public long pow(int x) {
            if (x >= 0) {
                return natural[x];
            } else {
                return reverse[-x];
            }
        }

        public String toString() {
            return "Exponentiation{" +
                    "natural=" + Arrays.toString(natural) +
                    ", reverse=" + Arrays.toString(reverse) +
                    '}';
        }

    }

