        void printLines(long[] x) {
            println(x, System.lineSeparator());
        }
        void printLines(Iterable<?> iterable) {
            println(iterable, System.lineSeparator());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
  private static int A_SIZE = 26;

  private static long solve(int k, char[] cs) {
    ModCalculator mc = new ModCalculator(1_000_000_007L);
    int n = k + cs.length;
    long answer = mc.pow(A_SIZE, n);
    for (int i = 0; i < cs.length; i++) {
      long v1 = mc.pow(A_SIZE - 1, n - i);
      long v2 = mc.getC(n, i);
      long v3 = mc.mul(v1, v2);
      answer = mc.sub(answer, v3);
    }
    return answer;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int k = reader.nextInt();
    char[] cs = reader.nextCharArray();
    out.println(solve(k, cs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

