import java.io.*;
import java.util.*;

public class Main {
	static void solve() {
		int k = ni();
		char[] s = ns().toCharArray();//多分sは文字数だけでなんでもいい
		int n = s.length;
		int m = k + n;

		preFact(300300);

		long dp[] = new long[m+1];//i文字目までを満たした場合の数
		for(int i=0;i<m;i++) {//i回目に完成したもの
			if(i - n < 0)continue;
			//i-1文字で、n-1文字完成してる
			long t = comb(i-1, n-1);
			long rem = i-n;//残りの文字数
			long t2 = comb(i-1, n);
			long rem2 = i-n-1;
			long tmp = mul(t, pow(26, rem));
			tmp = sub(tmp, mul(t2, pow(26, rem2)));
			dp[i] = tmp;
			dp[i] = dp[i] * pow(26, m-i) % mod;
		}
		long ans = 0;
		for(int i=0;i<m+1;i++) {
			ans += dp[i];
			ans %= mod;
		}
		out.println(ans);

	}

	//Fast Fermat Combination
	static long fact[];
	static long revFact[];

	static void preFact(int n) {
		fact = new long[n + 1];
		revFact = new long[n + 1];
		fact[0] = 1;
		for (int i = 0; i < n; i++) {
			fact[i + 1] = mul(i + 1, fact[i]);
		}
		revFact[n] = div(1, fact[n]);
		for (int i = n - 1; i >= 0; i--) {
			revFact[i] = mul(revFact[i + 1], i + 1);
		}
	}

	static long comb(int a, int b) {
		if (a < b)
			return 0;
		if (fact.length == 0)
			System.err.println("error : factorials has not been culculated!! do [pre_factorial] method");
		long af = fact[a];
		long bf = revFact[b];
		long abf = revFact[a - b];
		long res = mul(mul(af, bf), abf);
		return res;
	}


	//constant
