        long[] a = new long[m + 1];
        a[0] = a[1] = 1;
        for (int i = 2; i <= m; ++i) {
            a[i] = (a[i - 1] * i) % MOD;
        }

        for (int i = n; i <= m; ++i) {
            long v = pow(25, i - n);
            v = (v * a[i - 1]) % MOD;
            v = (v * inv(a[n - 1])) % MOD;
            v = (v * inv(a[i - n])) % MOD;
            v = (v * pow(26, m - i)) % MOD;
            ans = (ans + v) % MOD;
        }

        out.println(ans);
    }

