		fact[0] = 1;
		fact[1] = 1;
		for(int i = 2 ; i < fact.length; ++i){
			fact[i] = (i * fact[i - 1]) % MOD;
		}
		long sum = 0;
		for(int i = 0 ; i < S.length() ; ++i){
			long res = K + S.length() - i;
			long pat = modpow(25, res);
			pat = (pat * comb(K + S.length() , i , fact)) % MOD;
			sum = (sum + pat) % MOD;
		}
		long ret = (all - sum + MOD) % MOD;
		System.out.println(ret);
	}
}

