	public void solve() {
		int K = ni();
		int N = ns().length();
		long ans = 0, wk;
		for (int i = 0; i <= K; i++) {
			wk = modpow(26, K-i);
			wk = (wk * modpow(25, i)) % mod;
			wk = (wk * calcComb(i + N - 1, i)) % mod;
			ans = (ans + wk) % mod;
		}
		out.println(ans);
	}
	// a の p 乗を求めるアルゴリズム				
	// p = 30 の時、p の変化は　30 -> 15 -> 14 -> 7 -> 6 -> 3 -> 2 -> 1 -> 0				
	// と、半分半分になっていくので、計算量は O(log p) となる				
	int mod = (int)(1e9) + 7;				
	long modpow(long a, int p) {				
		if(p == 0)	return 1;		
		if(p % 2 == 0) {			
			int halfP = p / 2;                        // 偶数なら		
			long half = modpow(a, halfP);    // 乗数を半分にする		
			return half * half % mod;           // 計算結果を２回かける　→　乗数を戻す		
		} else {			
			return a * modpow(a, p - 1) % mod; // 乗数から１を引いた結果に a を掛ける		
		}			
	}				
	// 組み合わせの数を計算する(a個の中からb個を選ぶ）				
	//(10*9*8)/(3*2*1);				
	//10*9*8 -> ansMul				
	//3*2*1 -> ansDiv				
	long calcComb(int a, int b) {				
		if (b > a - b) return calcComb(a, a - b);			
		long ansMul = 1;			
		long ansDiv = 1;			
		for (int i = 0; i < b; i++) {			
			ansMul *= (a - i);		
			ansDiv *= (i + 1);		
			ansMul %= mod;		
			ansDiv %= mod;		
		}			
		//ansMul / ansDivをやりたい			
		//ansDivの逆元を使って求めよう！			
		// MOD p において、p が素数の場合、a の逆元は　a ^ (p-2) となる			
		// Fermat の小定理 a^(p-1) = 1(MOD p) --> a * a^(p - 2) = 1(MOD p)　より			
		long ans = ansMul * modpow(ansDiv, mod - 2) % mod;			

		return ans;			
	}				

