import java.util.*;

public class Main {

	// global
	static int mod = 1_000_000_007;
	static long fact[];
	static long inverse[];

	static long pow(long a,int n) {
	    long res=1;
	    while (n>0) {
	        if ((n-n/2*2)==1) {
	            res=res*a%mod;
	        }
	        a=a*a%mod;
	        n>>=1;
	    }
	    return res;
	}

	static long modinv(long n) {
	    return pow(n, mod-2);
	}

	static long comb(int n,int k){
    	if(n<0 || k<0 || n<k)return 0;
    	return fact[n]*(inverse[k]*inverse[n-k]%mod) %mod;
	}


	public static void main(String[] args) {
		// main method
		fact=new long[300000];
		fact[0]=1;
		inverse=new long[300000];
		inverse[0]=1;
		for(int i=1;i<300000;i++){
		    fact[i]=(fact[i-1]*(long)i)%mod;
		    inverse[i]=modinv(fact[i]);
		}
		Scanner sc = new Scanner(System.in);
		int K = sc.nextInt();
		String S = sc.next();

		int N = S.length();
		long ans = 0L;
		for (int i=N;i<=K+N;i++) {
			ans = (ans + comb(i-1, N-1)*pow(25, i-N)%mod*pow(26, K+N-i)%mod)%mod;
		}
		System.out.println(ans);
	}
}

import java.util.*;
