public class Main {
    private long fac[];
    private long finv[];
    private long inv[];
    private static int MAX_LEN = 2100000;
    private static int MOD = 1000000007;
    public static void main(String[] args) throws Exception {
        Main main = new Main();
        main.COMinit();
        main.solve();
    }

    private long pow(int base, int count, long MOD) {
        if (count == 0) {
            return 1;
        }
        if (count % 2 == 1) {
            long t = ((long) base) * pow(base, count - 1, MOD);
            t %= MOD;
            return t;
        }
        long t = pow(base, count / 2, MOD);
        t %= MOD;
        t *= t;
        t %= MOD;
        return t;
    }
    public void solve() throws Exception {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int K = scan.nextInt();
        String S = scan.next();
        int N = S.length();
        long ans = 0;
        for (int i = 0; i <= K; i++) {
            long t1 = COM(i + N - 1, i);
            long t2 = pow(25, i, MOD);
            long t3 = pow(26, K - i, MOD);
            long t = t1 * t2;
            t %= MOD;
            t *= t3;
            t %= MOD;
            ans += t;
            ans %= MOD;
        }
        System.out.println(ans);
    }
    void COMinit() {
        this.fac = new long[MAX_LEN];
        this.finv = new long[MAX_LEN];
        this.inv = new long[MAX_LEN];
        this.fac[0] = this.fac[1] = 1;
        this.finv[0] = this.finv[1] = 1;
        this.inv[1] = 1;
        for (int i = 2; i < MAX_LEN; i++) {
            fac[i] = fac[i-1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i-1] * inv[i] % MOD;
        }
    }
    long COM(int n, int k) {
        if (n < k) {
            return 0;
        };
        if (n <0 || k < 0) {
            return 0;
        }
        return fac[n] * (finv[k] * finv[n - k]%MOD)%MOD;
    }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int add = scanner.nextInt();
		String temp = scanner.next();
		int length = temp.length();
		long mod = (long) (Math.pow(10, 9) + 7l);
		int amount = length + add;
		long[] powers = new long[amount + 1];
		powers[0] = 1l;
		for (int i = 0; i < powers.length - 1; i++) 
		    powers[i + 1] = powers[i] * 25 % mod;

		long result = 1l;
		for(int i = 0; i < amount; i++) 
			result = result * 26 % mod;
		for(int i = 0; i < length; i++) {
			long temporal = powers[amount - i] * nCrModPFermat(amount, i, mod) % mod;
			result -= temporal;
			while(result < 0)
				result += mod;
			result %= mod;
		}
		System.out.print(result);
	}

	static long modInverse(long n, long p) 
    { 
        return power(n, p-2, p); 
    } 

	static long power(long x, long y, long p) 
    { 
        long res = 1l; 

        x = x % p; 

        while (y > 0) 
        { 

            if (y % 2 == 1) 
                res = (res * x) % p; 

            y = y >> 1;
            x = (x * x) % p; 
        } 
        return res; 
    } 

    static long nCrModPFermat(int n, int r, long p) { 

        if (r == 0) 
            return 1; 

        long[] fac = new long[n+1]; 
        fac[0] = 1; 

        for (int i = 1 ;i <= n; i++) 
            fac[i] = fac[i-1] * i % p; 

        return (fac[n]* modInverse(fac[r], p) 
                % p * modInverse(fac[n-r], p) 
                                    % p) % p; 
    } 
}

