      fact[0] = 1;
      for(int i = 1; i < 2000001; i++)
    	  fact[i] = (fact[i-1]*i)%mod;
      long[] pow25 = new long[1000001];
      long[] pow26 = new long[1000001];
      pow25[0] = 1;
      pow26[0] = 1;
      for(int i = 1; i < 1000001; i++) {
    	  pow25[i] = (pow25[i-1]*25)%mod;
    	  pow26[i] = (pow26[i-1]*26)%mod;
      }
      long inv = pow(fact[s.length()-1],mod-2);
      for(int i = 0; i <= k; i++) {
    	  ans = (ans + multiply(pow25[i],multiply(multiply(pow26[k-i],fact[s.length()+i-1]),multiply(inv,pow(fact[i],mod-2)))))%mod;
      }
      out.println(ans);
      out.close();
   }
   static long multiply(long a, long b) {
	   return (a*b)%mod;
   }
   static long pow(long l, int p) {
	   if(p == 0)
		   return 1;
	   if(p == 1 || l == 1)
		   return l;
	   long temp = pow(l, p/2);
	   long temp1 = (temp*temp)%mod;
	   if(p%2 == 1)
		   temp1 = (temp1*l)%mod;
	   return temp1;
   }
}

