    public static void solve(StringBuilder out) {
        ModuloArithmetic ma = new ModuloArithmetic(Const.MOD7);
        int k = In.ni();
        char[] s = In.nc();
        int n = s.length;
        long ans = 0;
        long[] p25 = new long[k + 1];
        p25[0] = 1;
        for (int i = 1; i <= k; i++) {
            p25[i] = (p25[i - 1] * 25) % ma.MOD;
        }
        long[] p26 = new long[k + 1];
        p26[0] = 1;
        for (int i = 1; i <= k; i++) {
            p26[i] = (p26[i - 1] * 26) % ma.MOD;
        }
        long[] fac = ma.factorialArray(n + k);
        long[] ifac = ma.inversiveFactrialArray(fac);
        for (int j = 0; j <= k; j++) {
            long c = ma.prod(fac[n - 1 + j], ifac[j], ifac[n - 1]);
            ans += ma.prod(c, p25[j], p26[k - j]);
        }
        out.append(ma.mod(ans));
    }
