    static class Task{
        static int MOD = 1000000007;
        public long pow(long x, long y){
            if (y == 0){
                return 1;
            }
            else{
                long au = pow(x, y / 2);
                au = (au * au) % MOD;
                if (y % 2 == 0){
                    return au;
                }
                else{
                    return (au * x)% MOD;
                }
            }
        }
        public void solve(InputReader in, PrintWriter out){
            int k = in.nextInt();
            String s = in.nextToken();
            int n = s.length();
            long cur = pow(26, k);
            long total = cur;
            for (int last = n + 1; last <= n + k; last++){
                cur = (cur * 25) % MOD;
                cur = (cur * (last -  1)) % MOD;
                cur = (cur * pow(26, MOD - 2)) % MOD;
                cur = (cur * pow(last - n, MOD - 2)) % MOD;
                total = (total + cur) % MOD;
            }
            out.println(total);
        }
    }
