	public struct IntPair
	{
		public int First;
		public int Second;

		public IntPair(string s)
		{
			var split = s.Split();
			First = int.Parse(split[0]);
			Second = int.Parse(split[1]);
		}

		public IntPair(int first, int second)
		{
			First = first;
			Second = second;
		}

		public static bool operator ==(IntPair p1, IntPair p2) => p1.First == p2.First && p1.Second == p2.Second;
		public static bool operator !=(IntPair p1, IntPair p2) => p1.First != p2.First || p1.Second != p2.Second;
		public override string ToString() => $"{First} {Second}";
		public override bool Equals(object obj)
		{
			var p = obj as IntPair?;
			return p.HasValue && p.Value.First == First && p.Value.Second == Second;
		}

		public override int GetHashCode()
		{
			uint rol5 = ((uint)First << 5) | ((uint)First >> 27);
			return ((int)rol5 + First) ^ Second;
		}

		public static long UpperBound(long min, long max, Predicate<long> test)
		{
			long ans = min;
			long s = min;
			long e = max;
			while (s <= e)
			{
				long mid = (s + e) / 2;
				if (test(mid))
				{
					ans = mid;
					s = mid + 1;
				}
				else
					e = mid - 1;
			}

			return ans;
		}

		public static long LowerBound(long min, long max, Predicate<long> test)
		{
			long ans = max;
			long e = max;
			long s = min;

			while (s <= e)
			{
				long mid = (s + e) / 2;

				if (test(mid))
				{
					ans = mid;
					e = mid - 1;
				}
				else
					s = mid + 1;
			}

			return ans;
		}

	}

