class Solver
{
    public void Solve()
    {
        //Solve Code Here
        int k = Cin;
        string s = Cin;
        var factorial = new ModInt[s.Length + k + 1];
        factorial[0] = 1;
        for (int i = 1; i <= s.Length + k; i++) factorial[i] = factorial[i - 1] * i;
        var mul25 = new ModInt[k + 1];
        mul25[0] = 1;
        for (int i = 0; i < k; i++) mul25[i + 1] = mul25[i] * 25;
        var mul26 = new ModInt[k + 1];
        mul26[0] = 1;
        for (int i = 0; i < k; i++) mul26[i + 1] = mul26[i] * 26;
        ModInt ans = 0;
        for (int i = 0; i <= k; i++)
        {
            ans += mul25[k - i] * mul26[i] * factorial[k + s.Length - i - 1] /
                   (factorial[s.Length - 1] * factorial[k - i]);
        }

        Coutln(ans);
    }
}

