		static long xGCD(long a, long b, out long x, out long y)
		{
			if (b == 0)
			{
				x = 1;
				y = 0;
				return a;
			}

			long x1, y1;
			long gcd = xGCD(b, a % b, out x1, out y1);
			x = y1;
			y = (int)(x1 - (long)(a / b) * y1);
			return gcd;
		}
		static long inverse(long a)
		{
			long x, y;
			xGCD(a, (int)MOD, out x, out y);
			return x;
		}
