public class Scanner {
    private readonly TextReader Reader;
    private readonly CultureInfo ci = CultureInfo.InvariantCulture;

    private readonly char[] buffer = new char[2 * 1024];
    private int cursor = 0, length = 0;
    private string Token;
    private readonly StringBuilder sb = new StringBuilder(1024);

    public Scanner()
        : this(Console.In) {
    }

    public Scanner(TextReader reader) {
        Reader = reader;
    }

    public int NextInt() { return checked((int)NextLong()); }
    public long NextLong() {
        var s = Next();
        long r = 0;
        int i = 0;
        bool negative = false;
        if (s[i] == '-') {
            negative = true;
            i++;
        }
        for (; i < s.Length; i++) {
            r = r * 10 + (s[i] - '0');
#if DEBUG
            if (!char.IsDigit(s[i])) throw new FormatException();
#endif
        }
        return negative ? -r : r;
    }
    public double NextDouble() { return double.Parse(Next(), ci); }
    public string[] NextArray(int size) {
        string[] array = new string[size];
        for (int i = 0; i < size; i++) {
            array[i] = Next();
        }

        return array;
    }
    public int[] NextIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextInt();
        }

        return array;
    }

    public long[] NextLongArray(int size) {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextLong();
        }

        return array;
    }

    public double[] NextDoubleArray(int size) {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextDouble();
        }

        return array;
    }

    public string Next() {
        if (Token == null) {
            if (!StockToken()) {
                throw new Exception();
            }
        }
        var token = Token;
        Token = null;
        return token;
    }

    public bool HasNext() {
        if (Token != null) {
            return true;
        }

        return StockToken();
    }

    private bool StockToken() {
        while (true) {
            sb.Clear();
            while (true) {
                if (cursor >= length) {
                    cursor = 0;
                    if ((length = Reader.Read(buffer, 0, buffer.Length)) <= 0) {
                        break;
                    }
                }
                var c = buffer[cursor++];
                if (33 <= c && c <= 126) {
                    sb.Append(c);
                } else {
                    if (sb.Length > 0) break;
                }
            }

            if (sb.Length > 0) {
                Token = sb.ToString();
                return true;
            }

            return false;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder.Abc171
{
    public class ModularCombinationFixedK
    {
        int k;
        long mod;
        long[] combination;

        public ModularCombinationFixedK(int maxN, int k, long mod)
        {
            combination = new long[maxN + 1];
            this.k = k;
            this.mod = mod;

            combination[k] = 1;
            for (int i = k; i < maxN; i++)
                combination[i + 1] = combination[i] * (i + 1) % mod * Inverse(i - k + 1) % mod;
        }

        public ModularCombinationFixedK(int n, long mod) : this(n, n, mod) { }

        public long Get(int n)
        {
            return combination[n];
        }

        long Inverse(long a)
        {
            long i = mod, v = 0, d = 1;
            while (a > 0)
            {
                long t = i / a, x = a;
                a = i % x;
                i = x;
                x = d;
                d = v - t * x;
                v = x;
            }
            v %= mod;
            if (v < 0) v = (v + mod) % mod;
            return v;
        }
    }

    class F
    {
        static readonly long mod = 1000000007;

        public static void Main()
        {
            var k = int.Parse(Console.ReadLine());
            var s = Console.ReadLine();

            int n = k + s.Length;

            var comb = new ModularCombinationFixedK(n - 1, s.Length - 1, mod);
            long ans = 0;

            var pow26 = new long[k + 1];
            pow26[0] = 1;
            for (int i = 1; i <= k; i++)
                pow26[i] = (pow26[i - 1] * 26) % mod;

            long pow25 = 1;
            for (int i = 0; i <= k; i++)
            {
                ans += (comb.Get(s.Length - 1 + i) * pow25) % mod * pow26[k - i] % mod;
                pow25 = pow25 * 25 % mod;
            }
            Console.WriteLine(ans);
        }
    }
}

