namespace CSharpSpiral {
  class Program {
    public static void Main(string[] args) {
      var sw = new StreamWriter(Console.OpenStandardOutput()) {
        AutoFlush=
#if DEBUG
      true
#else
			false
#endif
      };
      Console.SetOut(sw);
      new Program().Solve(new ConsoleInput(
#if DEBUG
      new StreamReader("../../../inputData.txt")
#else
			Console.In
#endif
      , ' '));
      Console.Out.Flush();
    }
    public void Solve(ConsoleInput cin) {
			const int modulo = 1_000_000_007;
			var F = new ResidueField(modulo);
			var K = cin.ReadInt;
			var SL = cin.ReadLine.Length;
			var TwentyFives = new long[K+1];
			TwentyFives[0]=1;
			var TwentySixes = new long[K+1];
			TwentySixes[0]=1;
			for(int i = 1; i<=K; i++) {
				TwentyFives[i]=(TwentyFives[i-1]*25)%modulo;
				TwentySixes[i]=(TwentySixes[i-1]*26)%modulo;
			}
			var Combinations = new long[K+1];
			Combinations[0]=1;
			for(int i = 0; i<K; i++) {
				Combinations[i+1]=F.Mul(F.Div(i+SL, i+1), Combinations[i]);
			}
			var sum = Enumerable.Range(0, K+1).Sum(j =>
				F.Mul(Combinations[j], F.Mul(TwentyFives[j], TwentySixes[K-j]))
			);
			Console.WriteLine(sum%modulo);
    }
  }

  static class ExtendClass {
    public static string Join<T>(this IEnumerable<T> X, string separator = " ") => string.Join(separator, X);
    public static int LastOrDefault(this SortedSet<int> S) {
      return S.Any() ? S.Last() : int.MaxValue;
    }
    public static void MergeSort<T>(this T[] A, bool desending) where T : IComparable<T> {
      if(desending)
        MergeSort(A, Comparer<T>.Create((x, y) => y.CompareTo(x)));
      else
        MergeSort(A, Comparer<T>.Create((x, y) => x.CompareTo(y)));
    }
    public static void MergeSort<T>(T[] A, IComparer<T> comparer) where T : IComparable<T> {
      MergeSort1(0, A.Length, A, comparer);
    }
    private static void Merge<T>(int left, int mid, int right, T[] A, IComparer<T> comparer)
      where T : IComparable<T> {
      var nl = mid-left;
      var nr = right-mid;
      var L = new T[nl];
      var R = new T[nr];
      for(int i = 0; i<nl; i++)
        L[i]=A[i+left];
      for(int i = 0; i<nr; i++)
        R[i]=A[i+mid];
      int il = 0, ir = 0;
      for(int k = left; k<right; k++) {
        if(comparer.Compare(L[il], R[ir])<=0) {
          A[k]=L[il++];
          if(il==nl) {
            k++;
            for(; ir<nr;)
              A[k++]=R[ir++];
            break;
          }
        } else {
          A[k]=R[ir++];
          if(ir==nr) {
            k++;
            for(; il<nl;)
              A[k++]=L[il++];
            break;
          }
        }
      }
    }
    private static void MergeSort1<T>(int left, int right, T[] A, IComparer<T> comparer)
    where T : IComparable<T> {
      if(left+1<right) {
        var mid = (left+right)/2;
        MergeSort1(left, mid, A, comparer);
        MergeSort1(mid, right, A, comparer);
        Merge(left, mid, right, A, comparer);
      }
    }
  }
  class ConsoleInput {
    private readonly TextReader _stream;
    private readonly char _separator = ' ';
    private readonly Queue<string> inputStream;
    public ConsoleInput(TextReader stream, char separator = ' ') {
      this._separator=separator;
      this._stream=stream;
      inputStream=new Queue<string>();
    }
    public string Read {
      get {
        if(inputStream.Count!=0) return inputStream.Dequeue();
        string[] tmp = _stream.ReadLine().Split(_separator);
        for(int i = 0; i<tmp.Length; ++i)
          inputStream.Enqueue(tmp[i]);
        return inputStream.Dequeue();
      }
    }
    public string ReadLine { get { return _stream.ReadLine(); } }
    public int ReadInt { get { return int.Parse(Read); } }
    public long ReadLong { get { return long.Parse(Read); } }
    public double ReadDouble { get { return double.Parse(Read); } }
    public string[] ReadStrArray(long N) {
      var ret = new string[N];
      for(long i = 0; i<N; ++i)
        ret[i]=Read;
      return ret;
    }
    public int[] ReadIntArray(long N) { var ret = new int[N]; for(long i = 0; i<N; ++i) ret[i]=ReadInt; return ret; }
    public long[] ReadLongArray(long N) { var ret = new long[N]; for(long i = 0; i<N; ++i) ret[i]=ReadLong; return ret; }
    public double[] ReadDoubleArray(long N) { var ret = new double[N]; for(long i = 0; i<N; ++i) ret[i]=ReadDouble; return ret; }
    public bool isEOF {
      get { return _stream.Peek()==-1; }
    }
	}
	class ResidueField: QuotientRing {
		public ResidueField(int _modulo = 1000*1000*1000+7) : base(_modulo) { }
		private static long extgcd(long a, long b, ref long x, ref long y) {
			if(b==0) {
				x=1; y=0; return a;
			}
			var q = a/b;
			var g = extgcd(b, a-q*b, ref x, ref y);
			var z = x-q*y;
			x=y; y=z;
			return g;
		}
		public long Inv(long a) {
			if(a==0) throw new DivideByZeroException();
			long x = 0, y = 0;
			extgcd(a, modulo, ref x, ref y);
			return mod(x);
		}
		public long Div(long a, long b) => Mul(a, Inv(b));
	}
	class QuotientRing {
		public readonly long modulo;
		public QuotientRing(int mModulo = 1000*1000*1000+7) {
			modulo=mModulo;
		}
		private long[] factorialTable = { 1 };
		private int factorialTableLastIndex { get { return factorialTable.Length-1; } }
		public long mod(long x) => x<0 ? x%modulo+modulo : x%modulo;
		public long Add(long a, long b) => mod(a+b);
		public long Sub(long a, long b) => mod(a-b);
		public long Mul(long a, long b) => mod(a*b);
		public long Pow(long a, long n) {
			if(n==0) return 1;
			var R = 1L;
			n=n<0 ? n%(modulo-1)+(modulo-1) : n%(modulo-1);
			for(; n>0; a=Mul(a, a), n>>=1) {
				if((n&1)!=0) R=Mul(R, a);
			}
			return R;
		}
		private void ExpandFactorialTable(int N) {
			var k = factorialTableLastIndex;
			Array.Resize(ref factorialTable, N+1);
			for(int i = k+1; i<=N; i++) {
				if(i==0) { factorialTable[i]=1; continue; }
				factorialTable[i]=Mul(factorialTable[i-1], i);
			}
		}
		public long Factorial(int n) {
			if(n>factorialTableLastIndex)
				ExpandFactorialTable(n);
			return factorialTable[n];
		}
	}
}

