    public void Solve(ConsoleInput cin) {
			const int modulo = 1_000_000_007;
			var F = new ResidueField(modulo);
			var K = cin.ReadInt;
			var SL = cin.ReadLine.Length;
			var TwentyFives = new long[K+1];
			TwentyFives[0]=1;
			var TwentySixes = new long[K+1];
