  static class ExtendClass {
    public static string Join<T>(this IEnumerable<T> X, string separator = " ") => string.Join(separator, X);
    public static int LastOrDefault(this SortedSet<int> S) {
      return S.Any() ? S.Last() : int.MaxValue;
    }
    public static void MergeSort<T>(this T[] A, bool desending) where T : IComparable<T> {
      if(desending)
        MergeSort(A, Comparer<T>.Create((x, y) => y.CompareTo(x)));
      else
        MergeSort(A, Comparer<T>.Create((x, y) => x.CompareTo(y)));
    }
    public static void MergeSort<T>(T[] A, IComparer<T> comparer) where T : IComparable<T> {
      MergeSort1(0, A.Length, A, comparer);
    }
    private static void Merge<T>(int left, int mid, int right, T[] A, IComparer<T> comparer)
      where T : IComparable<T> {
      var nl = mid-left;
      var nr = right-mid;
      var L = new T[nl];
      var R = new T[nr];
      for(int i = 0; i<nl; i++)
        L[i]=A[i+left];
      for(int i = 0; i<nr; i++)
        R[i]=A[i+mid];
      int il = 0, ir = 0;
      for(int k = left; k<right; k++) {
        if(comparer.Compare(L[il], R[ir])<=0) {
          A[k]=L[il++];
          if(il==nl) {
            k++;
            for(; ir<nr;)
              A[k++]=R[ir++];
            break;
          }
        } else {
          A[k]=R[ir++];
          if(ir==nr) {
            k++;
            for(; il<nl;)
              A[k++]=L[il++];
            break;
          }
        }
      }
    }
    private static void MergeSort1<T>(int left, int right, T[] A, IComparer<T> comparer)
    where T : IComparable<T> {
      if(left+1<right) {
        var mid = (left+right)/2;
        MergeSort1(left, mid, A, comparer);
        MergeSort1(mid, right, A, comparer);
        Merge(left, mid, right, A, comparer);
      }
    }
  }
