    static ModInt[] Power25 = new ModInt[2000001];
    static ModInt[] Power26 = new ModInt[2000001];

    static ModInt Power(ModInt n, long m)
    {
        ModInt pow = n;
        ModInt res = 1;
        while (m > 0)
        {
            if ((m & 1) == 1) res *= pow;
            pow *= pow;
            m >>= 1;
        }
        return res;
    }

