        InvFactorial[InvFactorial.Length - 1] = 1 / Factorial[Factorial.Length - 1];
        for (int i = InvFactorial.Length - 2; i >= 0; i--) InvFactorial[i] = InvFactorial[i + 1] * (i + 1);
        Power25[0] = 1;
        Power26[0] = 1;
        for (int i = 1; i < Power25.Length; i++)
        {
