class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int k = sc.Int;
        var s = sc.Str;
        int n = s.Length;
        long ans = 0;
        MyMath.setfacts(k + n + 9);
        for (int i = 0; i <= k; i++)
        {
            long p = MyMath.comb(n + i - 1, i) * MyMath.pow(25, i) % M;
            ans = (ans + p * MyMath.pow(26, k - i)) % M;
        }
        Prt(ans);

    }
}

