				TwentyFives[i]=(TwentyFives[i-1]*25)%modulo;
				TwentySixes[i]=(TwentySixes[i-1]*26)%modulo;
			}
			var sum = Enumerable.Range(0, K+1).Sum(j =>
			F.Mul(F.Combination(j+SL-1, SL-1), F.Mul(TwentyFives[j], TwentySixes[K-j]))
			);
			Console.WriteLine(sum%modulo);
    }
