		v %= ModInt.Mod;
		if (v < 0) v += ModInt.Mod;
		return new ModInt(v);
	}
	public static ModInt mod(this int v) {
		var u = v % ModInt.Mod;
		if (u < 0) u += ModInt.Mod;
