function ruijoR(num, x, divider){
  var ans = [1];
  var tmp = 1;
  for (var i = 0; i <= x; i++){
      tmp *= num;
      tmp %= divider;
      ans.push(tmp);
  }
  return ans;
}
function nCr_amari(n, k, MAX, MOD, C2) {
// 前処理
var v_ans = [ ];
var fac, finv, inv;
fac = [1,1];
finv = [1,1];
inv = [0,1];
for (var i = 2; i < (n + MAX); i++){
    fac.push(fac[i - 1] * i % MOD);
    inv.push(MOD - kakeruR(inv[MOD%i], (MOD / i | 0), MOD, C2) % MOD);
    finv.push(kakeruR(finv[i - 1],inv[i] ,MOD,C2));
}
  //二項係数計算
if (n < k) return 0;
if (n < 0 || k < 0) return 0;
for (var i = 0; i < MAX; i++){
  v_ans.push(kakeruR(kakeruR(fac[n + i] , finv[k + i],MOD,C2), finv[n - k],MOD,C2));
}
return v_ans;
}
function kakeruR(a, b, C, C2){
var tmpQ, tmpR, ans;
  tmpQ =  (b / C2 | 0);
  tmpR =  b - (tmpQ * C2);
  ans = (a * tmpQ % C) * C2 % C + (a * tmpR);
  ans %= C;
return ans;
}

