class Combinatorics
  def initialize(n, mod)
    @mod = mod
    @fact, @inv, @finv = Array.new(3){[1, 1]}
    2.upto(n) do |i|
      @fact[i] = (@fact[i-1] * i) % @mod
      @inv[i]  = (@inv[@mod % i] * (@mod - @mod / i) ) % @mod
      @finv[i] = (@finv[i-1] * @inv[i] ) % @mod
    end
  end
  def combination(n, r)
    return 0 if (n < r) || (n < 0) || (r < 0)
    (@fact[n] * @finv[n-r] % @mod) * @finv[r] % @mod
  end
  def permutation(n, r)
    @fact[n] * @finv[n-r] % @mod
  end
end
def power(m, n, mod)
  return 1 if n.zero?
  n.odd? ? (power(m, n - 1, mod) * m % mod) : power(m * m % mod, n >> 1, mod)
end
