	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	COMinit()

	k, s := nextInt(), next()
	n := len(s)

	ans := int64(0)
	pow := int64(modPow(25, k, int(MOD)))
	for x := 0; x <= k; x++ {
		add := (COM(int64(n+k-x-1), int64(n-1)) * pow) % MOD
		ans += add
		ans %= MOD

		pow *= int64(26 * modInv(25, int(MOD)))
		pow %= MOD
	}

	puts(ans)
}

