		inv[i] = (mod - inv[mod%i]*(mod/i)) % mod
		if inv[i] < 0 {
			inv[i] += mod
		}
		ifac[i] = (ifac[i-1] * inv[i]) % mod
	}

	var k int
	fmt.Scan(&k)
	var s string
	fmt.Scan(&s)
	n := len(s)
	var sum int
	for i := n; i <= k+n; i++ {
		a := comb(k+n, i) * modpow(25, k+n-i)
		sum += a
		sum %= mod
	}
	fmt.Println(sum)
}

func comb(n, r int) int {
	if r > n {
		return 0
	} else if r == 0 || r == n {
		return 1
	}
	t := (ifac[n-r] * ifac[r]) % mod
	return (t * fac[n]) % mod
}

func modpow(a, n int) int {
	res := 1
	for n > 0 {
		if n&1 > 0 {
			res *= a
			res %= mod
		}
		a = a * a % mod
		n >>= 1
	}
	return res
}

