const p = 1000000007

func Factorial(N int) (F, Finv, Inv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  Inv = make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  Inv[0] = 1
  Inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    Inv[i] = p - Inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * Inv[i] % p
  }
  return
}

func Comb(F, Finv *[]int, A ...int) int {
  S := SumInt(A...)
  C := (*F)[S]
  for _, a := range A {
    C *= (*Finv)[a]
    C %= p
  }
  return C
}

func Pow(n, k int) int {
  a := 1
  for ; 0 < k; k /= 2 {
    if k % 2 == 1 { a = (a * n) % p }
    n = (n * n) % p
  }
  return a
}

func Solve() {
  var K int
  NextInt(&K)
  S := NextLine()
  N := len(S)
  F, Finv, _ := Factorial(N + K)
  P := 0
  for k := 0; k <= K; k++ {
    P += (Pow(25, k) * Comb(&F, &Finv, N - 1, k) % p) * Pow(26, K - k) % p
    P %= p
  }
  Write(P)
}

