func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	n := r.nextInt()
	r.Scan(false)
	c := len(r.nextString())
	n += c
	MOD := pow(10, 9, 0) + 7

	f := make([]int, n+1)
	f25 := make([]int, n+1)
	f26 := make([]int, n+1)
	{
		f[0] = 1
		f25[0] = 1
		f26[0] = 1
		for i, end := 1, len(f); i < end; i++ {
			f[i] = f[i-1] * i % MOD
			f25[i] = f25[i-1] * 25 % MOD
			f26[i] = f26[i-1] * 26 % MOD
		}

	}

	ans := 0

	for i := c; i <= n; i++ {
		ans = (ans + f25[i-c]*f26[n-i]%MOD*(f[i-1]*pow(f[c-1], MOD-2, MOD)%MOD*pow(f[i-c], MOD-2, MOD)%MOD)) % MOD
	}
	fmt.Fprintln(stdout, ans)
}

