func ModCombi(n, k int) int {
	if n < k || n < 0 || k < 0 {
		return 0
	}
	return fact[n] * (finv[k] * finv[n-k] % Mod) % Mod
}

var fact, finv, inv []int

func InitModCombi(max int) {
	fact, finv, inv = make([]int, max), make([]int, max), make([]int, max)
	fact[0], fact[1], finv[0], finv[1], inv[1] = 1, 1, 1, 1, 1
	for i := 2; i < max; i++ {
		fact[i] = fact[i-1] * i % Mod
		inv[i] = Mod - inv[Mod%i]*(Mod/i)%Mod
		finv[i] = finv[i-1] * inv[i] % Mod
	}
}

