const N = 1_000_000_007
const MAX = 2_000_001

var fac, finv, inv []int
var pow25, pow26 []int

func main() {
	sc := NewScanner()

	k := sc.ReadInt()
	s := sc.ReadString()

	fac = make([]int, MAX)
	fac[0] = 1
	fac[1] = 1
	finv = make([]int, MAX)
	finv[0] = 1
	finv[1] = 1
	inv = make([]int, MAX)
	inv[1] = 1
	for i := 2; i < MAX; i++ {
		fac[i] = fac[i-1] * i % N
		inv[i] = N - inv[N%i]*(N/i)%N
		finv[i] = finv[i-1] * inv[i] % N
	}

	pow25 = make([]int, MAX)
	pow25[0] = 1
	pow26 = make([]int, MAX)
	pow26[0] = 1
	for i := 1; i < MAX; i++ {
		pow25[i] = pow25[i-1] * 25 % N
		pow26[i] = pow26[i-1] * 26 % N
	}

	ans := 0
	for m := 0; m <= k; m++ {
		mAns := Combi(len(s)+m-1, m)
		mAns = mAns * pow25[m] % N
		mAns = mAns * pow26[k-m] % N
		ans = (ans + mAns) % N
	}
	fmt.Println(ans)
}

func Combi(n, k int) int {
	if n < k {
		return 0
	}
	if n < 0 || k < 0 {
		return 0
	}
	return fac[n] * (finv[k] * finv[n-k] % N) % N
}

