	b[0] = 1
	for i := 1; i < n; i++ {
		a[i] = a[i-1] * 25 % mod
		b[i] = b[i-1] * 26 % mod
	}

	for i := 0; i < n; i++ {
		if i < len(s)-1 {
			continue
		}
		ans += comb(i, len(s)-1) * a[i-len(s)+1] % mod * b[n-i-1] % mod

		ans %= mod
	}

	fmt.Fprintln(wr, ans)
}

const mod = 1000000007

var fac, ifac, inv []int

func combInit(n int) {
	fac = make([]int, n+1)
	ifac = make([]int, n+1)
	inv = make([]int, n+1)

	fac[0], fac[1] = 1, 1
	ifac[0], ifac[1] = 1, 1
	inv[1] = 1

	for i := 1; i < n; i++ {
		fac[i+1] = fac[i] * (i + 1) % mod
		inv[i+1] = mod - inv[mod%(i+1)]*(mod/(i+1))%mod
		ifac[i+1] = ifac[i] * inv[i+1] % mod
	}
}

func comb(a, b int) int { return (fac[a] * ifac[b] % mod) * ifac[a-b] % mod }
func perm(a, b int) int { return fac[a] * ifac[a-b] % mod }

func mpow(a, n int) int {
	res := 1
	for n > 0 {
		if n&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		n >>= 1
	}
	return res
}

