func main() {
	const cmax = int(2e6 + 1)
	fac = make([]int, cmax)
	ifac = make([]int, cmax)
	inv := make([]int, cmax)
	fac[0], fac[1] = 1, 1
	ifac[0], ifac[1] = 1, 1
	inv[0], inv[1] = 1, 1
	for i := 2; i < cmax; i++ {
		fac[i] = (fac[i-1] * i) % mod
		inv[i] = (mod - inv[mod%i]*(mod/i)) % mod
		if inv[i] < 0 {
			inv[i] += mod
		}
		ifac[i] = (ifac[i-1] * inv[i]) % mod
	}

	var k int
	fmt.Scan(&k)
	var s string
	fmt.Scan(&s)
	n := len(s)
	sum := 1
	for i := 1; i <= k+n; i++ {
		sum *= 26
		sum %= mod
	}
	var isum int
	for i := 0; i < n; i++ {
		a := comb(k+n, i) * modpow(25, k+n-i)
		isum += a
		isum %= mod
	}

	ans := (sum - isum) % mod
	if ans < 0 {
		ans += mod
	}
	fmt.Println(ans)
}

func comb(n, r int) int {
	if r > n {
		return 0
	} else if r == 0 || r == n {
		return 1
	}
	t := (ifac[n-r] * ifac[r]) % mod
	return (t * fac[n]) % mod
}

func modpow(a, n int) int {
	res := 1
	for n > 0 {
		if n&1 > 0 {
			res *= a
			res %= mod
		}
		a = a * a % mod
		n >>= 1
	}
	return res
}

