	for i := 1; i <= k; i++ {
		p25[i] = p25[i-1] * 25
		p25[i] %= mod
		p26[i] = p26[i-1] * 26
		p26[i] %= mod
	}
	c := combmod(n+k-1, n-1)
	for i := 0; i <= k; i++ {
		x := c
		x *= p26[i]
		x %= mod
		x *= p25[k-i]
		x %= mod
		a += x
		a %= mod
		if i < k {
			c *= powmod(n+k-i-1, mod-2)
			c %= mod
			c *= k - i
			c %= mod
		}
	}
	fmt.Println(a)
	return nil
