    for (var a = mod, u = 0, v = 1, t; b; v = t)
      (t = (a / b) | 0),
        (a -= t * b),
        (u -= t * v),
        (t = a),
        (a = b),
        (b = t),
        (t = u),
        (u = v)
    u %= mod
    return u < 0 ? u + mod : u
  }
  const fset = (n: number) => {
    fac.length = n + 1
    fac[0] = fac[1] = 1
    for (let i = 2; i <= n; ) {
      fac[i] = mul(fac[i - 1], i++)
    }
    finv.length = n + 1
    finv[0] = finv[1] = 1
    finv[n] = inv(fac[n])
    for (let i = n; 2 < i; ) {
      finv[i - 1] = mul(finv[i], i--)
    }
  }
  const ncr = (n: number, r: number) => mul(fac[n], finv[r], finv[n - r])

  outs.push(main())

  console.log(
    outs
      .map((line) => (typeof line === 'object' ? line.join(' ') : String(line)))
      .join('\n')
  )
}

