def build_factorial(max_value):
    fact = [1]
    for i in range(1, max_value + 1):
        fact.append(fact[-1] * i % M)

    finv = [fast_pow(fact[-1], M - 2, M)]
    for i in range(max_value, 0, -1):
        finv.append(finv[-1] * i % M)
    finv.reverse()

    return fact, finv

