def memorize(f):
    dic = {}
    def main(*args):
        if args not in dic:
            dic[args] = f(*args)
        return dic[args]
    return main

@memorize
def fpow(x, n):
    ret = 1
    tmp = x
    while n:
        if n & 1:
            ret = ret * tmp % mod
        tmp = tmp * tmp % mod
        n >>= 1
    return ret

@memorize
def inv(x):
    return fpow(x, mod - 2)

@memorize
def fact(x):
    if x == 0:
        return 1
    return fact(x - 1) * x % mod

@memorize
def C(n, m):
    return fact(n) * inv(fact(m)) * inv(fact(n - m)) % mod

