fn main() {
    input! {
        k: usize,
        s: chars,
    }
    let n = s.len();

    let mut ans = 0;
    let mut v25 = vec![1; k + 1];
    let mut v26 = vec![1; k + 1];
    // let mut cv = vec![1;k+1];
    let mut inv = vec![1; n + k + 3];
    let mut fact = vec![1; n + k + 3];
    let mut factinv = vec![1; n + k + 3];
    for i in 1..=k {
        v25[i] = 25 * v25[i - 1] % MOD_P;
        v26[i] = 26 * v26[i - 1] % MOD_P;
    }
    for i in 1..=(n + k + 2) {
        fact[i] = fact[i - 1] * i % MOD_P;
        factinv[i] = factinv[i - 1] * mod_pow(i, MOD_P - 2) % MOD_P;
        inv[i] = fact[i - 1] * factinv[i];
    }
    for last in 0..=k {
        let rest = k - last;
        // nCr = n! / (r! (n-r)!) = n! (r!)^(p-2) ((n-r)!)^(p-2)
        let c = fact[n + rest - 1] * factinv[rest] % MOD_P * factinv[n - 1] % MOD_P; //comb_wrap(n + rest - 1, rest);
        ans += v26[last] * v25[rest] % MOD_P * c % MOD_P;
        ans %= MOD_P;
    }
    println!("{}", ans);
}

