impl ModU32 {
    pub fn new(n: u32) -> ModU32 {
        ModU32(n % MOD)
    }
    pub fn zero() -> ModU32 {
        ModU32(0)
    }
    pub fn one() -> ModU32 {
        ModU32(1)
    }
    pub fn pow(self, mut n: u32) -> ModU32 {
        let mut t = ModU32::one();
        let mut s = self;
        while n > 0 {
            if n & 1 == 1 {
                t *= s;
            }
            s *= s;
            n >>= 1;
        }
        t
    }
    pub fn inv(self) -> ModU32 {
        assert!(self.0 > 0);
        self.pow(MOD - 2)
    }
}

struct Combination {
    fact: Vec<ModU32>,
    fact_inv: Vec<ModU32>,
}

impl Combination {
    pub fn new(n: usize) -> Self {
        let mut fact = vec![ModU32::one(); n + 1];
        let mut fact_inv = vec![ModU32::one(); n + 1];
        for i in 2..(n + 1) {
            fact[i] = fact[i - 1] * ModU32(i as u32);
        }
        fact_inv[n] = fact[n].inv();
        for i in (1..n).rev() {
            fact_inv[i] = fact_inv[i + 1] * ModU32((i + 1) as u32);
        }
        Self { fact,fact_inv }
    }
    pub fn eval(&self, n: usize, k: usize) -> ModU32 {
        if k > n {
            return ModU32::zero();
        }
        self.fact[n] * self.fact_inv[k] * self.fact_inv[n - k]
    }
}

#[fastout]
fn main() {
    input! {
        k:usize,
        s: String
    }
    let n = s.len();
    let cmb = Combination::new(n + k);
    let rad = ModU32(26);
    let mut ans = ModU32::zero();
    for i in 0..=k {
        ans += rad.pow(i as u32)
            * cmb.eval(k - i + n - 1, n - 1)
            * (rad - ModU32::one()).pow((k - i) as u32);
    }
    println!("{}", ans);
}

