fn main() {
    input! {
        k:i64,
        s:Chars,
    }
    let n = s.len();
    let modulo = 1e+9 as i64 + 7;
    let comb = CombinationMod::new(n + k as usize, modulo);
    let n = n as i64;
    let ans = (0..=k)
        .map(|i| {
            let mut res = 1;
            res = res * modpow(25, k - i, modulo) % modulo;
            res = res * modpow(26, i, modulo) % modulo;
            res = res * comb.query(n + k - i - 1, n - 1) % modulo;
