fn dijkstra2(X:usize, Y:usize, g:&Vec<Vec<char>>, k:usize)->Vec<Vec<Vec<(i64, i64)>>>{
    let mut dist = vec![vec![vec![(INF, INF);g[0].len()];g.len()];4];
    dist[0][X][Y] = (0, 0);
    dist[1][X][Y] = (0, 0);
    dist[2][X][Y] = (0, 0);
    dist[3][X][Y] = (0, 0);
    let mut h = BinaryHeap::new();
    h.push(((0, 0), 0, X, Y));
    h.push(((0, 0), 1, X, Y));
    h.push(((0, 0), 2, X, Y));
    h.push(((0, 0), 3, X, Y));
    let dx = vec![0, 0, 1, -1];
    let dy = vec![1, -1, 0, 0];
    while(h.len() != 0){
        let mut t = h.pop().unwrap();
        let mut a = (t.0).0 * -1;
        let mut b = (t.0).1 * -1;
        let mut s = t.1;
        let mut x = t.2;
        let mut y = t.3;
        if dist[s][x][y]<(a, b){
            continue;
        }
        for i in 0..4{
            let mut na = a;
            let mut nb = b;
            if i == s{
                nb +=1;
                if nb == k as i64{
                    na+=1;
                    nb = 0;
                }
            }
            else{
                if nb != 0{
                    na +=1;
                    nb = 0;
                }
                nb+=1;
                if nb == k as i64{
                    na +=1;
                    nb = 0;
                }
            }
            let mut nx = x as i64 + dx[i];
            let mut ny = y as i64 + dy[i];
            if 0<=nx && nx<g.len() as i64 && 0<=ny && ny <g[0].len() as i64{
                let mut nx = nx as usize;
                let mut ny = ny as usize;
                if g[nx][ny] == '@'{
                    continue;
                }

                if dist[i][nx][ny] > (na, nb){
                    dist[i][nx][ny] = (na, nb);
                    h.push(((na*-1, nb*-1), i, nx, ny));
                }
            }
        }
    }
    dist


}
