fn mypow(a: u64, b: u64, md: u64) -> u64 {
    if b == 0 {
        1
    } else {
        let tmp = mypow(a, b / 2, md);
        if b % 2 == 1 {
            (((tmp * tmp) % md) * a) % md
        } else {
            (tmp * tmp) % md
        }
    }
}

