    let mut fact = vec![1 as u64; max_n];
    let mut inv = vec![1 as u64; max_n];
    fact[0] = 1;
    for i in 2..max_n {
        fact[i] = fact[i - 1] * i as u64 % md;
        inv[i] = mypow(fact[i], md - 2, md);
    }
    let mut ans: u64 = 1;
    for _ in 0..n {
