fn binom(n: ModInt, k: ModInt) -> ModInt {
    if k.0 == 0 {
        ModInt(1, n.1)
    } else if n.0 < k.0 * 2 {
        binom(n, n - k)
    } else {
        let mut c = ModInt(1, n.1);
        for i in 0..k.0 {
            c *= n - i;
            c /= k - i;
        }
        c
    }
}

/// x = binom(n, k) => binom(n, k+1)
fn binom_increment(x: ModInt, n: i64, k: i64) -> ModInt {
    x * (n - k) / (k + 1)
}

