    let mut ans = ModInt(0);
    for i in 0..=K {
        ans += ModInt(26).pow(K-i) * com.fac[N-1+i] * com.finv[N-1] * com.finv[i] * ModInt(25).pow(i);
    }
    println!("{}", ans);
}

