#[derive(Copy, Clone, Debug, PartialEq)]
struct ModInt (i64);

impl ModInt {
    fn new(value: i64) -> Self {
        ModInt(value % MOD)
    }

    /// a を (MOD - 2) 乗した余りを求める
    /// MOD - 2: 111011100110101100101000000101
    fn resiprocal(&self) -> Self {
        let mut v_res = [ModInt::new(0); 30];

        v_res[0] = self.clone();
        for i in 1..30 {
            v_res[i] = v_res[i - 1] * v_res[i - 1]
        }
        let mut prod = ModInt::new(1);
        for &i in [0, 2, 9, 11, 14, 15, 17, 19, 20, 23, 24, 25, 27, 28, 29].iter() {
            prod = prod * v_res[i]
        }
        prod
    }

    fn pow(&self, num: u32) -> Self {
        let mut res = ModInt::new(1);
        let mut num = num;
        let mut beki = *self;
        while num > 0 {
            if num % 2 == 1 {
                res = res * beki;
            }
            beki = beki * beki;
            num = num >> 1;
        }
        res
    }
}

impl ops::Add for ModInt {
    type Output = Self;
    fn add(self, rhs: ModInt) -> Self::Output {
        ModInt::new(self.0 + rhs.0)
    }
}

impl iter::Sum for ModInt {
    fn sum<I: Iterator<Item = ModInt>>(iter: I) -> Self {
        let mut total = ModInt::new(0);
        for i in iter {
            total = total + i
        }
        total
    }
}

impl ops::Sub for ModInt {
    type Output = Self;
    fn sub(self, rhs: ModInt) -> Self::Output {
        ModInt::new(self.0 - rhs.0)
    }
}

impl ops::Mul for ModInt {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self::Output {
        ModInt::new(self.0 * rhs.0)
    }
}

impl ops::Div for ModInt {
    type Output = Self;
    fn div(self, rhs: Self) -> Self::Output {
        self * rhs.resiprocal()
    }
}

