static mut FACTRM_M: [u32; 1000001] = [MODC as u32; 1000001];
fn factrm(k: u64) -> u64 {
    unsafe {
        if FACTRM_M[k as usize] == MODC as u32 {
            let mut r = 1;
            if k > 1 {
                for i in 2..(k+1) {
                    r *= i;
                    r %= MODC;
                }
            }
            r = powm(r, MODC - 2);
            FACTRM_M[k as usize] = r as u32;
