    segb:Vec<i64>,
}
impl stTree
    {


        pub fn new(n_:usize)->Self{
            let mut n = 1;
            while(n<n_){n*=2;}
            stTree{n: n, sega:vec![0; 2*n-1], segb:vec![0;2*n-1]}
        }
        pub fn update(&mut self, a:usize, b:usize, x:i64, k:usize, l:usize, r:usize){
            if (a <= l && r <= b){ 
                self.sega[k] += x; 
                return;
            }
            self.update(a, b, x, k * 2 + 1, l, (l + r) / 2); 
            self.update(a, b, x, k * 2 + 2, (l + r) / 2, r); 
            self.segb[k] = cmp::max(self.segb[k * 2 + 1] + self.sega[k * 2 + 1], self.segb[k * 2 + 2] + self.sega[k * 2 + 2]);
        }
        pub fn query(&self, a:usize, b:usize, k:usize, l:usize, r:usize) -> i64{
            if r<=a || b<=l{return 0;}
            if a<=l && r<=b{return self.sega[k]+self.segb[k];}
            else{
                let mut vl = self.query(a, b, k*2+1, l, (l+r)/2);
                let mut vr = self.query(a, b, k*2+2, (l+r)/2, r);
                return cmp::max(vl, vr)+self.sega[k];
            }
        }
    }
