impl cumulativeSum2{
    fn new(data:&Vec<Vec<i64>>)->cumulativeSum2{
        cumulativeSum2{ data:data.clone()}
    }
    fn build(&mut self){
        for i in 1..self.data.len(){
            for j in 1..self.data[i].len(){
                self.data[i][j] += self.data[i][j - 1] + self.data[i - 1][j] - self.data[i - 1][j - 1];
            }
        }

    }
    fn query(&self, sx:usize, sy:usize, gx:usize, gy:usize)->i64
    {
        //[sx, gx) [sy, gy]
        return (self.data[gx][gy] - self.data[sx][gy] - self.data[gx][sy] + self.data[sx][sy]);
    }


