struct Comb {
    div: usize,
    g1: Vec<usize>,
    g2: Vec<usize>,
}
impl Comb {
    #[allow(dead_code)]
    fn new(nmax: usize) -> Self {
        let mut g1 = vec![1; nmax + 1];
        let mut g2 = vec![1; nmax + 1];
        let mut inv = vec![0; nmax + 1];
        inv[1] = 1;
        let div = 1000000007;
        for i in 2..(nmax + 1) {
            g1[i] = g1[i - 1] * i % div;
            inv[i] = div - (inv[div % i] * (div / i)) % div;
            g2[i] = (g2[i - 1] * inv[i]) % div;
        }
        Comb {
            div: div,
            g1: g1,
            g2: g2,
        }
    }
    #[allow(dead_code)]
    fn compute(&self, n: usize, k: usize) -> usize {
        (((self.g1[n] * self.g2[k]) % self.div) * self.g2[n - k]) % self.div
    }
    #[allow(dead_code)]
    fn compute_dupc(&self, n: usize, k: usize) -> usize {
        self.compute(n + k - 1, n - 1)
    }
    #[allow(dead_code)]
    fn compuute_perm(&self, n: usize, k: usize) -> usize {
        (self.g1[n] * self.g2[n - k]) % self.div
    }
}

