    }

    let powm = |mut x,mut k| {
        let mut res = 1;
        while k>0 {
            if k&1==1 {
                res = res*x%MOD;
            }
            k>>=1;
            x=x*x%MOD;
        }
        res
    };
    let mod_inv = |x| {
        powm(x,MOD-2)
    };
    let comb = |n,k| {
        fact[n] * mod_inv(fact[n-k]) %MOD * mod_inv(fact[k])%MOD
    };
    for i in 0..k {
