const MOD: usize = 1e9 as usize + 7;

#[derive(Default)]
//NOTE
//declare variables to reduce the number of parameters for dp and dfs etc.
struct Solver {}

impl Solver {
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let k: usize = scn.read();
        let s = scn.chars();
        let n = s.len();
        let mod_util = ModUtil::new(2000010, MOD);
        let mut result = 0;
        for i in 0..=k {
            let c = mod_util.combination(i + n - 1, n - 1);
            let a = ModUtil::mod_pow(25, i, MOD);
            let b = ModUtil::mod_pow(26, k - i, MOD);
            result += a * c % MOD * b % MOD;
            result %= MOD;
        }
