static MODC: u64 = 1000000007;

fn powm (xx: u64, yy: u64) -> u64 {
    let mut x = xx;
    let mut y = yy;
    let mut result = 1;
    while y > 0 {
        if y & 1 != 0 {
            result *= x;
            result %= MODC;
        }
        x *= x;
        x %= MODC;
        y >>= 1;
    }
    result
}
fn combm (n: u64, k: u64) -> u64 {
    let mut x = n;
    let mut y = k;
    let mut result = 1;
    for _ in 0..k {
        result *= x * powm(y, MODC - 2) % MODC;
        result %= MODC;
        x -= 1;
        y -= 1;
    }
    result
}

