    let mut comb = 1;
    for i in 0..(k + 1) {
        // println!("{}C{} * 25 ^ {} * 26 ^ {}", i+n-1, n-1, i, k-i);
        // println!("= {}", combination(i + n - 1, n - 1) % MOD * binary_power(25, i) % MOD * binary_power(26, k - i) % MOD);
        ans += comb % MOD * binary_power(25, i) % MOD * binary_power(26, k - i) % MOD;
        // println!("{}", i+k);
        comb *= (i + n) % MOD;
        comb /= (i + n - 2) % MOD;
        ans %= MOD;
    }
    // println!("{}", combination(1, 0));
    println!("{}", ans - 1);
}

