fn comb(n: u64, r: u64, fact: &Vec<u64>) -> u64{
    fact[n as usize]*inv(fact[r as usize])%MD *inv(fact[(n-r) as usize])%MD
}

fn inv(n: u64) -> u64{
    pow(n, MD-2)
}

fn pow(mut x: u64, mut y: u64) -> u64{
    let mut res = 1;
    while y>0 {
        if y&1==1 { res = res*x%MD; }
        x = x*x%MD;
        y >>= 1;
    }
