const MODC: u64 = 1000000007;

fn powm (xx: u64, yy: u64) -> u64 {
    let mut x = xx;
    let mut y = yy;
    let mut result = 1;
    while y > 0 {
        if y & 1 != 0 {
            result *= x;
            result %= MODC;
        }
        x *= x;
        x %= MODC;
        y >>= 1;
    }
    result
}
struct Fact {
    mm: Vec<u32>,
    iv: Vec<u32>,
}
impl Fact {
    fn new() -> Fact {
        Fact {
            mm: vec![1],      // idx!
            iv: vec![1],     // 1 / idx!
        }

    }
    fn fact(&mut self, x: u64) -> u64 {
        if x < self.mm.len() as u64 { self.mm[x as usize] as u64 }
        else {
            let len = self.mm.len();
            let mut n = self.mm[len-1] as u64;
            for i in (len as u64)..(x + 1) {
                n = n * i % MODC;
                self.mm.push(n as u32);
            }
            n
        }
    } 
    fn facti(&mut self, x: u64) -> u64 {
        if x < self.iv.len() as u64 { self.iv[x as usize] as u64 }
        else {
            let len = self.iv.len();
            let mut n: u64 = 0;
            for i in (len as u64)..(x + 1) {
                n = powm(self.fact(i), MODC - 2);
                self.iv.push(n as u32);
            }
            n
        }
    } 
    fn combm (&mut self, n: u64, k: u64) -> u64 {
        let mut result = self.fact(n);
        result = result * self.facti(n - k) % MODC;
        result * self.facti(k) % MODC
    }
}

