    let mut ans = 0;
    for i in 0..(k+1) {
        ans += powm(25, i) * powm(26, k - i) % MODC * f.combm(n + i - 1, n - 1) % MODC;
        if ans >= MODC {ans -= MODC};
    }
    println!("{}", ans);
}

