const M: i64 = 1_000_000_007;

fn exp(mut x: i64, mut e: i64) -> i64 {
    let mut ans = 1;
    while e > 0 {
        if e & 1 == 1 {
            ans = ans * x % M;
        }
        x = x * x % M;
        e >>= 1;
    }
    ans
}

// Gimmicky return type, I know
// But I wanted to try it
// I don't use (fac, inv) for anything else, really
fn build_ncr() -> impl Fn(usize, usize) -> i64 {
    const N: usize = 2_000_001;
    let mut f = vec![0; N];
    let mut inv = vec![0; N];
    f[0] = 1;
    for i in 1..N {
        f[i] = f[i-1] * i as i64 % M;
    }
    inv[N-1] = exp(f[N-1], M - 2);
    for i in (0..N-1).rev() {
        inv[i] = inv[i+1] * (i + 1) as i64 % M;
    }

    move |n, k| f[n] * inv[k] % M * inv[n - k] % M
}

fn main() -> Result<(), io::Error> {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = UnsafeScanner::new(stdin.lock());
    let mut out = BufWriter::new(stdout.lock());

    let ncr = build_ncr();

    let k: usize = scan.token();
    let n = scan.token::<String>().len();

    let mut ans = 0;
    for i in n..=n+k {
        let x = exp(25, (i - n) as i64);
        let y = exp(26, (n + k - i) as i64);
        let z = ncr(i - 1, n - 1);
        ans += x * y % M * z % M;
        if ans >= M { ans -= M; }
    }

    answer!(out, ans)
}

