const M: u64 = 1000_000_007;

fn main() {
    input! {
        k:u64,
        s:Chars
    }
    let n = s.len();
    // 最後の文字以降におく文字数をiとすると、
    // 文字のえらび方は、25.pow(k-i)*26.pow(i)
    // また、n-1 文字の挿入位置は (k-i+n-1 choose n-1)
    // n choose k = n*(n-1)*...*(n-k+1) /(k*...*1) なので、
    // あとは、各iについて、合計すればよい。
    let mut fact = vec![1u64; 2000010];
    let mut inv_fact = vec![1u64; 2000010];
    fact[0] = 1;
    for i in 0..2000005 {
        fact[i + 1] = fact[i] * ((i + 1) as u64) % M;
        inv_fact[i] = modInv(fact[i]);
    }
    let choose = |n, k| fact[n as usize] * inv_fact[n - k] % M * inv_fact[k] % M;
    let mut ans = 0u64;
    for i in 0..k + 1 {
        ans += choose(n + (k as usize) - (i as usize) - 1, n - 1) * modPow(25u64, k - i as u64) % M
            * modPow(26u64, i as u64)
            % M;
    }
    println!("{}", ans % M);
}
//fn choose(n: usize, k: usize, fact: &Vec<u64>, inv_fact: &Vec<u64>) -> u64 {
//    fact[n as usize] * inv_fact[n - k] % M * inv_fact[k] % M
//}
fn modPow(x: u64, a: u64) -> u64 {
    if a == 0 {
        1
    } else {
        if a == 1 {
            x
        } else {
            if a % 2 != 0 {
                (modPow(x, a - 1) * x) % M
            } else {
                let t = modPow(x, a / 2);
                t * t % M
            }
        }
    }
}
fn modInv(x: u64) -> u64 {
    modPow(x, M - 2)
}

