mod combination {
    use modular::*;

    pub struct Combination<T> {
        facts: Vec<T>,
        inv_facts: Vec<T>,
    }

    use std::fmt::Debug;
    impl<P: ModP + Copy + Debug> Combination<Modular<P>> {
        pub fn new(n: usize) -> Combination<Modular<P>> {
            let mut facts = vec![Modular::<P>::new(1)];
            for i in 1..n {
                let t = facts[i - 1];
                facts.push(t * Modular::<P>::new(i as u32));
            }
            let mut inv_facts = vec![];
            inv_facts.push(Modular::<P>::new(1) / facts[n - 1]);
            for i in (1..n - 1).rev() {
                let t = *inv_facts.last().unwrap();
                inv_facts.push(t * Modular::<P>::new((i + 1) as u32));
            }
            inv_facts.push(Modular::<P>::new(1));
            inv_facts.reverse();
            Combination {
                facts: facts,
                inv_facts: inv_facts,
            }
        }
        pub fn c(&self, n: usize, r: usize) -> Modular<P> {
            if n < r {
                Modular::<P>::new(0)
            } else {
                self.facts[n] * self.inv_facts[n - r] * self.inv_facts[r]
            }
        }
    }
}

