    let mut st: Vec<usize> = vec![0; n + m + 1];
    st[0] = 1;
    for i in 1..n + m + 1 {
        st[i] = st[i - 1] * i % d;
    }
    let sti: Vec<usize> = st.iter().map(|&x| inv_m(x, d)).collect();
    let mut ans = 0;
    for k in 0..n + 1 {
        ans = (ans + st[m + k - 1] * sti[k] % d * pow_m(25, k, d) % d * pow_m(26, n - k, d) % d) % d;
