    line.trim().parse().ok().unwrap()
}

fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn inverse_mod(n: u64) -> u64 {
    binary_power(n, MOD-2)
}  

fn combination(fact: &Vec<u64>, n: u64, m: u64) -> u64 {
    fact[n as usize] * inverse_mod(fact[(n-m) as usize]) %MOD * inverse_mod(fact[m as usize])%MOD
}

fn main() {
    let k: u64 = input();
    let s: String = input();
    let s: Vec<char> = s.chars().collect();
    let n = s.len() as u64;
    let mut fact: Vec<u64> = Vec::new();
    fact.push(1);
    for i in 1..n+k {
        fact.push(fact[i as usize - 1]*(i) % MOD);
    }

    let mut ans = 0;
    let mut comb = 1;
    for i in 0..(k + 1) {
        // println!("{}C{} * 25 ^ {} * 26 ^ {}", i+n-1, n-1, i, k-i);
        // println!("= {}", combination(i + n - 1, n - 1) % MOD * binary_power(25, i) % MOD * binary_power(26, k - i) % MOD);
        ans += combination(&fact, i + n - 1, n - 1) % MOD * binary_power(25, i) % MOD * binary_power(26, k - i) % MOD;
        ans %= MOD;

        comb = comb * (i + n + 2) % MOD * inverse_mod(n-1) % MOD;
    }
    // println!("{}", combination(1, 0));
    println!("{}", ans);
}
